INSERT INTO rule_sources (source_id, sanction, sport, title, url, edition, access, use_note, retrieved_on) VALUES
  ('ABCA-BR', 'coaching_resource', 'baseball', 'Coaches'' Corner: Better Baserunning in Youth Baseball (John M. Cissik, ABCA Inside Pitch)', 'https://www.abca.org/magazine/magazine/2023-6-November-December/Coaches_Corner_Better_Baserunning.aspx', 'Nov/Dec 2023', 'free_coaching_page', 'Coaching philosophy and practice plan: base running every practice, leads, going on the pitcher''s commitment, simple signs. No rule text.', DATE '2026-10-25'),
  ('AU-BR-DRILLS', 'coaching_resource', 'baseball', '4 Baseball Base Running Drills to Improve Speed & Game IQ (Emily Murphy, Athletes Untapped blog)', 'https://athletesuntapped.com/blog/baseball-base-running-drills-for-speed-and-game-iq/', 'published 2026-02-05', 'free_coaching_page', 'Drill ideas only: first step, rounding bases, read and react, sliding. No rule text.', DATE '2026-10-25'),
  ('BR-SIT-PRACTICE', 'coaching_resource', 'baseball', 'Base running Situations to Practice (practice sheet)', 'https://cdn1.sportngin.com/attachments/document/0113/6133/Base_running_Situations_to_Practice.pdf', 'undated; retrieved 2026-10-25', 'free_coaching_pdf', 'Strategy only: what a runner does by base, outs and type of batted ball. No rule text. The sheet names no author.', DATE '2026-10-25'),
  ('BRL-2026', 'babe_ruth_league', 'baseball', 'Babe Ruth League 2026 Baseball Rule Changes', 'https://www.baberuthleague.org/latest-rule-changes/2026-baseball-rule-changes', '2026 season', 'free_official_page', 'Facts only.', DATE '2026-10-22'),
  ('BRL-BAT', 'babe_ruth_league', 'both', 'Babe Ruth League Bat Rules', 'https://www.baberuthleague.org/bat-rules', 'retrieved 2026-10-22', 'free_official_page', 'Facts only.', DATE '2026-10-22'),
  ('BRL-BB-AGE', 'babe_ruth_league', 'baseball', 'Babe Ruth / Cal Ripken Baseball Age Chart', 'https://www.baberuthleague.org/league-resources/baseball-age-chart', '2027 season (calculator only)', 'free_official_page', 'The page has no cutoff text, only a birth-date calculator. Gap.', DATE '2026-10-22'),
  ('BRL-CHILDSAFE', 'babe_ruth_league', 'both', 'Babe Ruth League Child Abuse Risk Management Program', 'https://www.baberuthleague.org/sitemedia/BabeRuthLeagueChildAbuseRiskManagementProgram.pdf', 'undated', 'free_official_pdf', 'Out of scope for rulings. Catalog only, as the policy the app points to for safety questions.', DATE '2026-10-22'),
  ('BRL-CR', 'cal_ripken', 'baseball', 'Babe Ruth League: Cal Ripken Baseball overview', 'https://www.baberuthleague.org/cal-ripken-baseball', 'retrieved 2026-10-22', 'free_official_page', 'Divisions and ages only. No pitching numbers on the page.', DATE '2026-10-22'),
  ('BRL-CR-PITCHSHEET', 'cal_ripken', 'baseball', 'Cal Ripken Pitch Count Sheet', 'https://www.baberuthleague.org/sitemedia/Pitch%20Count%20Sheet%20CR.pdf', 'undated', 'free_official_pdf', 'Daily maximums are readable. The rest-day table didn''t extract cleanly, so it isn''t used.', DATE '2026-10-22'),
  ('BRL-FACILITY', 'babe_ruth_league', 'both', 'Babe Ruth League Facility Guide', 'https://www.baberuthleague.org/sitemedia/Babe%20Ruth%20Facility%20Guide%20TC2.pdf', 'undated, retrieved 2026-10-22', 'free_official_pdf', 'Field dimensions only.', DATE '2026-10-22'),
  ('BRL-LIGHTNING', 'babe_ruth_league', 'both', 'Babe Ruth League Guide to Emergency Weather and Lightning Safety', 'https://www.baberuthleague.org/sitemedia/Lightning%20Policy.pdf', 'undated, retrieved 2026-10-22', 'free_official_pdf', 'Safety facts only.', DATE '2026-10-22'),
  ('BRL-LLGUIDE-2026', 'babe_ruth_league', 'both', 'Babe Ruth League 2026 Local League Guide', 'https://www.baberuthleague.org/sitemedia/2026_BRL_LocalLeagueGuide.pdf', '2026', 'free_official_pdf', 'League administration. Catalog only; no playing rules loaded.', DATE '2026-10-22'),
  ('BRL-RULES-2026', 'babe_ruth_league', 'both', 'BRL 2026 Baseball / Softball Rules and Regulations (Human Kinetics)', 'https://coacheducation.humankinetics.com/collections/babe-ruth-league', '2026, paid ebook ($10 each)', 'purchased', 'Verification only if purchased. Never quoted or committed.', DATE '2026-10-22'),
  ('BRL-SAFE', 'babe_ruth_league', 'both', 'Babe Ruth League SAFE background check portal', 'https://safe.baberuthleague.org/#/background', 'live portal', 'free_official_page', 'Out of scope. Catalog only.', DATE '2026-10-22'),
  ('BRL-SB-2026', 'babe_ruth_league', 'softball', 'Babe Ruth League 2026 Softball Rule Changes', 'https://www.baberuthleague.org/latest-rule-changes/2026-softball-rule-changes', '2026 season', 'free_official_page', 'Facts only.', DATE '2026-10-22'),
  ('BRL-SB-AGE', 'babe_ruth_league', 'softball', 'Babe Ruth Softball Age Chart', 'https://www.baberuthleague.org/league-resources/softball-age-chart', '2026 season', 'free_official_page', 'Facts only.', DATE '2026-10-22'),
  ('BRL-TBALL', 'babe_ruth_league', 'baseball', 'USABat Tee Ball Sticker Program Overview', 'https://www.baberuthleague.org/sitemedia/USABat%20Tee%20Ball%20Sticker%20Program%20Overview.pdf', 'program effective 2018-01-01', 'free_official_pdf', 'Facts only.', DATE '2026-10-22'),
  ('BRL-USABAT-2015', 'babe_ruth_league', 'baseball', 'Batter Up archive: New bat specification testing', 'https://www.baberuthleague.org/batter-up-archive/articles/new-bat-specification-testing', '2015-09-28', 'free_official_article', 'Background only (USABat history). Outdated; not a current rule source.', DATE '2026-10-22'),
  ('BRL-WARMUP', 'babe_ruth_league', 'baseball', 'Babe Ruth League Pre-Game Defensive Warm-Up Routine', 'https://www.baberuthleague.org/sitemedia/PreGameDefensiveWarmUpRoutine.pdf', 'undated', 'free_official_pdf', 'Drill structure inspiration only. Write our own drills; don''t copy.', DATE '2026-10-22'),
  ('DIQ-SME', 'diq_coaching', 'both', 'Billy Goats GGUF coaching staff (youth coach, travel-ball parent and 4-year youth umpire)', 'https://github.com/seanrugg/diamondagentiq', '2026', 'team_sme', 'Experience-based coaching guidance written by the team. Not a rule; never cited as one.', DATE '2026-10-23'),
  ('JB-BAT-COACH', 'retailer', 'both', 'JustBats Bat Coach (guided bat finder)', 'https://www.justbats.com/bat-coach/', 'retrieved 2026-10-23', 'free_retailer_page', 'Catalog only: a 14-question shopping quiz. Point users to it; no facts taken.', DATE '2026-10-23'),
  ('JB-FAQ', 'retailer', 'both', 'JustBats: General bat questions', 'https://www.justbats.com/bat-resource-guide/frequently-asked-questions/', 'retrieved 2026-10-23', 'free_retailer_page', 'Retailer guide (JustBats), not a governing body. Selection, sizing and care tips in our own words; bat legality comes from the league or governing body source. Break-in advice differs from the resource guide (150-200 hits vs about 50 swings).', DATE '2026-10-23'),
  ('JB-GUIDE', 'retailer', 'both', 'JustBats Bat Resource Guide', 'https://www.justbats.com/bat-resource-guide/', 'retrieved 2026-10-23', 'free_retailer_page', 'Retailer guide (JustBats), not a governing body. Selection, sizing and care tips in our own words; bat legality comes from the league or governing body source. Drop ranges, materials, care. Its barrel-diameter figures didn''t render.', DATE '2026-10-23'),
  ('JB-SB-GOV', 'retailer', 'softball', 'JustBats: Softball bat governing bodies', 'https://www.justbats.com/bat-resource-guide/governing-bodies/', 'retrieved 2026-10-23', 'free_retailer_page', 'Retailer guide (JustBats), not a governing body. Selection, sizing and care tips in our own words; bat legality comes from the league or governing body source. Softball only; links to each body''s certified list.', DATE '2026-10-23'),
  ('JB-SIZING', 'retailer', 'both', 'JustBats: Bat sizing guide', 'https://www.justbats.com/bat-resource-guide/sizing-guide/', 'retrieved 2026-10-23', 'free_retailer_page', 'Catalog only: the length chart is an interactive widget with no numbers in the page.', DATE '2026-10-23'),
  ('JB-YOUTH-SELECT', 'retailer', 'baseball', 'JustBats: How to select a youth bat', 'https://www.justbats.com/bat-resource-guide/frequently-asked-questions/youth/howtoselect/', 'retrieved 2026-10-23', 'free_retailer_page', 'Retailer guide (JustBats), not a governing body. Selection, sizing and care tips in our own words; bat legality comes from the league or governing body source. Its drop-by-age figures conflict with its own stated range; not used as numbers.', DATE '2026-10-23'),
  ('LL-2026', 'little_league', 'both', 'Little League news: 2026 rule and regulation updates', 'https://www.littleleague.org/news/clarifications-and-enhancements-highlight-2026-little-league-rule-and-regulation-updates/', '2026-01-14', 'free_official_article', 'Facts only.', DATE '2026-10-22'),
  ('LL-AGE-BB-2026', 'little_league', 'baseball', '2026 Little League Baseball Age Chart', 'https://www.littleleague.org/downloads/2026-baseball-age-chart/', '2026', 'free_official_pdf', 'Facts only.', DATE '2026-10-22'),
  ('LL-AGE-BB-2027', 'little_league', 'baseball', '2027 Little League Baseball Age Chart', 'https://www.littleleague.org/downloads/2027-baseball-age-chart/', '2027', 'free_official_pdf', 'Facts only.', DATE '2026-10-22'),
  ('LL-AGE-CH-2026', 'little_league', 'baseball', '2026 Little League Challenger Age Chart', 'https://www.littleleague.org/downloads/2026-challenger-age-chart/', '2026', 'free_official_pdf', 'Facts only.', DATE '2026-10-22'),
  ('LL-AGE-CH-2027', 'little_league', 'baseball', '2027 Little League Challenger Age Chart', 'https://www.littleleague.org/downloads/2027-challenger-age-chart/', '2027', 'free_official_pdf', 'Facts only.', DATE '2026-10-22'),
  ('LL-AGE-SB-2026', 'little_league', 'softball', '2026 Little League Softball Age Chart', 'https://www.littleleague.org/downloads/2026-softball-age-chart/', '2026', 'free_official_pdf', 'Facts only.', DATE '2026-10-22'),
  ('LL-AGE-SB-2027', 'little_league', 'softball', '2027 Little League Softball Age Chart', 'https://www.littleleague.org/downloads/2027-softball-age-chart/', '2027', 'free_official_pdf', 'Facts only.', DATE '2026-10-22'),
  ('LL-APPX', 'little_league', 'both', 'Little League Rulebook Appendices (lightning, safety code, heat illness)', 'https://www.littleleague.org/playing-rules/appendices/', 'retrieved 2026-10-22', 'free_official_page', 'Catalog only. The page lists titles; the text is in the rulebook.', DATE '2026-10-22'),
  ('LL-BAT', 'little_league', 'both', 'Little League Bat Rules (Rule 1.10)', 'https://www.littleleague.org/playing-rules/bat-rules/', 'page updated 2026-07-07', 'free_official_page', 'Facts only (bat standards and sizes by division).', DATE '2026-10-22'),
  ('LL-BATINFO', 'little_league', 'baseball', 'Little League Bat Information (USABat/BBCOR by division)', 'https://www.littleleague.org/playing-rules/bat-information/', 'page updated 2026-07-07', 'free_official_page', 'Facts only.', DATE '2026-10-22'),
  ('LL-CHALLENGER-BUDDY', 'little_league', 'baseball', 'Game Play Guidelines for Challenger Buddies', 'https://www.littleleague.org/downloads/challenger-game-play-guidelines-buddies/', 'undated, retrieved 2026-10-22', 'free_official_pdf', 'Guidance, not playing rules. Use for coaching tone and adaptive-play suggestions.', DATE '2026-10-22'),
  ('LL-CHANGES-2026', 'little_league', 'both', 'Little League 2026 Rule Changes and Clarifications', 'https://www.littleleague.org/playing-rules/rule-changes/', '2026', 'free_official_page', 'Facts only.', DATE '2026-10-22'),
  ('LL-D-5070-field-conversion', 'little_league', 'baseball', 'Little League Converting a Little League field for Intermediate (50/70)', 'https://www.littleleague.org/downloads/5070-field-conversion/', 'retrieved 2026-10-22', 'free_official_pdf', 'Dimensions only.', DATE '2026-10-22'),
  ('LL-D-bat-decertification-marucci-cat5', 'little_league', 'baseball', 'Little League Memo: decertification of 33-inch Marucci CAT5 bat', 'https://www.littleleague.org/downloads/bat-decertification-marucci-cat5/', '2012-02-27', 'free_official_pdf', 'Facts only. Old, model-specific.', DATE '2026-10-22'),
  ('LL-D-bat-decertification-marucci-cat5squared-black', 'little_league', 'baseball', 'Little League Memo: decertification of Marucci CAT5 Squared 34 and Marucci Black 33/34 bats', 'https://www.littleleague.org/downloads/bat-decertification-marucci-cat5squared-black/', '2012-06-21', 'free_official_pdf', 'Facts only. Old, model-specific.', DATE '2026-10-22'),
  ('LL-D-coach-pitch-12-week-program', 'little_league', 'baseball', 'Little League Coach-Pitch 12-Week Program (Minor Division)', 'https://www.littleleague.org/downloads/coach-pitch-12-week-program/', '2015', 'free_official_pdf', 'Coaching curriculum: the source of age-appropriate progression and coaching principles. Write our own drills; never copy.', DATE '2026-10-22'),
  ('LL-D-helmet-manufacturer-letter', 'little_league', 'both', 'Little League Letter to helmet manufacturers on face protectors (C-flap) and NOCSAE', 'https://www.littleleague.org/downloads/helmet-manufacturer-letter/', '2018 (cites NOCSAE release of 2018-05-08)', 'free_official_pdf', 'Facts only.', DATE '2026-10-22'),
  ('LL-D-league-resource-guide', 'little_league', 'both', 'Little League Little League League Resource Guide', 'https://www.littleleague.org/downloads/league-resource-guide/', 'retrieved 2026-10-22', 'free_official_pdf', 'Facts only (protest committee, volunteer umpires).', DATE '2026-10-22'),
  ('LL-D-parent-code-conduct', 'little_league', 'both', 'Little League Sport Parent Code of Conduct (template)', 'https://www.littleleague.org/downloads/parent-code-conduct/', 'retrieved 2026-10-22', 'free_official_pdf', 'Facts and own-words summaries. Template that local leagues adopt; key for the de-escalation and channel guidance.', DATE '2026-10-22'),
  ('LL-D-pitching-eligibility-tracking-form', 'little_league', 'both', 'Little League Pitcher Eligibility Tracking Form', 'https://www.littleleague.org/downloads/pitching-eligibility-tracking-form/', 'retrieved 2026-10-22', 'free_official_pdf', 'Shows the fields leagues track (date, pitches, league age, eligible-again date). Good model for our pitch log.', DATE '2026-10-22'),
  ('LL-D-president-training-program', 'little_league', 'both', 'Little League Training Program for League Presidents', 'https://www.littleleague.org/downloads/president-training-program/', 'retrieved 2026-10-22', 'free_official_pdf', 'League administration. Catalog only.', DATE '2026-10-22'),
  ('LL-D-regulation-iid', 'little_league', 'both', 'Little League Report of Players Claimed under Regulation II(d) or II(a)', 'https://www.littleleague.org/downloads/regulation-iid/', 'retrieved 2026-10-22', 'free_official_pdf', 'Facts only. Form updated 2023-12-14.', DATE '2026-10-22'),
  ('LL-D-regulation-va-12-year-old-waiver', 'little_league', 'baseball', 'Little League Regulation V(a) waiver form: 12-year-old in Minor Division', 'https://www.littleleague.org/downloads/regulation-va-12-year-old-waiver/', 'retrieved 2026-10-22', 'free_official_pdf', 'Facts only. Form updated 2023-03-06.', DATE '2026-10-22'),
  ('LL-D-residency-school-attendance-eligibility-requirements', 'little_league', 'both', 'Little League Residency and School Attendance Eligibility Requirements', 'https://www.littleleague.org/downloads/residency-school-attendance-eligibility-requirements/', 'retrieved 2026-10-22', 'free_official_pdf', 'Facts only. 2026 season document dates.', DATE '2026-10-22');
