INSERT INTO rules_facts (fact_code, source_id, sport, sanction, division, age_min, age_max, edition, topic, fact_key, fact_value, unit, rule_ref, call_type, summary, source_url, verified, verified_by, retrieved_on, verify_note) VALUES
  ('F001', 'LL-PITCH', 'baseball', 'little_league', NULL, 6, 8, 'page modified 2026-02-11', 'pitch_count', 'daily_max_pitches', '50', 'pitches', 'Regulation VI(c)', 'rule', 'Little League baseball pitchers aged 6-8 may throw at most 50 pitches in a day.', 'https://www.littleleague.org/playing-rules/pitch-count/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F002', 'LL-PITCH', 'baseball', 'little_league', NULL, 9, 10, 'page modified 2026-02-11', 'pitch_count', 'daily_max_pitches', '75', 'pitches', 'Regulation VI(c)', 'rule', 'Little League baseball pitchers aged 9-10 may throw at most 75 pitches in a day.', 'https://www.littleleague.org/playing-rules/pitch-count/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F003', 'LL-PITCH', 'baseball', 'little_league', NULL, 11, 12, 'page modified 2026-02-11', 'pitch_count', 'daily_max_pitches', '85', 'pitches', 'Regulation VI(c)', 'rule', 'Little League baseball pitchers aged 11-12 may throw at most 85 pitches in a day.', 'https://www.littleleague.org/playing-rules/pitch-count/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F004', 'LL-PITCH', 'baseball', 'little_league', NULL, 13, 16, 'page modified 2026-02-11', 'pitch_count', 'daily_max_pitches', '95', 'pitches', 'Regulation VI(c)', 'rule', 'Little League baseball pitchers aged 13-16 may throw at most 95 pitches in a day.', 'https://www.littleleague.org/playing-rules/pitch-count/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F005', 'LL-PITCH', 'baseball', 'little_league', NULL, 6, 16, 'page modified 2026-02-11', 'pitch_count', 'complete_batter_at_limit', 'true', NULL, 'Regulation VI(c)', 'rule', 'A pitcher who hits the daily limit mid at-bat may finish that batter. The appearance ends when the batter reaches base or is put out, or the half-inning or game ends. A new batter can''t be started once the limit is reached.', 'https://www.littleleague.org/playing-rules/pitch-count/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F006', 'LL-PITCH', 'baseball', 'little_league', NULL, 6, 16, 'page modified 2026-02-11', 'pitch_rest', 'three_consecutive_days', 'false', NULL, 'Regulation VI, Note 1', 'rule', 'A Little League pitcher may never pitch on three consecutive days, whatever the pitch counts.', 'https://www.littleleague.org/playing-rules/pitch-count/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F007', 'LL-PITCH', 'baseball', 'little_league', NULL, 6, 16, 'page modified 2026-02-11', 'pitch_rest', 'threshold_reached_mid_batter', 'see note', NULL, 'Regulation VI, Note', 'rule', 'When a pitcher crosses a rest-day threshold while facing a batter, a note in Regulation VI decides which threshold sets the rest days.', 'https://www.littleleague.org/playing-rules/pitch-count/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: CHECK EXACT WORDING. The automatic summary was ambiguous about whether rest follows the threshold at the start or the end of that at-bat. Verify before RulesAgent relies on it.'),
  ('F008', 'LL-PITCH', 'baseball', 'little_league', NULL, 6, 16, 'page modified 2026-02-11', 'catcher', 'catch4_cannot_pitch', '4', 'innings', 'Regulation VI(a)', 'rule', 'A player who catches four or more innings in a game can''t pitch on that calendar day. One pitch thrown in the fourth inning counts as catching that inning.', 'https://www.littleleague.org/playing-rules/pitch-count/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F009', 'LL-PITCH', 'baseball', 'little_league', NULL, 6, 14, 'page modified 2026-02-11', 'catcher', 'pitched_cannot_catch', '21', 'pitches', 'Regulation VI(a)', 'rule', 'A player aged 14 or under who catches three innings or fewer, then throws 21 or more pitches that day, can''t go back to catching that day.', 'https://www.littleleague.org/playing-rules/pitch-count/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Check whether a 40/41-pitch rule still exists. The summary mentioned one, but it may be outdated text.'),
  ('F010', 'LL-PITCH', 'baseball', 'little_league', NULL, 15, 16, 'page modified 2026-02-11', 'catcher', 'pitched_cannot_catch', '31', 'pitches', 'Regulation VI(a)', 'rule', 'The same restriction for 15-16 year olds starts at 31 pitches.', 'https://www.littleleague.org/playing-rules/pitch-count/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F011', 'LL-PITCH', 'softball', 'little_league', 'Minors/Majors', NULL, NULL, 'page modified 2026-02-11', 'pitching_innings', 'daily_max_innings', '12', 'innings', 'Regulation VI (Softball)', 'rule', 'Little League softball has no pitch count. In Minors and Majors, a pitcher may pitch up to 12 innings per calendar day. One pitch in an inning counts as a full inning.', 'https://www.littleleague.org/playing-rules/pitch-count/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F012', 'LL-PITCH', 'softball', 'little_league', 'Minors/Majors', NULL, NULL, 'page modified 2026-02-11', 'pitching_innings', 'rest_after_7_innings', '1', 'days', 'Regulation VI (Softball)', 'rule', 'A Little League softball pitcher in Minors or Majors who pitches 7 or more innings in a day needs one calendar day of rest.', 'https://www.littleleague.org/playing-rules/pitch-count/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F013', 'LL-PITCH', 'softball', 'little_league', 'Junior/Senior', NULL, NULL, 'page modified 2026-02-11', 'pitching_innings', 'restrictions', 'none', NULL, 'Regulation VI (Softball)', 'rule', 'Little League Junior and Senior softball have no pitching restrictions, though local leagues and districts may add limits.', 'https://www.littleleague.org/playing-rules/pitch-count/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F014', 'LL-PROTEST', 'both', 'little_league', 'regular season', NULL, NULL, 'page modified 2018-11-15', 'protest', 'protestable', 'rule interpretation; ineligible player', NULL, 'Rule 4.19', 'rule', 'In Little League, a game can be protested over a playing-rule interpretation or the use of an ineligible player. Umpire judgment calls can''t be protested.', 'https://www.littleleague.org/university/articles/local-league-protest-committee/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F015', 'LL-PROTEST', 'both', 'little_league', 'regular season', NULL, NULL, 'page modified 2018-11-15', 'judgment', 'judgment_not_protestable', 'true', NULL, 'Rule 4.19', 'judgment', 'Calls that rest on the umpire''s judgment, such as balls and strikes or safe and out, are not protestable in Little League.', 'https://www.littleleague.org/university/articles/local-league-protest-committee/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F016', 'LL-RULEDIFF', 'both', 'little_league', 'regular season', NULL, NULL, 'page modified 2024-05-07', 'protest', 'timing_regular_season', 'before next pitch or play', NULL, 'Rule 4.19(c)(1)', 'rule', 'In the regular season, the manager must tell the umpire right away, before the next pitch or play, that the game is under protest. An ineligible-player protest may be made until the umpires leave the field. A written protest goes to the League President within 24 hours.', 'https://www.littleleague.org/university/articles/regular-season-to-tournament-rule-differences/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F017', 'LL-RULEDIFF', 'both', 'little_league', 'regular season', NULL, NULL, 'page modified 2024-05-07', 'protest', 'decided_by', 'local protest committee', NULL, 'Rule 4.19(f)', 'rule', 'A league committee decides regular-season protests: the League President, Player Agent, Umpire-in-Chief, and other officers who aren''t managers or umpires. If a protest is upheld, play resumes from the exact point of the infraction.', 'https://www.littleleague.org/university/articles/regular-season-to-tournament-rule-differences/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F018', 'LL-RULEDIFF', 'both', 'little_league', 'tournament', NULL, NULL, 'page modified 2024-05-07', 'protest', 'tournament_procedure', 'verbal to UIC at once; escalates', NULL, 'Tournament replacement for Rule 4.19', 'rule', 'In tournament play, the protest is made verbally to the Umpire-in-Chief at once. It escalates to the Tournament Director or District Administrator, then Regional Headquarters, and finally the International Tournament Committee, whose decision is final. Umpires and tournament officials can''t declare a forfeit.', 'https://www.littleleague.org/university/articles/regular-season-to-tournament-rule-differences/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F019', 'LL-RULEDIFF', 'both', 'little_league', NULL, NULL, NULL, 'page modified 2024-05-07', 'courtesy_runner', 'pitcher_catcher_two_outs', 'true', NULL, 'Rule 3.04; Tournament Rule 3', 'rule', 'A courtesy runner may run for the pitcher or catcher with two outs. In the regular season this is a local-league option. In tournaments it''s allowed for every team. With a continuous batting order, the runner is the player who made the last out.', 'https://www.littleleague.org/university/articles/regular-season-to-tournament-rule-differences/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F020', 'LL-2026', 'both', 'little_league', NULL, NULL, NULL, '2026-01-14', 'courtesy_runner', 'before_mandatory_play_2026', 'true', NULL, '2026 update (article gives no number)', 'rule', 'New for 2026: in tournament play, or whenever a continuous batting order is used, a courtesy runner may be used for the pitcher or catcher before they''ve met mandatory play.', 'https://www.littleleague.org/news/clarifications-and-enhancements-highlight-2026-little-league-rule-and-regulation-updates/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F021', 'LL-2026', 'both', 'little_league', NULL, NULL, NULL, '2026-01-14', 'uncaught_third_strike', 'double_first_base_2026', 'either side', NULL, '2026 update (article gives no number)', 'rule', 'New for 2026: with a double first base on an uncaught third strike, both the fielder and the runner may use either part of the base.', 'https://www.littleleague.org/news/clarifications-and-enhancements-highlight-2026-little-league-rule-and-regulation-updates/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F022', 'LL-2026', 'both', 'little_league', NULL, NULL, NULL, '2026-01-14', 'equipment', 'pine_tar_2026', 'permitted', NULL, '2026 update (article gives no number)', 'rule', 'New for 2026: pine tar is allowed at all levels of Little League baseball and softball, on the handle or grip only.', 'https://www.littleleague.org/news/clarifications-and-enhancements-highlight-2026-little-league-rule-and-regulation-updates/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F023', 'LL-OBSTR', 'both', 'little_league', NULL, NULL, NULL, 'page modified 2019-07-16', 'obstruction', 'award_to_nullify', 'umpire awards bases', NULL, 'casebook concept', 'mixed', 'Obstruction is a fielder without the ball impeding a runner, with or without contact; a fake tag counts. Whether it happened, and how far the runner would have gotten, are the umpire''s judgment. Awarding bases to cancel its effect is the rule.', 'https://www.littleleague.org/university/articles/defining-interference-and-obstruction/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F024', 'USSSA-FP18', 'softball', 'usssa', NULL, NULL, NULL, '18th edition, printed 2025-12', 'obstruction', 'definition', 'fielder without ball impedes runner', NULL, 'Rule 3 (Obstruction)', 'mixed', 'In USSSA fastpitch, obstruction is a defender who isn''t holding the ball and isn''t making the first play on a batted ball getting in a runner''s way, or hindering a batter''s swing. A fake tag is obstruction.', 'https://dev-newsfeed.usssa.com/wp-content/uploads/2025/12/usssa-fastpitch-rulebook-edition-18.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F025', 'USSSA-FP18', 'softball', 'usssa', NULL, NULL, NULL, '18th edition, printed 2025-12', 'obstruction', 'runner_penalty', 'delayed dead ball; award bases runner would have reached', NULL, 'Rule 8, Sec 13', 'mixed', 'USSSA fastpitch treats obstruction of a runner as a delayed dead ball. If the obstructed runner is put out before reaching the base the umpire judges they''d have reached, the ball is dead and the umpire awards that base. A runner who goes past it may be put out.', 'https://dev-newsfeed.usssa.com/wp-content/uploads/2025/12/usssa-fastpitch-rulebook-edition-18.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F026', 'USSSA-FP18', 'softball', 'usssa', NULL, NULL, NULL, '18th edition, printed 2025-12', 'obstruction', 'protected_between_bases', 'true with exceptions', NULL, 'Rule 8, Sec 13-D', 'rule', 'An obstructed runner generally can''t be put out between the two bases where the obstruction happened. The exceptions include passing another runner, committing interference or malicious contact, and a proper appeal.', 'https://dev-newsfeed.usssa.com/wp-content/uploads/2025/12/usssa-fastpitch-rulebook-edition-18.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F027', 'USSSA-FP18', 'softball', 'usssa', NULL, NULL, NULL, '18th edition, printed 2025-12', 'obstruction', 'catcher_obstruction_option', 'offense may choose play or award', NULL, 'Rule 7 / Rule 8, Sec 4-E', 'rule', 'When the catcher or an infielder obstructs the batter, the offensive coach may keep the result of the play or take first base for the batter. The obstruction is ignored if the batter and every runner advance at least one base anyway.', 'https://dev-newsfeed.usssa.com/wp-content/uploads/2025/12/usssa-fastpitch-rulebook-edition-18.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F028', 'USAS-PLAYS-2026', 'softball', 'usa_softball', NULL, NULL, NULL, '2026-02', 'obstruction', 'one_protected_fielder', 'true', NULL, 'Rule 8-7-J; Rule 1 Obstruction (as cited)', 'judgment', 'USA Softball''s 2026 clarifications: when a runner and a fielder collide while the fielder chases a pop-up, only the one fielder making the play is protected. Contact with that fielder is interference; contact with any other fielder is obstruction. Deciding which applies is the umpire''s judgment.', 'https://www.usasoftball.com/wp-content/uploads/sites/120/2026/02/February-2026-Plays-and-Clarification.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F029', 'USSSA-FP18', 'softball', 'usssa', NULL, NULL, NULL, '18th edition, printed 2025-12', 'protest', 'protestable', 'rule interpretation; player eligibility', NULL, 'Rule 13, Sec 1', 'rule', 'USSSA fastpitch allows protests only on rule interpretations and player eligibility.', 'https://dev-newsfeed.usssa.com/wp-content/uploads/2025/12/usssa-fastpitch-rulebook-edition-18.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F030', 'USSSA-FP18', 'softball', 'usssa', NULL, NULL, NULL, '18th edition, printed 2025-12', 'protest', 'fee', '100', 'USD', 'Rule 13, Sec 2', 'rule', 'A USSSA fastpitch tournament director may charge a $100 protest fee, per player for eligibility protests.', 'https://dev-newsfeed.usssa.com/wp-content/uploads/2025/12/usssa-fastpitch-rulebook-edition-18.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F031', 'USSSA-FP18', 'softball', 'usssa', NULL, NULL, NULL, '18th edition, printed 2025-12', 'protest', 'timing', 'before next pitch', NULL, 'Rule 13, Sec 4', 'rule', 'A USSSA fastpitch rule-interpretation protest must be raised with the plate umpire before the next pitch, and never after the umpires leave the field. Tournament officials and the UIC decide, and their decision is final.', 'https://dev-newsfeed.usssa.com/wp-content/uploads/2025/12/usssa-fastpitch-rulebook-edition-18.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F032', 'USSSA-FP18', 'softball', 'usssa', NULL, NULL, NULL, '18th edition, printed 2025-12', 'judgment', 'judgment_final', 'true', NULL, 'Rule 14, Sec 8', 'judgment', 'In USSSA fastpitch, judgment calls such as fair or foul, ball or strike, and safe or out are final. A coach may ask for the correct ruling only when a call seems to conflict with a rule.', 'https://dev-newsfeed.usssa.com/wp-content/uploads/2025/12/usssa-fastpitch-rulebook-edition-18.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F033', 'USSSA-FP18', 'softball', 'usssa', NULL, NULL, NULL, '18th edition, printed 2025-12', 'sportsmanship', 'argue_judgment', 'prohibited', NULL, 'Rule 11, Sec 2-R', 'rule', 'Arguing ball and strike calls or other judgment calls is listed as unsporting behavior in USSSA fastpitch.', 'https://dev-newsfeed.usssa.com/wp-content/uploads/2025/12/usssa-fastpitch-rulebook-edition-18.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F034', 'USSSA-FP18', 'softball', 'usssa', NULL, NULL, NULL, '18th edition, printed 2025-12', 'uncaught_third_strike', 'batter_may_run', 'first open or two outs', NULL, 'Rule 7, Sec 14-D; Rule 3 (Strikeout)', 'rule', 'In USSSA fastpitch, the batter may run on an uncaught third strike when first base is open or there are two outs. Coach-pitch travel ball is the exception.', 'https://dev-newsfeed.usssa.com/wp-content/uploads/2025/12/usssa-fastpitch-rulebook-edition-18.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F035', 'USSSA-FP18', 'softball', 'usssa', 'coach pitch', NULL, NULL, '18th edition, printed 2025-12', 'uncaught_third_strike', 'coach_pitch', 'not in effect', NULL, 'Rule 15', 'rule', 'In USSSA fastpitch coach-pitch travel ball, the batter is out on a third strike whether or not it''s caught, and the infield fly rule isn''t used.', 'https://dev-newsfeed.usssa.com/wp-content/uploads/2025/12/usssa-fastpitch-rulebook-edition-18.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F036', 'USSSA-FP18', 'softball', 'usssa', 'coach pitch', NULL, NULL, '18th edition, printed 2025-12', 'baserunning', 'coach_pitch_leave_early', 'runner out', NULL, 'Rule 15', 'rule', 'In USSSA fastpitch coach pitch, a runner may not leave the base until the coach releases the pitch, and stealing isn''t allowed.', 'https://dev-newsfeed.usssa.com/wp-content/uploads/2025/12/usssa-fastpitch-rulebook-edition-18.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F037', 'USSSA-FP18', 'softball', 'usssa', NULL, NULL, NULL, '18th edition, printed 2025-12', 'baserunning', 'look_back_rule', 'in effect', NULL, 'Rule 8, Sec 2', 'mixed', 'USSSA fastpitch uses a look-back rule. Once the pitcher holds the ball in the circle, a runner off base must go back or advance right away and may stop only once. Whether the pitcher made a play that released the runner is the umpire''s judgment.', 'https://dev-newsfeed.usssa.com/wp-content/uploads/2025/12/usssa-fastpitch-rulebook-edition-18.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F038', 'USSSA-FP18', 'softball', 'usssa', NULL, NULL, NULL, '18th edition, printed 2025-12', 'pitching', 'illegal_pitch_effect', 'ball; offense option', NULL, 'Rule 6, Sec 3', 'rule', 'A USSSA fastpitch illegal pitch is a ball. If the batter reaches first and every runner advances, the play stands. Otherwise the offense picks the play result or the illegal-pitch award.', 'https://dev-newsfeed.usssa.com/wp-content/uploads/2025/12/usssa-fastpitch-rulebook-edition-18.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F039', 'USSSA-FP18', 'softball', 'usssa', NULL, NULL, NULL, '18th edition, printed 2025-12', 'courtesy_runner', 'pitcher_catcher', 'true', NULL, 'Rule 8, Sec 3', 'rule', 'USSSA fastpitch allows a courtesy runner for the pitcher or catcher. It must be an unused substitute, and one runner can''t run for both in the same inning.', 'https://dev-newsfeed.usssa.com/wp-content/uploads/2025/12/usssa-fastpitch-rulebook-edition-18.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F040', 'USSSA-FP18', 'softball', 'usssa', NULL, NULL, NULL, '18th edition, printed 2025-12', 'game', 'run_rule', '12 after 3; 10 after 4; 8 after 5', 'runs', 'Rule 4, Sec 4', 'rule', 'The USSSA fastpitch run rule ends a game with a 12-run lead after 3 innings, a 10-run lead after 4, or an 8-run lead after 5.', 'https://dev-newsfeed.usssa.com/wp-content/uploads/2025/12/usssa-fastpitch-rulebook-edition-18.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F041', 'USSSA-FP18', 'softball', 'usssa', NULL, NULL, NULL, '18th edition, printed 2025-12', 'equipment', 'bat_standard', 'BPF 1.20; USSSA mark', NULL, 'Rule 2, Sec 10', 'rule', 'A legal USSSA fastpitch bat has a BPF of 1.20 or less, carries a USSSA certification mark, and isn''t on the withdrawn or non-compliant list. Maximums are 34 inches, 31 ounces and a 2-1/4 inch diameter.', 'https://dev-newsfeed.usssa.com/wp-content/uploads/2025/12/usssa-fastpitch-rulebook-edition-18.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F042', 'USSSA-BB-NAT', 'baseball', 'usssa', NULL, 7, 12, 'edition dated 2024-08-01, revised 2024-08-16', 'pitching_innings', 'daily_max_innings', '6', 'innings', 'Rule 7.05.B; Chart 7.05.B-1', 'rule', 'Under USSSA baseball''s national rules, a 7U-12U pitcher may throw up to 6 innings in a day and 8 across three consecutive days.', 'https://www.usssabaseball.org/images/2024/USSSA_National_By-Laws8-16-2024.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Same in the 2024 edition (checked).'),
  ('F043', 'USSSA-BB-NAT', 'baseball', 'usssa', NULL, 7, 12, 'edition dated 2024-08-01, revised 2024-08-16', 'pitching_innings', 'three_day_max_innings', '8', 'innings', 'Rule 7.05.B; Chart 7.05.B-1', 'rule', 'USSSA 7U-12U: at most 8 innings over three consecutive days.', 'https://www.usssabaseball.org/images/2024/USSSA_National_By-Laws8-16-2024.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F044', 'USSSA-BB-NAT', 'baseball', 'usssa', NULL, 13, 14, 'edition dated 2024-08-01, revised 2024-08-16', 'pitching_innings', 'daily_max_innings', '7', 'innings', 'Rule 7.05.B; Chart 7.05.B-1', 'rule', 'USSSA 13U-14U: at most 7 innings in a day and 8 across three consecutive days.', 'https://www.usssabaseball.org/images/2024/USSSA_National_By-Laws8-16-2024.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F045', 'USSSA-BB-NAT', 'baseball', 'usssa', NULL, 13, 14, 'edition dated 2024-08-01, revised 2024-08-16', 'pitching_innings', 'three_day_max_innings', '8', 'innings', 'Rule 7.05.B; Chart 7.05.B-1', 'rule', 'USSSA 13U-14U: at most 8 innings over three consecutive days.', 'https://www.usssabaseball.org/images/2024/USSSA_National_By-Laws8-16-2024.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F046', 'USSSA-BB-NAT', 'baseball', 'usssa', NULL, 15, 18, 'edition dated 2024-08-01, revised 2024-08-16', 'pitching_innings', 'daily_max_innings', 'unlimited', NULL, 'Chart 7.05.B-1', 'rule', 'USSSA national rules set no innings limit for 15U-18U pitchers.', 'https://www.usssabaseball.org/images/2024/USSSA_National_By-Laws8-16-2024.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F047', 'USSSA-BB-NAT', 'baseball', 'usssa', NULL, 7, 14, 'edition dated 2024-08-01, revised 2024-08-16', 'pitching_innings', 'mandatory_rest', 'next day', 'days', 'Rule 7.05.B.4', 'rule', 'A USSSA pitcher must rest the next day after pitching more than 3 innings in one day, 8 innings over two consecutive days, or on three consecutive days.', 'https://www.usssabaseball.org/images/2024/USSSA_National_By-Laws8-16-2024.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F048', 'USSSA-BB-NAT', 'baseball', 'usssa', NULL, 7, 18, 'edition dated 2024-08-01, revised 2024-08-16', 'pitching_innings', 'out_equals_third_inning', '1/3', 'innings', 'Rule 7.05.B.5', 'rule', 'For USSSA innings limits, each out counts as one-third of an inning.', 'https://www.usssabaseball.org/images/2024/USSSA_National_By-Laws8-16-2024.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F049', 'USSSA-BB-NAT', 'baseball', 'usssa', NULL, 7, 18, 'edition dated 2024-08-01, revised 2024-08-16', 'pitching_innings', 'violation_penalty', 'forfeit', NULL, 'Rules 7.05.B.1-7', 'rule', 'Breaking a USSSA pitching limit forfeits the game. In pool play, it also bars the team from the championship bracket.', 'https://www.usssabaseball.org/images/2024/USSSA_National_By-Laws8-16-2024.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F050', 'USSSA-BB-NAT', 'baseball', 'usssa', NULL, NULL, NULL, 'edition dated 2024-08-01, revised 2024-08-16', 'protest', 'protestable', 'age; pitching; rule interpretation', NULL, 'Rule 16.01', 'rule', 'USSSA baseball allows protests on age violations, pitching violations and rule interpretations. Judgment calls aren''t among the protestable categories.', 'https://www.usssabaseball.org/images/2024/USSSA_National_By-Laws8-16-2024.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Judgment exclusion is inferred: the rule lists what can be protested and doesn''t mention judgment.');
INSERT INTO rules_facts (fact_code, source_id, sport, sanction, division, age_min, age_max, edition, topic, fact_key, fact_value, unit, rule_ref, call_type, summary, source_url, verified, verified_by, retrieved_on, verify_note) VALUES
  ('F051', 'USSSA-BB-NAT', 'baseball', 'usssa', NULL, NULL, NULL, 'edition dated 2024-08-01, revised 2024-08-16', 'protest', 'timing', 'before next pitch', NULL, 'Rule 16.01', 'rule', 'A USSSA baseball protest goes to the Umpire-in-Chief, then the tournament director, before the next pitch. If the disputed play ends the game, the protest must come before the umpires and teams leave the field.', 'https://www.usssabaseball.org/images/2024/USSSA_National_By-Laws8-16-2024.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F052', 'USSSA-BB-NAT', 'baseball', 'usssa', NULL, NULL, NULL, 'edition dated 2024-08-01, revised 2024-08-16', 'protest', 'fee', '100', 'USD', 'Rule 16.02', 'rule', 'A USSSA baseball protest costs $100 cash, refunded only if the protest is upheld. Leagues may set their own fees.', 'https://www.usssabaseball.org/images/2024/USSSA_National_By-Laws8-16-2024.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F053', 'USSSA-BB-NAT', 'baseball', 'usssa', '7U-8U kid pitch', 7, 8, 'edition dated 2024-08-01, revised 2024-08-16', 'balk', 'balks_apply', 'false', NULL, 'Rule 11.02', 'rule', 'Balk rules don''t apply in USSSA 7U-8U kid pitch.', 'https://www.usssabaseball.org/images/2024/USSSA_National_By-Laws8-16-2024.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F054', 'USSSA-BB-NAT', 'baseball', 'usssa', '7U-8U kid pitch', 7, 8, 'edition dated 2024-08-01, revised 2024-08-16', 'uncaught_third_strike', 'batter_may_run', 'false', NULL, 'Rule 11.03', 'rule', 'In USSSA 7U-8U kid pitch, the batter is automatically out on a dropped third strike.', 'https://www.usssabaseball.org/images/2024/USSSA_National_By-Laws8-16-2024.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F055', 'USSSA-BB-NAT', 'baseball', 'usssa', NULL, NULL, NULL, 'edition dated 2024-08-01, revised 2024-08-16', 'general', 'unaddressed_defaults_to', 'MLB rules', NULL, 'Foreword', 'rule', 'Anything the USSSA baseball national rules don''t address follows professional baseball rules.', 'https://www.usssabaseball.org/images/2024/USSSA_National_By-Laws8-16-2024.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F056', 'USSSA-FL', 'baseball', 'usssa', 'Florida state events', 8, 14, 'undated state page, retrieved 2026-10-22', 'pitching_innings', 'state_variation', 'see summary', NULL, 'state page (no national numbers)', 'rule', 'Florida USSSA layers its own limits on top of the national rules. Examples include 8 innings across a 3-day event and a rule that a pitcher removed from the mound can''t return. State rules can differ from national ones, so always check the event''s state.', 'https://flbaseball.usssa.com/pitching-rules-and-information/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: State-specific example; use it to show that house and state rules matter.'),
  ('F057', 'PS-9-12', 'baseball', 'pitch_smart', NULL, 9, 12, 'current page, retrieved 2026-10-22', 'pitch_rest', 'three_consecutive_days', 'false', NULL, 'guideline', 'rule', 'Pitch Smart recommends that pitchers aged 9-12 never pitch on three consecutive days, regardless of pitch counts.', 'https://www.mlb.com/pitch-smart/pitching-guidelines/ages-9-12', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Guideline; it binds only where a league adopts it.'),
  ('F058', 'PS-9-12', 'baseball', 'pitch_smart', NULL, 9, 12, 'current page, retrieved 2026-10-22', 'workload', 'annual_innings_cap', '80', 'innings per 12 months', 'guideline', 'rule', 'Pitch Smart recommends that pitchers aged 9-12 throw no more than 80 combined innings in any 12 months, and take at least 4 months off throwing each year.', 'https://www.mlb.com/pitch-smart/pitching-guidelines/ages-9-12', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F059', 'PS-9-12', 'baseball', 'pitch_smart', NULL, 9, 12, 'current page, retrieved 2026-10-22', 'workload', 'no_multiple_games_same_day', 'true', NULL, 'guideline', 'rule', 'Pitch Smart recommends against pitching in more than one game on the same day, and against catching on days a player isn''t pitching.', 'https://www.mlb.com/pitch-smart/pitching-guidelines/ages-9-12', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F060', 'PS-GUIDE', 'baseball', 'pitch_smart', NULL, 7, 8, 'current page, retrieved 2026-10-22', 'pitch_count', 'daily_max_pitches', '50', 'pitches', 'guideline', 'rule', 'Pitch Smart''s recommended daily maximum for ages 7-8 is 50 pitches.', 'https://www.mlb.com/pitch-smart/pitching-guidelines', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F061', 'PS-GUIDE', 'baseball', 'pitch_smart', NULL, 9, 10, 'current page, retrieved 2026-10-22', 'pitch_count', 'daily_max_pitches', '75', 'pitches', 'guideline', 'rule', 'Pitch Smart''s recommended daily maximum for ages 9-10 is 75 pitches.', 'https://www.mlb.com/pitch-smart/pitching-guidelines', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F062', 'PS-GUIDE', 'baseball', 'pitch_smart', NULL, 11, 12, 'current page, retrieved 2026-10-22', 'pitch_count', 'daily_max_pitches', '85', 'pitches', 'guideline', 'rule', 'Pitch Smart''s recommended daily maximum for ages 11-12 is 85 pitches.', 'https://www.mlb.com/pitch-smart/pitching-guidelines', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F063', 'PS-GUIDE', 'baseball', 'pitch_smart', NULL, 13, 14, 'current page, retrieved 2026-10-22', 'pitch_count', 'daily_max_pitches', '95', 'pitches', 'guideline', 'rule', 'Pitch Smart''s recommended daily maximum for ages 13-14 is 95 pitches.', 'https://www.mlb.com/pitch-smart/pitching-guidelines', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F064', 'PS-GUIDE', 'baseball', 'pitch_smart', NULL, 15, 16, 'current page, retrieved 2026-10-22', 'pitch_count', 'daily_max_pitches', '95', 'pitches', 'guideline', 'rule', 'Pitch Smart''s recommended daily maximum for ages 15-16 is 95 pitches.', 'https://www.mlb.com/pitch-smart/pitching-guidelines', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F065', 'PS-GUIDE', 'baseball', 'pitch_smart', NULL, 17, 18, 'current page, retrieved 2026-10-22', 'pitch_count', 'daily_max_pitches', '105', 'pitches', 'guideline', 'rule', 'Pitch Smart''s recommended daily maximum for ages 17-18 is 105 pitches.', 'https://www.mlb.com/pitch-smart/pitching-guidelines', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F066', 'LL-BAT', 'baseball', 'little_league', 'Tee Ball through Majors', NULL, NULL, 'page updated 2026-07-07', 'equipment', 'bat_standard', 'USABat', NULL, 'Rule 1.10', 'rule', 'Little League Majors and below require USABat-marked non-wood bats: at most 33 inches long with a 2-5/8 inch barrel. BPF 1.15 bats are banned.', 'https://www.littleleague.org/playing-rules/bat-rules/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F067', 'LL-BAT', 'baseball', 'little_league', 'Intermediate/Junior', NULL, NULL, 'page updated 2026-07-07', 'equipment', 'bat_standard', 'USABat or BBCOR', NULL, 'Rule 1.10', 'rule', 'Little League Intermediate (50/70) and Junior allow USABat or BBCOR bats up to 34 inches with a 2-5/8 inch barrel.', 'https://www.littleleague.org/playing-rules/bat-rules/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F068', 'LL-BAT', 'baseball', 'little_league', 'Senior', NULL, NULL, 'page updated 2026-07-07', 'equipment', 'bat_standard', 'BBCOR', NULL, 'Rule 1.10', 'rule', 'Little League Senior requires BBCOR (or one-piece wood) bats up to 36 inches. A bat may weigh no more than 3 ounces less than its length in inches.', 'https://www.littleleague.org/playing-rules/bat-rules/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F069', 'LL-BAT', 'softball', 'little_league', NULL, NULL, NULL, 'page updated 2026-07-07', 'equipment', 'bat_standard', 'BPF 1.20; 2-1/4 in', NULL, 'Rule 1.10', 'rule', 'Little League softball bats are at most 33 inches (34 for Junior and Senior) with a 2-1/4 inch diameter. Non-wood bats must be marked BPF 1.20.', 'https://www.littleleague.org/playing-rules/bat-rules/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F070', 'LL-BAT', 'both', 'little_league', NULL, NULL, NULL, 'page updated 2026-07-07', 'equipment', 'illegal_bat_penalty', 'remove bat; see Rule 6.06(d)', NULL, 'Rule 1.10; Rule 6.06(d)', 'rule', 'An illegal, damaged or altered bat comes out of play. Choke-up aids must be removed, and repeat offenses can lead to ejections. Penalties for batting with an illegal bat are in Rule 6.06(d).', 'https://www.littleleague.org/playing-rules/bat-rules/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F071', 'BRL-BAT', 'baseball', 'cal_ripken', NULL, NULL, NULL, 'retrieved 2026-10-22', 'equipment', 'bat_standard', 'USABat; no BBCOR or USSSA', NULL, 'Rule 1.10', 'rule', 'Cal Ripken Baseball requires USABat-marked bats with a barrel of at most 2-5/8 inches. BBCOR and USSSA bats aren''t allowed.', 'https://www.baberuthleague.org/bat-rules', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F072', 'BRL-BAT', 'baseball', 'babe_ruth_league', '13-16', 13, 16, 'retrieved 2026-10-22', 'equipment', 'bat_standard', 'USABat or BBCOR .50', NULL, 'Rule 1.10', 'rule', 'Babe Ruth Baseball 13-16 allows USABat or BBCOR .50 bats with a barrel of at most 2-5/8 inches.', 'https://www.baberuthleague.org/bat-rules', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F073', 'BRL-BAT', 'baseball', 'babe_ruth_league', '16-18', 16, 18, 'retrieved 2026-10-22', 'equipment', 'bat_standard', 'BBCOR .50', NULL, 'Rule 1.10', 'rule', 'Babe Ruth Baseball 16-18 requires BBCOR .50 bats; one-piece wood is allowed in every division.', 'https://www.baberuthleague.org/bat-rules', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F074', 'BRL-BAT', 'softball', 'babe_ruth_league', NULL, NULL, NULL, 'retrieved 2026-10-22', 'equipment', 'bat_standard', 'Official Softball/Fastpitch Bat', NULL, 'Rule 1.10', 'rule', 'Babe Ruth Softball bats must be marked ''Official Softball Bat'' or ''Official Fastpitch Bat''.', 'https://www.baberuthleague.org/bat-rules', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F075', 'BRL-TBALL', 'baseball', 'babe_ruth_league', 'Tee Ball', NULL, NULL, 'program effective 2018-01-01', 'equipment', 'tee_ball_bat', 'USA Baseball mark; 26 in max', NULL, 'USABat Tee Ball program', 'rule', 'Tee ball bats of 26 inches or shorter need the USA Baseball mark and must say they''re only for use with approved tee balls. Older bats can be made legal with an official sticker.', 'https://www.baberuthleague.org/sitemedia/USABat%20Tee%20Ball%20Sticker%20Program%20Overview.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F076', 'BRL-CR', 'baseball', 'cal_ripken', NULL, 4, 12, 'retrieved 2026-10-22', 'divisions', 'divisions', 'T-Ball 4-6; Rookie 7-8; Minor 9-10; Major 11-12', NULL, 'n/a', 'rule', 'Cal Ripken Baseball covers ages 4-12: T-Ball (4-6), Rookie (7-8, machine pitch), Minor (9-10) and Major (11-12, in 60-foot and 70-foot formats).', 'https://www.baberuthleague.org/cal-ripken-baseball', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F077', 'BRL-CR-PITCHSHEET', 'baseball', 'cal_ripken', NULL, 9, 12, 'undated', 'pitch_count', 'daily_max_pitches', '9-10: 75; 11-12: 85', 'pitches', 'pitch count sheet', 'rule', 'Cal Ripken daily pitch maximums are 75 for ages 9-10 and 85 for ages 11-12.', 'https://www.baberuthleague.org/sitemedia/Pitch%20Count%20Sheet%20CR.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: The rest-day table needs verification from the rulebook; it isn''t loaded.'),
  ('F078', 'BRL-2026', 'baseball', 'cal_ripken', '8U coach pitch', 7, 8, '2026 season', 'game', 'coach_pitch_rules_2026', 'see summary', NULL, '2026 appendix', 'rule', 'Cal Ripken 8U coach pitch uses four outfielders, at most four pitches per batter, and no infield fly rule. There''s no stealing in Rookie coach pitch and a 1:30 or six-inning limit.', 'https://www.baberuthleague.org/latest-rule-changes/2026-baseball-rule-changes', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F079', 'BRL-2026', 'baseball', 'babe_ruth_league', NULL, NULL, NULL, '2026 season', 'game', 'extra_inning_tiebreaker_2026', 'runner on second', NULL, 'Rules 11.05, 4.10b', 'rule', 'New for 2026 in Babe Ruth and Cal Ripken: each extra inning starts with the previous inning''s last batter on second base.', 'https://www.baberuthleague.org/latest-rule-changes/2026-baseball-rule-changes', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F080', 'BRL-SB-AGE', 'softball', 'babe_ruth_league', NULL, NULL, NULL, '2026 season', 'age', 'age_cutoff', 'Sept 1 - Aug 31', NULL, 'age chart', 'rule', 'Babe Ruth Softball league age runs from September 1 to August 31 by birth year. For example, 12U in 2026 is players born Sept 2012-Aug 2013 (2012-2013 on the chart).', 'https://www.baberuthleague.org/league-resources/softball-age-chart', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F081', 'USAS-RB-2026', 'softball', 'usa_softball', NULL, NULL, NULL, '2026 (posted 2026-01-12)', 'protest', 'protestable', 'rule interpretation; illegal player; ineligible player', NULL, 'Rule 9, Secs 1 and 3', 'rule', 'USA Softball allows three kinds of protest: misinterpretation of a playing rule, an illegal player, and an ineligible player. Protests may only involve how a rule was interpreted.', 'https://www.usasoftball.com/wp-content/uploads/sites/120/2026/01/1-12-2026-Rule-Book.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F082', 'USAS-RB-2026', 'softball', 'usa_softball', NULL, NULL, NULL, '2026 (posted 2026-01-12)', 'protest', 'timing_rule_misinterpretation', 'before next pitch', NULL, 'Rule 9, Sec 1-A', 'rule', 'A USA Softball rule-misinterpretation protest must come before the next pitch (legal or illegal) or play, before all infielders leave fair territory, or, on the game''s last play, before the umpires leave the field.', 'https://www.usasoftball.com/wp-content/uploads/sites/120/2026/01/1-12-2026-Rule-Book.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F083', 'USAS-RB-2026', 'softball', 'usa_softball', NULL, NULL, NULL, '2026 (posted 2026-01-12)', 'protest', 'timing_illegal_ineligible', 'illegal: while in game; ineligible: any time', NULL, 'Rule 9, Secs 1-B, 1-C and 5', 'rule', 'An illegal-player protest must come while that player is in the game and before the umpires leave. An ineligibility protest can come at any time, and the protest committee decides eligibility.', 'https://www.usasoftball.com/wp-content/uploads/sites/120/2026/01/1-12-2026-Rule-Book.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F084', 'USAS-RB-2026', 'softball', 'usa_softball', NULL, NULL, NULL, '2026 (posted 2026-01-12)', 'protest', 'no_reversal_after_pitch', 'true', NULL, 'Rule 9, Sec 1 (Note A-B)', 'rule', 'In USA Softball, an umpire can''t reverse a decision once the next pitch, legal or illegal, has been thrown.', 'https://www.usasoftball.com/wp-content/uploads/sites/120/2026/01/1-12-2026-Rule-Book.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F085', 'USAS-RB-2026', 'softball', 'usa_softball', NULL, NULL, NULL, '2026 (posted 2026-01-12)', 'protest', 'notification', 'plate umpire immediately', NULL, 'Rule 9, Sec 4', 'rule', 'The manager or captain must tell the plate umpire right away that the game is being played under protest. The umpire tells the other manager and the scorekeeper.', 'https://www.usasoftball.com/wp-content/uploads/sites/120/2026/01/1-12-2026-Rule-Book.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F086', 'USAS-RB-2026', 'softball', 'usa_softball', NULL, NULL, NULL, '2026 (posted 2026-01-12)', 'protest', 'outcome', 'resume from point of protest; ineligible = forfeit', NULL, 'Rule 9, Sec 7', 'rule', 'If a USA Softball rule protest is upheld, the call is corrected and play resumes from the point of protest. An upheld ineligibility protest forfeits the game.', 'https://www.usasoftball.com/wp-content/uploads/sites/120/2026/01/1-12-2026-Rule-Book.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F087', 'USAS-RB-2026', 'softball', 'usa_softball', NULL, NULL, NULL, '2026 (posted 2026-01-12)', 'judgment', 'not_protestable: fair or foul', 'judgment', NULL, 'Rule 9, Sec 2', 'judgment', 'In USA Softball, the call on fair or foul is the umpire''s judgment and can''t be protested.', 'https://www.usasoftball.com/wp-content/uploads/sites/120/2026/01/1-12-2026-Rule-Book.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F088', 'USAS-RB-2026', 'softball', 'usa_softball', NULL, NULL, NULL, '2026 (posted 2026-01-12)', 'judgment', 'not_protestable: safe or out', 'judgment', NULL, 'Rule 9, Sec 2', 'judgment', 'In USA Softball, the call on safe or out is the umpire''s judgment and can''t be protested.', 'https://www.usasoftball.com/wp-content/uploads/sites/120/2026/01/1-12-2026-Rule-Book.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F089', 'USAS-RB-2026', 'softball', 'usa_softball', NULL, NULL, NULL, '2026 (posted 2026-01-12)', 'judgment', 'not_protestable: ball or strike', 'judgment', NULL, 'Rule 9, Sec 2', 'judgment', 'In USA Softball, the call on ball or strike is the umpire''s judgment and can''t be protested.', 'https://www.usasoftball.com/wp-content/uploads/sites/120/2026/01/1-12-2026-Rule-Book.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F090', 'USAS-RB-2026', 'softball', 'usa_softball', NULL, NULL, NULL, '2026 (posted 2026-01-12)', 'judgment', 'not_protestable: legal or illegal pitch', 'judgment', NULL, 'Rule 9, Sec 2', 'judgment', 'In USA Softball, the call on legal or illegal pitch is the umpire''s judgment and can''t be protested.', 'https://www.usasoftball.com/wp-content/uploads/sites/120/2026/01/1-12-2026-Rule-Book.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F091', 'USAS-RB-2026', 'softball', 'usa_softball', NULL, NULL, NULL, '2026 (posted 2026-01-12)', 'judgment', 'not_protestable: whether a runner touched a base', 'judgment', NULL, 'Rule 9, Sec 2', 'judgment', 'In USA Softball, the call on whether a runner touched a base is the umpire''s judgment and can''t be protested.', 'https://www.usasoftball.com/wp-content/uploads/sites/120/2026/01/1-12-2026-Rule-Book.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F092', 'USAS-RB-2026', 'softball', 'usa_softball', NULL, NULL, NULL, '2026 (posted 2026-01-12)', 'judgment', 'not_protestable: whether a runner left too soon on a caught fly', 'judgment', NULL, 'Rule 9, Sec 2', 'judgment', 'In USA Softball, the call on whether a runner left too soon on a caught fly is the umpire''s judgment and can''t be protested.', 'https://www.usasoftball.com/wp-content/uploads/sites/120/2026/01/1-12-2026-Rule-Book.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F093', 'USAS-RB-2026', 'softball', 'usa_softball', NULL, NULL, NULL, '2026 (posted 2026-01-12)', 'judgment', 'not_protestable: whether a fly ball was caught legally', 'judgment', NULL, 'Rule 9, Sec 2', 'judgment', 'In USA Softball, the call on whether a fly ball was caught legally is the umpire''s judgment and can''t be protested.', 'https://www.usasoftball.com/wp-content/uploads/sites/120/2026/01/1-12-2026-Rule-Book.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F094', 'USAS-RB-2026', 'softball', 'usa_softball', NULL, NULL, NULL, '2026 (posted 2026-01-12)', 'judgment', 'not_protestable: whether a ball was an infield fly', 'judgment', NULL, 'Rule 9, Sec 2', 'judgment', 'In USA Softball, the call on whether a ball was an infield fly is the umpire''s judgment and can''t be protested.', 'https://www.usasoftball.com/wp-content/uploads/sites/120/2026/01/1-12-2026-Rule-Book.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F095', 'USAS-RB-2026', 'softball', 'usa_softball', NULL, NULL, NULL, '2026 (posted 2026-01-12)', 'judgment', 'not_protestable: whether interference or obstruction happened', 'judgment', NULL, 'Rule 9, Sec 2', 'judgment', 'In USA Softball, the call on whether interference or obstruction happened is the umpire''s judgment and can''t be protested.', 'https://www.usasoftball.com/wp-content/uploads/sites/120/2026/01/1-12-2026-Rule-Book.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F096', 'USAS-RB-2026', 'softball', 'usa_softball', NULL, NULL, NULL, '2026 (posted 2026-01-12)', 'judgment', 'not_protestable: whether the field is fit or there is enough light', 'judgment', NULL, 'Rule 9, Sec 2', 'judgment', 'In USA Softball, the call on whether the field is fit or there is enough light is the umpire''s judgment and can''t be protested.', 'https://www.usasoftball.com/wp-content/uploads/sites/120/2026/01/1-12-2026-Rule-Book.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F097', 'USAS-RB-2026', 'softball', 'usa_softball', NULL, NULL, NULL, '2026 (posted 2026-01-12)', 'obstruction', 'runner_penalty', 'delayed dead ball; award bases runner would have reached', NULL, 'Rule 8, Sec 5-B', 'mixed', 'USA Softball treats obstruction of a runner as a delayed dead ball. If the runner is put out before reaching the base the umpire judges they''d have reached, the ball is dead and bases are awarded. A runner put out after passing that base stays out, and the ball stays live.', 'https://www.usasoftball.com/wp-content/uploads/sites/120/2026/01/1-12-2026-Rule-Book.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F098', 'USAS-RB-2026', 'softball', 'usa_softball', NULL, NULL, NULL, '2026 (posted 2026-01-12)', 'obstruction', 'protected_between_bases', 'true with exceptions', NULL, 'Rule 8, Sec 5-B-1', 'rule', 'An obstructed runner can''t be put out between the two bases where they were obstructed. The exceptions include passing a runner, interference, and appeals for missing a base or leaving early on a fly ball.', 'https://www.usasoftball.com/wp-content/uploads/sites/120/2026/01/1-12-2026-Rule-Book.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F099', 'USAS-RB-2026', 'softball', 'usa_softball', NULL, NULL, NULL, '2026 (posted 2026-01-12)', 'obstruction', 'fake_tag', 'obstruction; possible ejection', NULL, 'Rule 8, Sec 5-B-4', 'mixed', 'A fake tag without the ball is obstruction in USA Softball, and the umpire may eject the fielder who made it.', 'https://www.usasoftball.com/wp-content/uploads/sites/120/2026/01/1-12-2026-Rule-Book.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F100', 'USAS-RB-2026', 'softball', 'usa_softball', NULL, NULL, NULL, '2026 (posted 2026-01-12)', 'baserunning', 'look_back_rule', 'in effect', NULL, 'Rule 8, Sec 7-T', 'mixed', 'USA Softball fast pitch uses a look-back rule. Once the pitcher holds the ball in the circle and the batter-runner has reached first or is out, a runner off base may stop once, then must go back or advance right away.', 'https://www.usasoftball.com/wp-content/uploads/sites/120/2026/01/1-12-2026-Rule-Book.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.');
INSERT INTO rules_facts (fact_code, source_id, sport, sanction, division, age_min, age_max, edition, topic, fact_key, fact_value, unit, rule_ref, call_type, summary, source_url, verified, verified_by, retrieved_on, verify_note) VALUES
  ('F101', 'USAS-RB-2026', 'softball', 'usa_softball', NULL, NULL, NULL, '2026 (posted 2026-01-12)', 'courtesy_runner', 'pitcher_catcher', 'true', NULL, 'Rule 8, Sec 10', 'rule', 'USA Softball allows a courtesy runner for the pitcher or catcher, reported to the plate umpire. In Junior Olympic pool play, any eligible player may be the courtesy runner.', 'https://www.usasoftball.com/wp-content/uploads/sites/120/2026/01/1-12-2026-Rule-Book.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F102', 'USAS-RB-2026', 'softball', 'usa_softball', 'JO fast pitch', NULL, NULL, '2026 (posted 2026-01-12)', 'game', 'run_ahead_rule', '15 after 3; 12 after 4; 8 after 5', 'runs', 'Rule 5, Sec 9-A', 'rule', 'At USA Softball national championships, Junior Olympic fast pitch games end with a 15-run lead after 3 innings, 12 after 4, or 8 after 5.', 'https://www.usasoftball.com/wp-content/uploads/sites/120/2026/01/1-12-2026-Rule-Book.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F103', 'USAS-CHG-2026', 'softball', 'usa_softball', 'JO fast pitch 10U-18U', 10, 18, '2025-11-10, effective 2026-01-01', 'game', 'time_limit_2026', '1:30 or 1:40', NULL, 'Rule 5, Sec 10-B', 'rule', 'New for 2026: Junior Olympic fast pitch territorial championship games have a 1:30 or 1:40 time limit, set before the event. Finish the inning, then go to the tiebreaker if still tied.', 'https://www.usasoftball.com/wp-content/uploads/sites/120/2025/12/11-10-2025-2026-USA-Softball-Rule-Changes-with-Comments-Final.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F104', 'USAS-CHG-2026', 'softball', 'usa_softball', NULL, NULL, NULL, '2025-11-10, effective 2026-01-01', 'equipment', 'bat_sensors_2026', 'allowed', NULL, 'Rule 3, Sec 1-B Note', 'rule', 'New for 2026: internal or external bat sensors are allowed in USA Softball if properly attached.', 'https://www.usasoftball.com/wp-content/uploads/sites/120/2025/12/11-10-2025-2026-USA-Softball-Rule-Changes-with-Comments-Final.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F105', 'USAS-CHG-2026', 'softball', 'usa_softball', NULL, NULL, NULL, '2025-11-10, effective 2026-01-01', 'conduct', 'ejection_suspension_2026', 'one additional game', NULL, 'Rule 4, Sec 8-B', 'rule', 'New for 2026: umpires may eject a participant from the time they arrive until they leave the field. An ejected participant must leave the grounds and sits out one more game, which they may appeal.', 'https://www.usasoftball.com/wp-content/uploads/sites/120/2025/12/11-10-2025-2026-USA-Softball-Rule-Changes-with-Comments-Final.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F106', 'USAS-RB-2026', 'softball', 'usa_softball', NULL, NULL, NULL, '2026 (posted 2026-01-12)', 'equipment', 'bat_standard', 'certification mark; 34 in; 38 oz; 2.25 in', NULL, 'Rule 3, Sec 1-A', 'rule', 'A USA Softball bat must carry the USA Softball certification mark, not be on the non-approved list, and be at most 34 inches, 38 ounces and 2.25 inches in diameter.', 'https://www.usasoftball.com/wp-content/uploads/sites/120/2026/01/1-12-2026-Rule-Book.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F107', 'USAS-RB-2026', 'softball', 'usa_softball', 'Girls 10U', NULL, 10, '2026 (posted 2026-01-12)', 'field', 'pitching_distance', '35', 'feet', 'Rule 2 (Official Distance Table)', 'rule', 'USA Softball Girls 10U fast pitch pitches from 35 feet, with 60-foot bases.', 'https://www.usasoftball.com/wp-content/uploads/sites/120/2026/01/1-12-2026-Rule-Book.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F108', 'USAS-RB-2026', 'softball', 'usa_softball', 'Girls 12U', NULL, 12, '2026 (posted 2026-01-12)', 'field', 'pitching_distance', '40', 'feet', 'Rule 2 (Official Distance Table)', 'rule', 'USA Softball Girls 12U fast pitch pitches from 40 feet, with 60-foot bases.', 'https://www.usasoftball.com/wp-content/uploads/sites/120/2026/01/1-12-2026-Rule-Book.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F109', 'USAS-RB-2026', 'softball', 'usa_softball', 'Girls 14U-18U', NULL, 18, '2026 (posted 2026-01-12)', 'field', 'pitching_distance', '43', 'feet', 'Rule 2 (Official Distance Table)', 'rule', 'USA Softball Girls 14U-18U fast pitch pitches from 43 feet, with 60-foot bases.', 'https://www.usasoftball.com/wp-content/uploads/sites/120/2026/01/1-12-2026-Rule-Book.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F110', 'USAS-RB-2026', 'softball', 'usa_softball', NULL, NULL, NULL, '2026 (posted 2026-01-12)', 'pitching', 'pitch_limits', 'none found', NULL, 'n/a', 'rule', 'The 2026 USA Softball rulebook has no pitch-count or innings limits for youth fast pitch. Any limits come from the league or tournament.', 'https://www.usasoftball.com/wp-content/uploads/sites/120/2026/01/1-12-2026-Rule-Book.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Absence check: search the book for innings and pitch limits to confirm.'),
  ('F111', 'USAS-UMP-2025', 'softball', 'usa_softball', NULL, NULL, NULL, '2025-01-29', 'channel', 'protest_vs_judgment', 'rule interpretation only', NULL, 'Umpire Manual (Protests)', 'judgment', 'The USA Softball umpire manual describes protests as being about an umpire''s interpretation or application of a rule, never a judgment call, and says the umpire''s first priority is getting the call right.', 'https://www.usasoftball.com/wp-content/uploads/sites/120/2025/01/1-29-2025-Umpire-Manual.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F112', 'BRL-SB-2026', 'softball', 'babe_ruth_league', NULL, NULL, NULL, '2026 season', 'age', 'age_determination_2026', 'age on Aug 31, 2025', NULL, 'Rule 0.02', 'rule', 'For 2026 Babe Ruth Softball, a player''s age on August 31, 2025 sets eligibility. Players range from 4 to 18.', 'https://www.baberuthleague.org/latest-rule-changes/2026-softball-rule-changes', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F113', 'BRL-SB-2026', 'softball', 'babe_ruth_league', NULL, NULL, NULL, '2026 season', 'game', 'intentional_walk_2026', 'no pitches; notify umpire', NULL, '2026 addition (no number)', 'rule', 'New for 2026 in Babe Ruth Softball: a manager calls an intentional walk by telling the plate umpire, and the batter goes to first with no pitches thrown.', 'https://www.baberuthleague.org/latest-rule-changes/2026-softball-rule-changes', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F114', 'BRL-SB-2026', 'softball', 'babe_ruth_league', '8U machine pitch', NULL, 8, '2026 season', 'game', 'machine_speed', '35 mph +/- 3', 'mph', '2026 clarification', 'rule', 'Babe Ruth Softball 8U machine pitch is set at 35 mph, plus or minus 3.', 'https://www.baberuthleague.org/latest-rule-changes/2026-softball-rule-changes', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F115', 'BRL-FACILITY', 'baseball', 'cal_ripken', '60-foot programs', 4, 12, 'undated, retrieved 2026-10-22', 'field', 'pitching_distance', '46', 'feet', 'Facility Guide', 'rule', 'Cal Ripken Rookie, Minor and Major/60 fields use 60-foot bases and a 46-foot pitching distance. Major/70 uses 70-foot bases and 50 feet.', 'https://www.baberuthleague.org/sitemedia/Babe%20Ruth%20Facility%20Guide%20TC2.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Facility guide says minimum recommendations; confirm against the rulebook.'),
  ('F116', 'BRL-FACILITY', 'baseball', 'babe_ruth_league', '13-18', 13, 18, 'undated, retrieved 2026-10-22', 'field', 'pitching_distance', '60.5', 'feet', 'Facility Guide', 'rule', 'Babe Ruth Baseball (13-18) uses 90-foot bases and 60 feet 6 inches to the pitcher''s plate.', 'https://www.baberuthleague.org/sitemedia/Babe%20Ruth%20Facility%20Guide%20TC2.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F117', 'BRL-FACILITY', 'softball', 'babe_ruth_league', NULL, 4, 18, 'undated, retrieved 2026-10-22', 'field', 'pitching_distance', '10U 35; 12U 40; 14U-18U 43', 'feet', 'Facility Guide', 'rule', 'Babe Ruth Softball uses 60-foot bases and pitches from 35 feet at 10U, 40 at 12U, and 43 at 14U-18U.', 'https://www.baberuthleague.org/sitemedia/Babe%20Ruth%20Facility%20Guide%20TC2.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F118', 'BRL-LIGHTNING', 'both', 'babe_ruth_league', NULL, NULL, NULL, 'undated, retrieved 2026-10-22', 'safety', 'lightning_wait', '30', 'minutes', 'Lightning Policy', 'rule', 'Babe Ruth League''s guidance is to stop play and get to an enclosed building or hard-top car when lightning is seen or thunder is heard. Dugouts and bleachers aren''t safe. Wait at least 30 minutes after the storm has passed before resuming.', 'https://www.baberuthleague.org/sitemedia/Lightning%20Policy.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F119', 'LL-AGE-BB-2026', 'baseball', 'little_league', NULL, NULL, NULL, '2026', 'age', 'league_age_rule', 'age on Aug 31 of the season year', NULL, 'age chart', 'rule', 'Little League baseball league age is the player''s age on August 31 of the season year. For 2026, a player born in January 2014 or September 2013 is league age 12.', 'https://www.littleleague.org/downloads/2026-baseball-age-chart/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Derived from the chart, so check one row by hand. Good candidate for a leagueAge() calculator.'),
  ('F120', 'LL-AGE-SB-2026', 'softball', 'little_league', NULL, NULL, NULL, '2026', 'age', 'league_age_rule', 'age on Dec 31 of the prior year', NULL, 'age chart', 'rule', 'Little League softball league age depends only on birth year: the player''s age on December 31 of the year before the season. For 2026, anyone born in 2013 is league age 12.', 'https://www.littleleague.org/downloads/2026-softball-age-chart/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Derived from the chart; check one row.'),
  ('F121', 'LL-AGE-CH-2026', 'baseball', 'little_league', 'Challenger', NULL, NULL, '2026', 'age', 'senior_challenger_eligibility', 'born before Sept 2011', NULL, 'age chart', 'rule', 'Challenger uses the same Aug 31 league-age chart as baseball. For 2026, players born before September 2011 are eligible for Senior League Challenger.', 'https://www.littleleague.org/downloads/2026-challenger-age-chart/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F122', 'LL-AGE-BB-2027', 'baseball', 'little_league', NULL, NULL, NULL, '2027', 'age', 'league_age_rule_2027', 'age on Aug 31, 2027', NULL, 'age chart', 'rule', 'The 2027 Little League baseball chart follows the same Aug 31 rule. A player born in September 2014 through August 2015 is league age 12 in 2027.', 'https://www.littleleague.org/downloads/2027-baseball-age-chart/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F123', 'LL-AGE-SB-2027', 'softball', 'little_league', NULL, NULL, NULL, '2027', 'age', 'league_age_rule_2027', 'birth year 2015 = 12', NULL, 'age chart', 'rule', 'The 2027 Little League softball chart follows the same birth-year rule. Players born in 2015 are league age 12 in 2027.', 'https://www.littleleague.org/downloads/2027-softball-age-chart/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F124', 'LL-SB-DIV', 'softball', 'little_league', 'Minor League', 5, 11, 'retrieved 2026-10-22', 'field', 'pitching_distance', '35', 'feet', 'division page', 'rule', 'Little League softball Minor League (ages 5-11) pitches from 35 feet on 60-foot bases.', 'https://www.littleleague.org/play-little-league/softball/divisions/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F125', 'LL-SB-DIV', 'softball', 'little_league', 'Little League (Major)', 9, 12, 'retrieved 2026-10-22', 'field', 'pitching_distance', '40', 'feet', 'division page', 'rule', 'Little League softball Little League (Major) (ages 9-12) pitches from 40 feet on 60-foot bases.', 'https://www.littleleague.org/play-little-league/softball/divisions/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F126', 'LL-SB-DIV', 'softball', 'little_league', 'Junior', 12, 14, 'retrieved 2026-10-22', 'field', 'pitching_distance', '43', 'feet', 'division page', 'rule', 'Little League softball Junior (ages 12-14) pitches from 43 feet on 60-foot bases.', 'https://www.littleleague.org/play-little-league/softball/divisions/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F127', 'LL-SB-DIV', 'softball', 'little_league', 'Senior', 12, 16, 'retrieved 2026-10-22', 'field', 'pitching_distance', '43', 'feet', 'division page', 'rule', 'Little League softball Senior (ages 12-16) pitches from 43 feet on 60-foot bases.', 'https://www.littleleague.org/play-little-league/softball/divisions/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F128', 'LL-SB-DIV', 'softball', 'little_league', 'Tee Ball', 4, 7, 'retrieved 2026-10-22', 'field', 'base_distance', '60 (league may use 50)', 'feet', 'division page', 'rule', 'Little League softball Tee Ball (ages 4-5, with a local option for 6-7) has no live pitching. Bases are 60 feet, or 50 at the league''s option.', 'https://www.littleleague.org/play-little-league/softball/divisions/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F129', 'LL-SIG-2024', 'softball', 'little_league', NULL, NULL, NULL, '2024', 'pitching', 'leaping_delivery', 'legal if pivot foot not replanted', NULL, 'Rules 2.00, 8.01(s), 8.05(a)', 'mixed', 'Since 2024, Little League softball allows leaping in the delivery. Both feet may leave the ground if they stay within the 24-inch width of the plate and the pivot foot isn''t replanted. A replant (crow hop) is illegal. Whether a replant happened is the umpire''s judgment.', 'https://littleleague.org/downloads/2024-rulebook-significant-changes', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: CONFLICT: the softball FAQ page (modified 2026-05-07) says a leaping, hopping or sidearm delivery is an illegal pitch under 8.05(d). Check the 2026 rulebook app and record which is current.'),
  ('F130', 'LL-SB-FAQ', 'softball', 'little_league', NULL, NULL, NULL, 'page modified 2026-05-07', 'pitching', 'illegal_pitch_effect', 'ball; offense may take the play', NULL, 'Rule 8.05 Penalty', 'rule', 'A Little League softball illegal pitch is a ball for the batter, and runners get no award. If a play follows, the offense may take the play instead. If every runner advances a base, the play stands.', 'https://www.littleleague.org/help-center/rule-interpretations-for-little-league-softball-faqs/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F131', 'LL-SB-FAQ', 'softball', 'little_league', NULL, NULL, NULL, 'page modified 2026-05-07', 'pitching', 'crow_hop_vs_drag', 'drag is legal; replant is a crow hop', NULL, 'Rule 2.00 (Crow Hop); 8.01(s)', 'judgment', 'Dragging the pivot foot is legal: it must push off and stay in contact with the ground. A crow hop means replanting the pivot foot before release. Telling the two apart is the umpire''s judgment.', 'https://www.littleleague.org/help-center/rule-interpretations-for-little-league-softball-faqs/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F132', 'LL-SB-FAQ', 'softball', 'little_league', 'Majors/Junior', NULL, NULL, 'page modified 2026-05-07', 'pitching_innings', 'junior_innings_count_toward_majors', 'true', NULL, 'Regulation VI(b), Example 3', 'rule', 'A softball pitcher may pitch in a Junior game and a Majors game on the same day, but innings from the Junior game count toward the 12-inning daily limit in the Majors.', 'https://www.littleleague.org/help-center/rule-interpretations-for-little-league-softball-faqs/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F133', 'LL-SB-FAQ', 'softball', 'little_league', NULL, NULL, NULL, 'page modified 2026-05-07', 'baserunning', 'circle_violation_procedure', 'runner out; no pitch', NULL, 'Rule 7.08(5)', 'mixed', 'When a runner leaves the base early in Little League softball, the umpire calls time and calls that runner out, rules ''no pitch'' if a pitch was thrown, and sends the other runners back. Whether the runner left early is the umpire''s judgment.', 'https://www.littleleague.org/help-center/rule-interpretations-for-little-league-softball-faqs/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F134', 'LL-SB-FAQ', 'softball', 'little_league', NULL, NULL, NULL, 'page modified 2026-05-07', 'equipment', 'tee_ball_bats_in_softball', 'not permitted', NULL, 'Rule 1.10', 'rule', 'Tee ball bats can''t be used in Little League softball.', 'https://www.littleleague.org/help-center/rule-interpretations-for-little-league-softball-faqs/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F135', 'LL-CHANGES-2026', 'both', 'little_league', NULL, NULL, NULL, '2026', 'equipment', 'thumb_protectors_2026', 'permitted', NULL, 'Rule 1.10, A.R. 2', 'rule', 'New for 2026: thumb protectors are allowed in Little League. Choke-knobs and choke-up assists are still banned.', 'https://www.littleleague.org/playing-rules/rule-changes/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F136', 'LL-CHANGES-2026', 'baseball', 'little_league', 'Intermediate/Junior/Senior', 11, 16, '2026', 'pitching', 'return_as_pitcher_2026', 'visits don''t block return', NULL, 'Rule 8.06(b) Note', 'rule', 'New for 2026: in Intermediate (50/70), Junior and Senior baseball, a pitcher removed from the mound may come back to pitch even if the team still has visits left. Softball got the same clarification for all divisions.', 'https://www.littleleague.org/playing-rules/rule-changes/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F137', 'LL-CHANGES-2026', 'both', 'little_league', NULL, NULL, NULL, '2026', 'game', 'forfeit_scorebook_2026', 'UIC signature not required', NULL, 'Rule 4.18', 'rule', 'New for 2026: the Umpire-in-Chief no longer has to sign the scorebook for a forfeited game.', 'https://www.littleleague.org/playing-rules/rule-changes/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F138', 'LL-NFHS-SB', 'softball', 'little_league', NULL, 4, 16, 'undated, retrieved 2026-10-22', 'obstruction', 'type_a_immediate', 'dead ball; one base beyond last touched', NULL, 'comparison sheet (Type A)', 'mixed', 'Little League softball has two kinds of obstruction. Type A covers a runner being played on: the ball is dead right away, and the runner gets one base past the last base touched. Other runners advance only if forced.', 'https://www.littleleague.org/downloads/nfhs-sb-comparison/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Closes the LL obstruction gap for softball. Undated comparison sheet; check against the 2026 rulebook app.'),
  ('F139', 'LL-NFHS-SB', 'softball', 'little_league', NULL, 4, 16, 'undated, retrieved 2026-10-22', 'obstruction', 'type_b_delayed', 'delayed dead; umpire awards bases at end of play', NULL, 'comparison sheet (Type B)', 'mixed', 'Type B obstruction covers a runner not being played on. Play continues; at the end the umpire calls time and awards the bases they judge the runner would have reached.', 'https://www.littleleague.org/downloads/nfhs-sb-comparison/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Undated comparison sheet; check against the 2026 rulebook app.'),
  ('F140', 'LL-NFHS-SB', 'softball', 'little_league', NULL, 4, 16, 'undated, retrieved 2026-10-22', 'obstruction', 'passing_obstructed_runner', 'following runner out', NULL, 'comparison sheet', 'rule', 'In Little League softball, a runner who passes an obstructed runner is out. Under NFHS rules, she isn''t.', 'https://www.littleleague.org/downloads/nfhs-sb-comparison/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Undated comparison sheet; check against the 2026 rulebook app.'),
  ('F141', 'LL-NFHS-SB', 'softball', 'nfhs', 'high school', NULL, NULL, 'undated, retrieved 2026-10-22', 'obstruction', 'all_delayed', 'delayed dead ball for all obstruction', NULL, 'comparison sheet', 'mixed', 'NFHS (high school) softball treats all obstruction as a delayed dead ball. The umpire awards the bases they judge the runner would have reached.', 'https://www.littleleague.org/downloads/nfhs-sb-comparison/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: NFHS rulebook is paid; this comes from Little League''s comparison. Undated comparison sheet; check against the 2026 rulebook app.'),
  ('F142', 'LL-NFHS-SB', 'softball', 'little_league', 'Majors', 9, 12, 'undated, retrieved 2026-10-22', 'game', 'game_length_run_rule', '6 innings; 15 after 3, 10 after 4', NULL, 'comparison sheet', 'rule', 'Little League Majors softball games are 6 innings (regulation after 4, or 3-1/2 if the home team leads). The run rule is 15 after 3 innings or 10 after 4.', 'https://www.littleleague.org/downloads/nfhs-sb-comparison/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Undated comparison sheet; check against the 2026 rulebook app.'),
  ('F143', 'LL-NFHS-SB', 'softball', 'little_league', 'Junior/Senior', 12, 16, 'undated, retrieved 2026-10-22', 'game', 'game_length_run_rule', '7 innings; 15 after 4, 10 after 5', NULL, 'comparison sheet', 'rule', 'Little League Junior and Senior softball games are 7 innings (regulation after 5). The run rule is 15 after 4 innings or 10 after 5.', 'https://www.littleleague.org/downloads/nfhs-sb-comparison/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Undated comparison sheet; check against the 2026 rulebook app.'),
  ('F144', 'LL-NFHS-SB', 'softball', 'little_league', NULL, 4, 16, 'undated, retrieved 2026-10-22', 'game', 'time_limit', 'none unless local league sets one', NULL, 'comparison sheet', 'rule', 'Little League softball has no time limit unless the local league sets one for the regular season. The international tiebreaker starts in the 7th inning.', 'https://www.littleleague.org/downloads/nfhs-sb-comparison/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Undated comparison sheet; check against the 2026 rulebook app.'),
  ('F145', 'LL-NFHS-SB', 'softball', 'little_league', 'Majors', 9, 12, 'undated, retrieved 2026-10-22', 'baserunning', 'head_first_slide', 'not allowed while advancing; runner out', NULL, 'comparison sheet', 'rule', 'In Little League Majors softball, a runner who slides head first while advancing is out. Junior and Senior allow head-first slides.', 'https://www.littleleague.org/downloads/nfhs-sb-comparison/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Undated comparison sheet; check against the 2026 rulebook app.'),
  ('F146', 'LL-NFHS-SB', 'softball', 'little_league', 'Majors+', 9, 16, 'undated, retrieved 2026-10-22', 'baserunning', 'leave_on_release', 'may leave on release of pitch', NULL, 'comparison sheet', 'rule', 'From Majors up, Little League softball runners may leave the base when the pitch is released. Leaving early is an immediate dead ball, and the runner is out.', 'https://www.littleleague.org/downloads/nfhs-sb-comparison/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Undated comparison sheet; check against the 2026 rulebook app.'),
  ('F147', 'LL-NFHS-SB', 'softball', 'little_league', 'Majors+', 9, 16, 'undated, retrieved 2026-10-22', 'baserunning', 'circle_rule', 'dead ball; violator out', NULL, 'comparison sheet', 'mixed', 'Little League softball uses a circle rule (NFHS calls it look-back). A runner who stays off base too long with the pitcher holding the ball in the circle is out, and the others go back.', 'https://www.littleleague.org/downloads/nfhs-sb-comparison/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Undated comparison sheet; check against the 2026 rulebook app.'),
  ('F148', 'LL-NFHS-SB', 'softball', 'little_league', 'Majors/Junior/Senior', 9, 16, 'undated, retrieved 2026-10-22', 'uncaught_third_strike', 'batter_may_run', 'permitted', NULL, 'comparison sheet', 'rule', 'The dropped-third-strike rule applies in Little League Majors, Junior and Senior softball.', 'https://www.littleleague.org/downloads/nfhs-sb-comparison/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Check Minor-division use in the rulebook. Undated comparison sheet; check against the 2026 rulebook app.'),
  ('F149', 'LL-NFHS-SB', 'softball', 'little_league', 'Majors', 9, 12, 'undated, retrieved 2026-10-22', 'pitching', 'conferences', '2 per game per pitcher; 1 per inning', NULL, 'comparison sheet', 'rule', 'A Little League softball pitcher gets 2 defensive conferences per game and 1 per inning. The next one removes her as pitcher.', 'https://www.littleleague.org/downloads/nfhs-sb-comparison/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Undated comparison sheet; check against the 2026 rulebook app.'),
  ('F150', 'LL-NFHS-SB', 'softball', 'little_league', NULL, 4, 16, 'undated, retrieved 2026-10-22', 'pitching', 'warmup_pitches', '8 or 1 minute', NULL, 'comparison sheet', 'rule', 'A Little League softball pitcher gets 8 warm-up pitches or one minute.', 'https://www.littleleague.org/downloads/nfhs-sb-comparison/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Undated comparison sheet; check against the 2026 rulebook app.');
INSERT INTO rules_facts (fact_code, source_id, sport, sanction, division, age_min, age_max, edition, topic, fact_key, fact_value, unit, rule_ref, call_type, summary, source_url, verified, verified_by, retrieved_on, verify_note) VALUES
  ('F151', 'LL-NFHS-SB', 'softball', 'little_league', NULL, 4, 16, 'undated, retrieved 2026-10-22', 'equipment', 'illegal_bat_penalty', 'batter out; one base coach removed; escalates', NULL, 'comparison sheet', 'rule', 'Using an illegal bat in Little League softball: the batter is out, the bat comes out, and the team loses one adult base coach for the game. A second violation ejects the manager in tournament play.', 'https://www.littleleague.org/downloads/nfhs-sb-comparison/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Undated comparison sheet; check against the 2026 rulebook app.'),
  ('F152', 'LL-NFHS-SB', 'softball', 'little_league', 'Majors', 9, 12, 'undated, retrieved 2026-10-22', 'equipment', 'metal_cleats', 'not permitted', NULL, 'comparison sheet', 'rule', 'Metal cleats aren''t allowed in Little League Majors softball. Junior and Senior allow them.', 'https://www.littleleague.org/downloads/nfhs-sb-comparison/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Undated comparison sheet; check against the 2026 rulebook app.'),
  ('F153', 'LL-NFHS-SB', 'softball', 'little_league', NULL, 4, 16, 'undated, retrieved 2026-10-22', 'protest', 'protestable', 'misapplied rule; ineligible player; ineligible pitcher', NULL, 'comparison sheet', 'rule', 'Little League softball protests are allowed only for misapplied rules, ineligible players and ineligible pitchers. NFHS leaves protests to each state association.', 'https://www.littleleague.org/downloads/nfhs-sb-comparison/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Undated comparison sheet; check against the 2026 rulebook app.'),
  ('F154', 'LL-NFHS-SB', 'softball', 'nfhs', 'high school', NULL, NULL, 'undated, retrieved 2026-10-22', 'pitching_innings', 'restrictions', 'none', NULL, 'comparison sheet', 'rule', 'NFHS (high school) softball has no pitching innings limits or rest requirements.', 'https://www.littleleague.org/downloads/nfhs-sb-comparison/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Undated comparison sheet; check against the 2026 rulebook app.'),
  ('F155', 'LL-NFHS-SB', 'softball', 'little_league', NULL, 4, 16, 'undated, retrieved 2026-10-22', 'appeal', 'live_ball_only', 'live ball appeal only', NULL, 'comparison sheet', 'rule', 'Little League softball allows only live-ball appeals. NFHS allows live or dead.', 'https://www.littleleague.org/downloads/nfhs-sb-comparison/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Undated comparison sheet; check against the 2026 rulebook app.'),
  ('F156', 'LL-DEMARINI-2013', 'softball', 'little_league', NULL, NULL, NULL, '2013-05-15', 'equipment', 'demarini_bustos_exception', 'permitted', NULL, '2013 memo', 'rule', 'Two 2013 DeMarini Bustos models (WTDXBPF-10 and WTDXBPX-12) carry both 1.15 and 1.20 BPF marks. Little League ruled them legal in all softball divisions.', 'https://www.littleleague.org/downloads/demarini-softball-mismarked-bpf-bats/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Old, narrow ruling; low priority.'),
  ('F157', 'LL-CHALLENGER-BUDDY', 'baseball', 'little_league', 'Challenger', NULL, NULL, 'undated, retrieved 2026-10-22', 'challenger', 'buddy_role', 'protect and assist', NULL, 'guidelines', 'rule', 'In Little League Challenger, a buddy''s job is to protect the player from batted and thrown balls and help only as much as that player needs. The help differs for every player.', 'https://www.littleleague.org/downloads/challenger-game-play-guidelines-buddies/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Guideline, not a rule.'),
  ('F158', 'LL-CHALLENGER-BUDDY', 'baseball', 'little_league', 'Challenger', NULL, NULL, 'undated, retrieved 2026-10-22', 'challenger', 'fielding_assist', 'adapt to mobility', NULL, 'guidelines', 'rule', 'Players with full mobility field softly hit balls themselves. For players using a walker or wheelchair, the buddy or a teammate fields the ball and hands it over so the player can make the throw. Talk to a player in a wheelchair at eye level.', 'https://www.littleleague.org/downloads/challenger-game-play-guidelines-buddies/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Guideline, not a rule.'),
  ('F159', 'LL-CHALLENGER-BUDDY', 'baseball', 'little_league', 'Challenger', NULL, NULL, 'undated, retrieved 2026-10-22', 'challenger', 'batting_tee_fallback', 'tee if pitch not hit', NULL, 'guidelines', 'rule', 'A Challenger batter first tries to hit a thrown pitch. If that doesn''t work, they move to a tee, with the buddy helping the swing if needed and making sure the bat is dropped before running.', 'https://www.littleleague.org/downloads/challenger-game-play-guidelines-buddies/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Guideline, not a rule.'),
  ('F160', 'LL-CHALLENGER-BUDDY', 'baseball', 'little_league', 'Challenger', NULL, NULL, 'undated, retrieved 2026-10-22', 'challenger', 'baserunning_and_inning_end', 'one base per hit; all stay until last runner scores', NULL, 'guidelines', 'rule', 'In Challenger, runners usually move up one base on each hit, with the buddy running alongside. At the end of an inning, everyone stays on the field until the last runner scores.', 'https://www.littleleague.org/downloads/challenger-game-play-guidelines-buddies/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Guideline, not a rule.'),
  ('F161', 'LL-F-ll-baseball-field-layout', 'baseball', 'little_league', 'Tee Ball/Minor/Major', 4, 12, 'diagram last updated 2018', 'field', 'field_dimensions', '60 ft bases; 46 ft pitching; 200 ft+ fence', 'feet', 'field diagram (2018)', 'rule', 'Little League baseball Majors and Minors (including Tee Ball, coach and machine pitch) play on 60-foot bases. The pitcher''s plate is 46 feet from home, and the fence is at least 200 feet away.', 'https://www.littleleague.org/downloads/ll-baseball-field-layout/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Values read from diagram text; confirm against the drawing.'),
  ('F162', 'LL-F-pitching-mound-ll-baseball', 'baseball', 'little_league', 'Minor/Major', 7, 12, 'diagram last updated 2018', 'field', 'mound', '10 ft circle; 46 ft', 'feet', 'mound diagram (2018)', 'rule', 'The Little League Majors/Minors mound is a 10-foot circle with the pitching plate 46 feet from the rear point of home plate.', 'https://www.littleleague.org/downloads/pitching-mound-ll-baseball/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Values read from diagram text; confirm against the drawing.'),
  ('F163', 'LL-F-field-layout-intermediate-baseball', 'baseball', 'little_league', 'Intermediate (50/70)', 11, 13, 'diagram last updated 2018', 'field', 'field_dimensions', '70 ft bases; 50 ft pitching; 200 ft+ fence', 'feet', 'field diagram (2018)', 'rule', 'Little League Intermediate (50/70) uses 70-foot bases, a 50-foot pitching distance and a 12-foot mound circle, with fences 200 feet or more.', 'https://www.littleleague.org/downloads/field-layout-intermediate-baseball/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Values read from diagram text; confirm against the drawing.'),
  ('F164', 'LL-F-jr-sl-baseball-field-layout', 'baseball', 'little_league', 'Junior/Senior', 12, 16, 'diagram last updated 2018', 'field', 'field_dimensions', '90 ft bases (Junior may use 80); 60 ft 6 in; 300 ft+ fence', 'feet', 'field diagram (2018)', 'rule', 'Little League Junior and Senior baseball use 90-foot bases (Junior may use 80) and a 60-foot 6-inch pitching distance from an 18-foot mound circle, with fences 300 feet or more.', 'https://www.littleleague.org/downloads/jr-sl-baseball-field-layout/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Values read from diagram text; confirm against the drawing.'),
  ('F165', 'LL-F-field-layout-challenger', 'baseball', 'little_league', 'Challenger', NULL, NULL, 'diagram last updated 2018', 'field', 'field_dimensions', '50 or 60 ft bases; 46 ft pitching; 165 ft+ fence', 'feet', 'field diagram (2018)', 'rule', 'The Little League Challenger field uses 50- or 60-foot bases, a 46-foot pitching distance and fences at least 165 feet away.', 'https://www.littleleague.org/downloads/field-layout-challenger/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Values read from diagram text; confirm against the drawing.'),
  ('F166', 'LL-F-field-layout-sl-challenger', 'baseball', 'little_league', 'Senior League Challenger', NULL, NULL, 'diagram last updated 2018', 'field', 'field_dimensions', '90 ft bases; 60 ft 6 in; 225 ft+ fence', 'feet', 'field diagram (2018)', 'rule', 'The Senior League Challenger field uses 90-foot bases and a 60-foot 6-inch pitching distance, with fences at least 225 feet away.', 'https://www.littleleague.org/downloads/field-layout-sl-challenger/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Values read from diagram text; confirm against the drawing.'),
  ('F167', 'LL-F-ll-softball-field-layout', 'softball', 'little_league', 'Tee Ball/Minor/Major', 4, 12, 'diagram last updated 2018', 'field', 'field_dimensions', '60 ft bases (Tee Ball may use 50); Minor 35 ft, Major 40 ft; 200 ft+ fence; 8 ft circle radius', 'feet', 'field diagram (2018)', 'rule', 'Little League softball Majors and Minors use 60-foot bases (Tee Ball may use 50) and an 8-foot circle radius. Minors pitch from 35 feet and Majors from 40, with fences 200 feet or more and a 3-foot running lane to first.', 'https://www.littleleague.org/downloads/ll-softball-field-layout/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Values read from diagram text; confirm against the drawing.'),
  ('F168', 'LL-F-field-layout-junior-senior-softball', 'softball', 'little_league', 'Junior/Senior', 12, 16, 'diagram last updated 2018', 'field', 'field_dimensions', '60 ft bases; 43 ft pitching; 200 ft+ fence', 'feet', 'field diagram (2018)', 'rule', 'Little League Junior and Senior softball use 60-foot bases and a 43-foot pitching distance, with fences 200 feet or more.', 'https://www.littleleague.org/downloads/field-layout-junior-senior-softball/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Values read from diagram text; confirm against the drawing.'),
  ('F169', 'LL-F-batters-box-major-minor-softball', 'softball', 'little_league', 'Minor/Major', NULL, NULL, 'diagram last updated 2018', 'field', 'catchers_box', 'foul lines extended 9 ft', NULL, 'batter''s box diagram (2018)', 'rule', 'In Little League softball Majors and Minors, the batter''s box is 3 by 7 feet. The catcher''s box is formed by extending the foul lines 9 feet behind home plate.', 'https://www.littleleague.org/downloads/batters-box-major-minor-softball/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Values read from diagram text; confirm against the drawing.'),
  ('F170', 'LL-F-batters-box-junior-senior-softball', 'softball', 'little_league', 'Junior/Senior', NULL, NULL, 'diagram last updated 2018', 'field', 'catchers_box', '10 ft x 8 ft 5 in', NULL, 'batter''s box diagram (2018)', 'rule', 'In Little League Junior and Senior softball, the catcher''s box is about 10 feet by 8 feet 5 inches, behind a 3-by-7-foot batter''s box.', 'https://www.littleleague.org/downloads/batters-box-junior-senior-softball/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Values read from diagram text; confirm against the drawing.'),
  ('F171', 'LL-D-parent-code-conduct', 'both', 'little_league', NULL, NULL, NULL, 'retrieved 2026-10-22', 'conduct', 'parent_respect_officials', 'respect officials; don''t confront at the field', NULL, 'Sport Parent Code of Conduct, item 15', 'rule', 'Under Little League''s parent code of conduct, parents respect the officials'' authority during games. They don''t question or confront coaches at the field; they set up a time and place to talk instead.', 'https://www.littleleague.org/downloads/parent-code-conduct/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Template. This is a template each local league adopts, so the exact wording varies by league.'),
  ('F172', 'LL-D-parent-code-conduct', 'both', 'little_league', NULL, NULL, NULL, 'retrieved 2026-10-22', 'conduct', 'parent_no_unsporting', 'no booing, taunting or profanity toward officials', NULL, 'Sport Parent Code of Conduct, item 6', 'rule', 'Parents and their guests agree not to boo, taunt or swear at officials, coaches, players or other parents.', 'https://www.littleleague.org/downloads/parent-code-conduct/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Template. This is a template each local league adopts, so the exact wording varies by league.'),
  ('F173', 'LL-D-parent-code-conduct', 'both', 'little_league', NULL, NULL, NULL, 'retrieved 2026-10-22', 'conduct', 'parent_violation_penalty', 'asked to leave; next game suspension; repeat escalates', NULL, 'Sport Parent Code of Conduct (preamble)', 'rule', 'A parent who behaves improperly at a game or practice can be asked to leave and suspended from the next game. Repeat violations can mean multiple games or the rest of the season.', 'https://www.littleleague.org/downloads/parent-code-conduct/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Template. This is a template each local league adopts, so the exact wording varies by league.'),
  ('F174', 'LL-D-parent-code-conduct', 'both', 'little_league', NULL, NULL, NULL, 'retrieved 2026-10-22', 'conduct', 'parent_learn_rules', 'parents learn the rules', NULL, 'Sport Parent Code of Conduct, item 4', 'rule', 'Parents agree to learn the rules of the game and the league''s policies.', 'https://www.littleleague.org/downloads/parent-code-conduct/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Template; useful framing for why the app exists. This is a template each local league adopts, so the exact wording varies by league.'),
  ('F175', 'LL-D-parent-code-conduct', 'both', 'little_league', NULL, NULL, NULL, 'retrieved 2026-10-22', 'conduct', 'parent_no_sideline_coaching', 'don''t coach unless an official coach', NULL, 'Sport Parent Code of Conduct, item 17', 'rule', 'Parents agree not to coach their own or other children during games and practices unless they''re an official team coach.', 'https://www.littleleague.org/downloads/parent-code-conduct/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Template. This is a template each local league adopts, so the exact wording varies by league.'),
  ('F176', 'LL-D-league-resource-guide', 'both', 'little_league', NULL, NULL, NULL, 'retrieved 2026-10-22', 'umpires', 'volunteer_no_certification', 'volunteers; no official certification', NULL, 'League Resource Guide (Umpires FAQ)', 'rule', 'Little League umpires are volunteers, and there''s no official umpire certification. Each league''s Umpire-in-Chief trains them, with support from Little League International.', 'https://www.littleleague.org/downloads/league-resource-guide/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Useful context for de-escalation: the umpire is usually a volunteer.'),
  ('F177', 'LL-D-league-resource-guide', 'both', 'little_league', 'regular season', NULL, NULL, 'retrieved 2026-10-22', 'protest', 'on_field_first', 'manager to umpire on the field first', NULL, 'League Resource Guide; Rule 4.19', 'rule', 'A Little League protest has to start with the manager telling the umpire on the field. Only then does it go to the league''s protest committee, and judgment calls won''t be considered.', 'https://www.littleleague.org/downloads/league-resource-guide/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F178', 'LL-D-regulation-va-12-year-old-waiver', 'baseball', 'little_league', 'Minor', 12, 12, 'retrieved 2026-10-22', 'eligibility', 'twelve_in_minors_waiver', 'waiver needed; can''t pitch', NULL, 'Regulation V(a)', 'rule', 'League-age 12 players must be drafted to Majors, Intermediate (50/70) or Junior. A 12-year-old can play Minors only with a waiver approved by the league board and the District Administrator. If approved, the player can''t pitch, can''t play All-Stars and can''t be moved up for the rest of that season.', 'https://www.littleleague.org/downloads/regulation-va-12-year-old-waiver/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F179', 'LL-D-residency-school-attendance-eligibility-requirements', 'both', 'little_league', NULL, NULL, NULL, 'retrieved 2026-10-22', 'eligibility', 'residence_or_school', 'live or attend school within boundaries', NULL, 'Residency and School Attendance requirements', 'rule', 'A Little League player may play for a league if they live within its boundaries or attend a school physically located inside them. Home schools, cyber schools and sports academies don''t count as school attendance.', 'https://www.littleleague.org/downloads/residency-school-attendance-eligibility-requirements/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F180', 'LL-D-residency-school-attendance-eligibility-requirements', 'both', 'little_league', NULL, NULL, NULL, 'retrieved 2026-10-22', 'eligibility', 'residence_proof', 'one document from each of three groups', NULL, 'Residency and School Attendance requirements', 'rule', 'Residence is proven with one document from each of three groups, such as a driver''s license, a government record and a utility bill, dated within the window the league sets. Moving into a league''s boundaries just to qualify for tournament play isn''t allowed.', 'https://www.littleleague.org/downloads/residency-school-attendance-eligibility-requirements/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Dates change each season.'),
  ('F181', 'LL-D-regulation-iid', 'both', 'little_league', NULL, NULL, NULL, 'retrieved 2026-10-22', 'eligibility', 'regulation_iid_claim', 'continued eligibility after a move or boundary change', NULL, 'Regulation II(d), II(a)', 'rule', 'Under Regulation II(d), a player who previously qualified may keep playing in their league after a move, a school change or a boundary change, and so may their siblings. The claim is filed once in a player''s career.', 'https://www.littleleague.org/downloads/regulation-iid/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Summary from the claim form; check the regulation text.'),
  ('F182', 'LL-D-pitching-eligibility-tracking-form', 'both', 'little_league', NULL, NULL, NULL, 'retrieved 2026-10-22', 'pitch_count', 'tracking_form_fields', 'date; pitches; league age; eligible again on', NULL, 'Regulation VI; tracking form', 'rule', 'Little League''s pitcher tracking form records the game date, pitches thrown, the pitcher''s league age and the date they''re eligible to pitch again. Manager signatures are a local option.', 'https://www.littleleague.org/downloads/pitching-eligibility-tracking-form/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F183', 'LL-D-5070-field-conversion', 'baseball', 'little_league', 'Intermediate (50/70)', 11, 13, 'retrieved 2026-10-22', 'field', 'dual_use_field', 'fence 200-275 ft; 70 ft bases added', 'feet', '50/70 conversion guide', 'rule', 'A standard 46/60 Little League field can also host Intermediate (50/70) by adding 70-foot base anchors and extending the infield dirt. A field used for both should have its fence 200 to 275 feet out.', 'https://www.littleleague.org/downloads/5070-field-conversion/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F184', 'LL-D-tournament-player-verification', 'both', 'little_league', 'tournament', NULL, NULL, 'retrieved 2026-10-22', 'eligibility', 'tournament_age_proof', 'birth record, federal/military record, or in-lieu statement', NULL, 'Tournament Player Verification', 'rule', 'For tournament (All-Star) play, a player''s age is proven with an official birth record, a federal or military record, or an in-lieu statement backed by documents from all four groups.', 'https://www.littleleague.org/downloads/tournament-player-verification/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F185', 'LL-D-tournament-player-verification', 'both', 'little_league', 'tournament', NULL, NULL, 'retrieved 2026-10-22', 'eligibility', 'tournament_residency_options', 'residence, school, or continuous participation', NULL, 'Tournament Player Verification; Regulation II', 'rule', 'A tournament player qualifies by residence (documents from three groups), by school enrollment inside the boundaries, or under Regulation II. Regulation II covers a player, or their sibling, who has played in the league continuously since league age 7 or younger.', 'https://www.littleleague.org/downloads/tournament-player-verification/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F186', 'LL-D-tournament-affidavit-supplemental', 'both', 'little_league', 'tournament', NULL, NULL, 'retrieved 2026-10-22', 'eligibility', 'school_participation_exception', 'school games can count toward tournament participation', NULL, 'Tournament Player Eligibility Condition 2; Regulation IX', 'rule', 'Teams claiming the school-participation exception for tournament eligibility list each player''s school and league games on a supplemental sheet. From Intermediate (50/70) up, special games can also count toward tournament participation.', 'https://www.littleleague.org/downloads/tournament-affidavit-supplemental/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Form only; check the exact game-count rule in the tournament rules.'),
  ('F187', 'LL-D-bat-decertification-marucci-cat5', 'baseball', 'little_league', 'Junior/Senior/Big League', 12, 18, '2012-02-27', 'equipment', 'decertified_bats_2012', 'Marucci CAT5 33; CAT5 Squared 34; Black 33/34', NULL, 'Rules 1.10, 6.06(d) (2012 memos)', 'rule', 'In 2012, Little League followed the NCAA''s BBCOR decertification of several Marucci bats: the CAT5 33-inch, the CAT5 Squared 34-inch, and the Black 33- and 34-inch. They''re illegal in Junior, Senior and Big League. The current list lives at USABat and BBCOR.', 'https://www.littleleague.org/downloads/bat-decertification-marucci-cat5/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Old memos; the live decertified list is the authority.'),
  ('F188', 'LL-D-helmet-manufacturer-letter', 'both', 'little_league', NULL, NULL, NULL, '2018 (cites NOCSAE release of 2018-05-08)', 'equipment', 'helmet_nocsae_and_faceguards', 'NOCSAE stamp required; add-ons may void certification', NULL, 'Helmet manufacturer letter (2018)', 'rule', 'Little League batting helmets must meet NOCSAE standards and carry the stamp. Adding a face protector such as a C-flap creates an untested model, and the manufacturer may void the certification. Families should get the manufacturer''s written confirmation that the helmet stays certified.', 'https://www.littleleague.org/downloads/helmet-manufacturer-letter/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Check the current rulebook for any later ruling on face guards.'),
  ('F189', 'LL-D-coach-pitch-12-week-program', 'baseball', 'little_league', 'Minor coach pitch', 6, 8, '2015', 'coaching', 'coach_ratio', '1 coach : 4 players', NULL, 'Coach-Pitch Program (2015)', 'rule', 'Little League''s coach-pitch curriculum recommends one coach for no more than four players during drills, so every child gets more reps and attention.', 'https://www.littleleague.org/downloads/coach-pitch-12-week-program/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Coaching guidance, not a rule.'),
  ('F190', 'LL-D-coach-pitch-12-week-program', 'baseball', 'little_league', 'Minor coach pitch', 6, 8, '2015', 'coaching', 'fear_of_ball', 'use plastic, soft-core or tennis balls first', NULL, 'Coach-Pitch Program (2015)', 'rule', 'Being afraid of the ball is normal at this age. The curriculum starts batting and fielding drills with plastic balls, soft-core tee balls or tennis balls until players are comfortable.', 'https://www.littleleague.org/downloads/coach-pitch-12-week-program/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Coaching guidance. Good for DevelopmentAgent.'),
  ('F191', 'LL-D-coach-pitch-12-week-program', 'baseball', 'little_league', 'Minor coach pitch', 6, 8, '2015', 'coaching', 'coach_pitch_position', 'kneel behind L-screen 25-30 ft; move to mound later', 'feet', 'Coach-Pitch Program (2015)', 'rule', 'For batting practice, the coach kneels behind an L-screen about 25 to 30 feet from the plate, so the batter sees the release clearly. Later in the season the coach moves to the mound, still behind the screen.', 'https://www.littleleague.org/downloads/coach-pitch-12-week-program/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Coaching guidance.'),
  ('F192', 'LL-D-coach-pitch-12-week-program', 'baseball', 'little_league', 'Minor coach pitch', 6, 8, '2015', 'safety', 'helmet_in_all_bat_drills', 'helmet always; bat only when batting', NULL, 'Coach-Pitch Program (2015)', 'rule', 'Every player wears a helmet in any drill with a bat. Players hold a bat only when it''s their turn, and carry it by the barrel to the box.', 'https://www.littleleague.org/downloads/coach-pitch-12-week-program/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Safety guidance.'),
  ('F193', 'LL-D-coach-pitch-12-week-program', 'baseball', 'little_league', 'Minor coach pitch', 6, 8, '2015', 'coaching', 'season_progression', 'grip and throw > catch > tee > soft toss > live; baserunning throughout', NULL, 'Coach-Pitch Program (2015)', 'rule', 'The 12-week coach-pitch plan builds in order: four-seam grip and throwing to a target, two-hand catching (below then above the waist), hitting off a tee, soft toss, then pitched balls. Baserunning, fly balls with a drop step and relays come later. The last week is about enjoying the game and reflecting on progress.', 'https://www.littleleague.org/downloads/coach-pitch-12-week-program/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Use as the progression model for 6-8 improvement plans.'),
  ('F194', 'LL-D-coach-pitch-12-week-program', 'baseball', 'little_league', 'Minor coach pitch', 6, 8, '2015', 'coaching', 'purpose', 'develop people, not stars', NULL, 'Coach-Pitch Program (2015)', 'rule', 'The curriculum states the main goal plainly: Little League is about growing well-rounded people, with confidence and a work ethic, not producing outstanding ballplayers.', 'https://www.littleleague.org/downloads/coach-pitch-12-week-program/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Framing for teachable moments.'),
  ('F195', 'LL-D-tee-ball-parents-guide', 'both', 'little_league', 'Tee Ball', 4, 7, 'retrieved 2026-10-22', 'game', 'tee_ball_format', 'non-competitive; 2 activities a week, 45-75 min', NULL, 'Tee Ball parents guide', 'rule', 'Little League Tee Ball (ages 4-7) is non-competitive. Leagues are encouraged to hold two activities a week, each 45 minutes to 1 hour 15 minutes, with parents staying at the field. The league supplies helmets, bats, balls and catcher''s gear; families usually buy the glove, pants and cleats.', 'https://www.littleleague.org/downloads/tee-ball-parents-guide/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F196', 'LL-D-tee-ball-program', 'both', 'little_league', 'Tee Ball', 4, 7, 'retrieved 2026-10-22', 'coaching', 'coach_pitch_in_tee_ball', 'second half only; 3-5 pitches then tee', NULL, 'Tee Ball Program', 'rule', 'If a Tee Ball league adds coach pitch, the curriculum suggests doing it only in the second half of the season, with 3 to 5 pitches per batter before going back to the tee. First-year players should hit off the tee all season.', 'https://www.littleleague.org/downloads/tee-ball-program/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Coaching guidance.'),
  ('F197', 'LL-D-tee-ball-parents-guide', 'both', 'little_league', NULL, NULL, NULL, 'retrieved 2026-10-22', 'eligibility', 'no_child_turned_away', 'financial hardship never excludes a child', NULL, 'Tee Ball parents guide', 'rule', 'Little League says no child may be turned away from playing for financial reasons. Leagues have options to keep it affordable.', 'https://www.littleleague.org/downloads/tee-ball-parents-guide/', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F198', 'NSA-FP-2026', 'softball', 'nsa', NULL, NULL, NULL, '2026', 'protest', 'protestable', 'misinterpretation; wrong rule; wrong penalty', NULL, 'Rule 11, Sec 2', 'rule', 'NSA fast pitch accepts protests only for a misinterpreted rule, an umpire applying the wrong rule, or the wrong penalty for a violation.', 'https://playnsa.com/wp-content/uploads/2025/12/2026-NSA-Fastpitch-Rulebook-P.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F199', 'NSA-FP-2026', 'softball', 'nsa', NULL, NULL, NULL, '2026', 'judgment', 'not_protestable: fair or foul', 'judgment', NULL, 'Rule 11, Sec 1', 'judgment', 'In NSA fast pitch, the call on fair or foul is the umpire''s judgment and can''t be protested.', 'https://playnsa.com/wp-content/uploads/2025/12/2026-NSA-Fastpitch-Rulebook-P.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F200', 'NSA-FP-2026', 'softball', 'nsa', NULL, NULL, NULL, '2026', 'judgment', 'not_protestable: safe or out', 'judgment', NULL, 'Rule 11, Sec 1', 'judgment', 'In NSA fast pitch, the call on safe or out is the umpire''s judgment and can''t be protested.', 'https://playnsa.com/wp-content/uploads/2025/12/2026-NSA-Fastpitch-Rulebook-P.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.');
INSERT INTO rules_facts (fact_code, source_id, sport, sanction, division, age_min, age_max, edition, topic, fact_key, fact_value, unit, rule_ref, call_type, summary, source_url, verified, verified_by, retrieved_on, verify_note) VALUES
  ('F201', 'NSA-FP-2026', 'softball', 'nsa', NULL, NULL, NULL, '2026', 'judgment', 'not_protestable: ball or strike', 'judgment', NULL, 'Rule 11, Sec 1', 'judgment', 'In NSA fast pitch, the call on ball or strike is the umpire''s judgment and can''t be protested.', 'https://playnsa.com/wp-content/uploads/2025/12/2026-NSA-Fastpitch-Rulebook-P.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F202', 'NSA-FP-2026', 'softball', 'nsa', NULL, NULL, NULL, '2026', 'judgment', 'not_protestable: whether a runner touched a base', 'judgment', NULL, 'Rule 11, Sec 1', 'judgment', 'In NSA fast pitch, the call on whether a runner touched a base is the umpire''s judgment and can''t be protested.', 'https://playnsa.com/wp-content/uploads/2025/12/2026-NSA-Fastpitch-Rulebook-P.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F203', 'NSA-FP-2026', 'softball', 'nsa', NULL, NULL, NULL, '2026', 'judgment', 'not_protestable: whether a runner left too soon on a caught fly', 'judgment', NULL, 'Rule 11, Sec 1', 'judgment', 'In NSA fast pitch, the call on whether a runner left too soon on a caught fly is the umpire''s judgment and can''t be protested.', 'https://playnsa.com/wp-content/uploads/2025/12/2026-NSA-Fastpitch-Rulebook-P.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F204', 'NSA-FP-2026', 'softball', 'nsa', NULL, NULL, NULL, '2026', 'judgment', 'not_protestable: whether a fly ball was caught legally', 'judgment', NULL, 'Rule 11, Sec 1', 'judgment', 'In NSA fast pitch, the call on whether a fly ball was caught legally is the umpire''s judgment and can''t be protested.', 'https://playnsa.com/wp-content/uploads/2025/12/2026-NSA-Fastpitch-Rulebook-P.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F205', 'NSA-FP-2026', 'softball', 'nsa', NULL, NULL, NULL, '2026', 'judgment', 'not_protestable: whether a ball was an infield fly', 'judgment', NULL, 'Rule 11, Sec 1', 'judgment', 'In NSA fast pitch, the call on whether a ball was an infield fly is the umpire''s judgment and can''t be protested.', 'https://playnsa.com/wp-content/uploads/2025/12/2026-NSA-Fastpitch-Rulebook-P.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F206', 'NSA-FP-2026', 'softball', 'nsa', NULL, NULL, NULL, '2026', 'judgment', 'not_protestable: whether interference happened', 'judgment', NULL, 'Rule 11, Sec 1', 'judgment', 'In NSA fast pitch, the call on whether interference happened is the umpire''s judgment and can''t be protested.', 'https://playnsa.com/wp-content/uploads/2025/12/2026-NSA-Fastpitch-Rulebook-P.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F207', 'NSA-FP-2026', 'softball', 'nsa', NULL, NULL, NULL, '2026', 'judgment', 'not_protestable: whether the field is fit or there is enough light', 'judgment', NULL, 'Rule 11, Sec 1', 'judgment', 'In NSA fast pitch, the call on whether the field is fit or there is enough light is the umpire''s judgment and can''t be protested.', 'https://playnsa.com/wp-content/uploads/2025/12/2026-NSA-Fastpitch-Rulebook-P.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F208', 'NSA-FP-2026', 'softball', 'nsa', NULL, NULL, NULL, '2026', 'judgment', 'arguing_judgment', 'grounds for ejection', NULL, 'Rule 10, Sec 5', 'judgment', 'NSA says there''s no appeal of a judgment call, and arguing one is grounds for ejecting the player or coach. Only the manager or captain may ask for a ruling, and only on a point of rules.', 'https://playnsa.com/wp-content/uploads/2025/12/2026-NSA-Fastpitch-Rulebook-P.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F209', 'NSA-FP-2026', 'softball', 'nsa', NULL, NULL, NULL, '2026', 'protest', 'timing', 'before next pitch', NULL, 'Rule 11, Sec 3', 'rule', 'An NSA protest must be announced to the plate umpire right away, before the next pitch, except for player eligibility. The umpire records the situation: inning, outs, batter and runners.', 'https://playnsa.com/wp-content/uploads/2025/12/2026-NSA-Fastpitch-Rulebook-P.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F210', 'NSA-FP-2026', 'softball', 'nsa', 'league', NULL, NULL, '2026', 'protest', 'written_league', 'within 48 hours', NULL, 'Rule 11, Sec 4', 'rule', 'In NSA league play, the written protest is generally due within 48 hours of the game.', 'https://playnsa.com/wp-content/uploads/2025/12/2026-NSA-Fastpitch-Rulebook-P.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F211', 'NSA-FP-2026', 'softball', 'nsa', 'tournament', NULL, NULL, '2026', 'protest', 'fee', '75 cash; bats 200 each', 'USD', 'Rule 11, Sec 5', 'rule', 'In NSA tournaments, play stops until a protest is resolved. The fee is $75 cash, refunded if upheld; eligibility is $75 per player and bat protests $200 per bat ($75 with a compression machine on site). Eligibility protests must come before the game ends.', 'https://playnsa.com/wp-content/uploads/2025/12/2026-NSA-Fastpitch-Rulebook-P.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F212', 'NSA-FP-2026', 'softball', 'nsa', NULL, NULL, NULL, '2026', 'obstruction', 'runner_penalty', 'delayed dead ball; award bases', NULL, 'Rule 8 (Obstruction effect)', 'mixed', 'NSA treats obstruction as a delayed dead ball, even if the umpire forgets to call it. If the runner is put out before the base the umpire judges they''d have reached, the ball is dead and bases are awarded. A runner put out after reaching that base stays out.', 'https://playnsa.com/wp-content/uploads/2025/12/2026-NSA-Fastpitch-Rulebook-P.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F213', 'NSA-FP-2026', 'softball', 'nsa', NULL, NULL, NULL, '2026', 'obstruction', 'fake_tag_ejection', 'automatic ejection', NULL, 'Rule 8 (Obstruction effect 4)', 'rule', 'In NSA fast pitch, a fielder who fakes a tag is automatically ejected, and the runners get the bases they''d have reached. USA Softball says the fielder ''may'' be ejected; NSA makes it automatic.', 'https://playnsa.com/wp-content/uploads/2025/12/2026-NSA-Fastpitch-Rulebook-P.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Cross-sanction difference worth showing.'),
  ('F214', 'NSA-FP-2026', 'softball', 'nsa', 'Girls 10U', NULL, NULL, '2026', 'field', 'pitching_distance', '35', 'feet', 'Rule 2 (distance table)', 'rule', 'NSA Girls 10U fast pitch pitches from 35 feet on 60-foot bases.', 'https://playnsa.com/wp-content/uploads/2025/12/2026-NSA-Fastpitch-Rulebook-P.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F215', 'NSA-FP-2026', 'softball', 'nsa', 'Girls 12U', NULL, NULL, '2026', 'field', 'pitching_distance', '40', 'feet', 'Rule 2 (distance table)', 'rule', 'NSA Girls 12U fast pitch pitches from 40 feet on 60-foot bases.', 'https://playnsa.com/wp-content/uploads/2025/12/2026-NSA-Fastpitch-Rulebook-P.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F216', 'NSA-FP-2026', 'softball', 'nsa', 'Girls 14U-18U', NULL, NULL, '2026', 'field', 'pitching_distance', '43', 'feet', 'Rule 2 (distance table)', 'rule', 'NSA Girls 14U-18U fast pitch pitches from 43 feet on 60-foot bases.', 'https://playnsa.com/wp-content/uploads/2025/12/2026-NSA-Fastpitch-Rulebook-P.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F217', 'NSA-FP-2026', 'softball', 'nsa', '8U coach pitch', NULL, 8, '2026', 'game', 'eight_u_rules', '5-run innings; no dropped third strike; no bunting', NULL, '8U rules section', 'rule', 'In NSA 8U, an inning ends after 3 outs or 5 runs. Runners may leave on the release but can''t steal home unless played on. There''s no bunting, no dropped third strike, and no hit-by-pitch award until a second hit in the same at-bat.', 'https://playnsa.com/wp-content/uploads/2025/12/2026-NSA-Fastpitch-Rulebook-P.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Check which 8U format (coach, machine or modified) each rule belongs to.'),
  ('F218', 'NSA-FP-2026', 'softball', 'nsa', 'odd-age', 9, 15, '2026', 'game', 'odd_age_play', 'play by next even age''s rules', NULL, 'Odd Age Tournaments section', 'rule', 'NSA odd-age tournaments (9U, 11U, 13U, 15U) use the next even age''s playing rules, except for roster rules.', 'https://playnsa.com/wp-content/uploads/2025/12/2026-NSA-Fastpitch-Rulebook-P.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F219', 'NSA-FP-2026', 'softball', 'nsa', NULL, NULL, NULL, '2026', 'pitching', 'pitch_limits', 'none found', NULL, 'n/a', 'rule', 'The 2026 NSA fast pitch rulebook has no youth pitch-count or innings limits.', 'https://playnsa.com/wp-content/uploads/2025/12/2026-NSA-Fastpitch-Rulebook-P.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Absence check; confirm.'),
  ('F220', 'NSA-FP-2026', 'softball', 'nsa', NULL, NULL, NULL, '2026', 'equipment', 'bat_standard', 'approved company + NSA2012 stamp', NULL, 'Approved Bat Company list', 'rule', 'An NSA-legal bat comes from an approved company and shows the NSA2012 stamp. Without a visible stamp, the bat isn''t legal for any NSA play.', 'https://playnsa.com/wp-content/uploads/2025/12/2026-NSA-Fastpitch-Rulebook-P.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F221', 'NSA-ALTERED', 'softball', 'nsa', NULL, NULL, NULL, 'undated', 'equipment', 'altered_bat_penalty', '2-5 year suspension; refusal = 5 years', NULL, 'Altered Bat and Ball Procedures', 'rule', 'A player suspected of using an altered bat or ball must allow inspection. Refusing means an immediate 5-year NSA suspension. A confirmed alteration means 2 to 5 years for a first offense and life for a second.', 'https://playnsa.com/wp-content/uploads/2022/01/NSA-Altered-Bat-and-Altered-Ball-Procedures.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F222', 'NSA-AGE-2027', 'softball', 'nsa', NULL, NULL, NULL, '2027 season (starts 2026-09-01)', 'age', 'age_cutoff', 'age on Aug 31 before the season', NULL, '2027 age chart', 'rule', 'NSA fast pitch age groups use the player''s age on August 31 before the season. The 2027 season runs Sept 1, 2026 to Aug 31, 2027. Players may play up a division but never down.', 'https://picture.nyc3.digitaloceanspaces.com/nsa/1635129949/cms-image-639196484023028490.png', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F223', 'NSA-YFP-CHG-2026', 'softball', 'nsa', NULL, NULL, NULL, '2025-11-06 vote, effective 2026-01-01', 'equipment', 'one_way_comms_2026', 'allowed; on-field repair = warning then ejection', NULL, 'Rule 5, Sec 11', 'rule', 'New for 2026: NSA allows one-way communication devices for calling pitches and plays. Players may wear the receiver, and the catcher may use an earpiece. A transmitter on the field, an on-field repair, or a two-way device draws a warning, then the head coach''s ejection.', 'https://playnsa.com/wp-content/uploads/2025/12/2026-Youth-Fast-Pitch-Rule-Changes-MS-1.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F224', 'NSA-YFP-CHG-2026', 'softball', 'nsa', NULL, NULL, NULL, '2025-11-06 vote, effective 2026-01-01', 'courtesy_runner', 'wrong_cr_2026', 'out on appeal', NULL, 'Rule 4, Sec 8', 'rule', 'New for 2026: using the wrong courtesy runner is an out if appealed before that runner crosses home.', 'https://playnsa.com/wp-content/uploads/2025/12/2026-Youth-Fast-Pitch-Rule-Changes-MS-1.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F225', 'NSA-YFP-CHG-2026', 'softball', 'nsa', NULL, NULL, NULL, '2025-11-06 vote, effective 2026-01-01', 'batting', 'moving_into_pitch_2026', 'strike or ball; batter stays', NULL, 'Rule 8, Sec 2 Exception', 'judgment', 'New for 2026: if the umpire judges the batter deliberately moved into the pitch, it''s a dead ball, called a strike or ball by location, and the batter stays at bat.', 'https://playnsa.com/wp-content/uploads/2025/12/2026-Youth-Fast-Pitch-Rule-Changes-MS-1.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F226', 'NSA-YFP-CHG-2026', 'softball', 'nsa', '8U modified', NULL, 8, '2025-11-06 vote, effective 2026-01-01', 'pitching', 'eight_u_modified_coach_pitch_2026', 'all pitching by coach', NULL, '2026 change', 'rule', 'New for 2026: all pitching in NSA 8U modified is done by the coach.', 'https://playnsa.com/wp-content/uploads/2025/12/2026-Youth-Fast-Pitch-Rule-Changes-MS-1.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F227', 'NSA-YFP-CHG-2026', 'softball', 'nsa', NULL, NULL, NULL, '2025-11-06 vote, effective 2026-01-01', 'conduct', 'noisemakers_2026', 'not allowed in championship play', NULL, 'Rule 5, Sec 10', 'rule', 'New for 2026: artificial noisemakers aren''t allowed in NSA championship play.', 'https://playnsa.com/wp-content/uploads/2025/12/2026-Youth-Fast-Pitch-Rule-Changes-MS-1.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F228', 'USAB-BATS', 'baseball', 'usa_baseball', '10U-12U events', 10, 12, 'retrieved 2026-10-22', 'equipment', 'bat_standard', 'USABat; 32 in max; 2-5/8', NULL, 'USA Baseball event bat guidelines', 'rule', 'At USA Baseball''s own 10U-12U events, bats may be at most 32 inches with a 2-5/8 inch barrel. Non-wood and multi-piece wood bats must be USABat certified.', 'https://www.usabaseball.com/bats/guidelines', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Applies to USA Baseball events only.'),
  ('F229', 'USAB-BATS', 'baseball', 'usa_baseball', '13U-15U events', 13, 15, 'retrieved 2026-10-22', 'equipment', 'bat_standard', 'one-piece wood or BBCOR -3; 34 in', NULL, 'USA Baseball event bat guidelines', 'rule', 'At USA Baseball 13U-15U events, players use one-piece wood, a BBCOR -3 bat, or an approved BBCOR wood-barrel bat, up to 34 inches.', 'https://www.usabaseball.com/bats/guidelines', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Applies to USA Baseball events only.'),
  ('F230', 'USAB-BATS', 'baseball', 'usa_baseball', '16U-18U events', 16, 18, 'retrieved 2026-10-22', 'equipment', 'bat_standard', 'wood or BBCOR wood-barrel only', NULL, 'USA Baseball event bat guidelines', 'rule', 'At USA Baseball 16U-18U events, only one-piece wood or approved BBCOR wood-barrel bats are allowed.', 'https://www.usabaseball.com/bats/guidelines', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Applies to USA Baseball events only.'),
  ('F231', 'USAB-BATS', 'baseball', 'usa_baseball', 'events', NULL, NULL, 'retrieved 2026-10-22', 'protest', 'timing', 'before next batter steps in', NULL, 'USA Baseball event bat guidelines', 'rule', 'At USA Baseball events, a protest must come before the next batter enters the box and is void once the first pitch is thrown. If upheld, the protesting team chooses an automatic out or the result of the play.', 'https://www.usabaseball.com/bats/guidelines', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Applies to USA Baseball events only.'),
  ('F232', 'USAB-BYLAWS', 'baseball', 'usa_baseball', NULL, NULL, NULL, 'retrieved 2026-10-22', 'governance', 'national_governing_body', 'USA Baseball', NULL, 'bylaws page', 'rule', 'USA Baseball is the national governing body for amateur baseball in the US. It runs the USABat standard and co-runs Pitch Smart with MLB, but member leagues such as Little League write their own playing rules.', 'https://www.usabaseball.com/about/governance/bylaws', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F233', 'USSSA-BB-NAT', 'baseball', 'usssa', NULL, 7, 18, 'edition dated 2024-08-01, revised 2024-08-16', 'pitching', 'removed_pitcher_no_return', 'can''t return as pitcher', NULL, 'Rule 7.05.A', 'rule', 'In USSSA baseball, a pitcher removed from the mound can''t pitch again in that game. If it happens, the defense just swaps in a legal pitcher, unless the pitcher had no innings left, which makes it a pitching-limit violation.', 'https://www.usssabaseball.org/images/2024/USSSA_National_By-Laws8-16-2024.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F234', 'USSSA-BB-NAT', 'baseball', 'usssa', NULL, 7, 18, 'edition dated 2024-08-01, revised 2024-08-16', 'pitching_innings', 'end_of_day', 'night break, not midnight', NULL, 'Rule 7.05.B', 'rule', 'For USSSA pitching limits, a ''day'' ends when the ballpark shuts down for the night, not at midnight. A suspended game finished the next day counts as two separate days.', 'https://www.usssabaseball.org/images/2024/USSSA_National_By-Laws8-16-2024.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Important for an innings calculator.'),
  ('F235', 'USSSA-BB-NAT', 'baseball', 'usssa', NULL, 7, 18, 'edition dated 2024-08-01, revised 2024-08-16', 'pitching_innings', 'forfeit_and_double_play', 'forfeit outs count; DP/TP overage excused', NULL, 'Rules 7.05.B.6-7', 'rule', 'Outs from a game that ends in forfeit still count toward USSSA innings limits. A pitcher violates the limit by recording any out beyond it, except that going over on a double or triple play isn''t a violation (it still counts toward next-day eligibility).', 'https://www.usssabaseball.org/images/2024/USSSA_National_By-Laws8-16-2024.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F236', 'USSSA-BB-NAT', 'baseball', 'usssa', NULL, 7, 18, 'edition dated 2024-08-01, revised 2024-08-16', 'pitching_innings', 'who_enforces', 'teams must challenge', NULL, 'Rule 7.05.B.8', 'rule', 'Each team must catch pitching violations itself: tell the umpire, then protest to the tournament director while the pitcher is still in the game after going over. The penalty is a forfeit.', 'https://www.usssabaseball.org/images/2024/USSSA_National_By-Laws8-16-2024.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F237', 'USSSA-BB-NAT', 'baseball', 'usssa', NULL, 7, 18, 'edition dated 2024-08-01, revised 2024-08-16', 'pitching', 'mound_visits', '2 coach visits per inning; 2nd to same pitcher = change', NULL, 'Rule 7.05.C', 'rule', 'USSSA allows two coach visits per inning. A second visit to the same pitcher in the same inning means a pitching change.', 'https://www.usssabaseball.org/images/2024/USSSA_National_By-Laws8-16-2024.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F238', 'USAB-FAQ', 'baseball', 'usa_baseball', NULL, NULL, NULL, 'retrieved 2026-10-22', 'age', 'usab_domestic_age_date', 'April 30', NULL, 'USA Baseball FAQ', 'rule', 'USA Baseball''s domestic age date is April 30: a player''s age on that date is their age for the season. International (WBSC) events use January 1.', 'https://www.usabaseball.com/about/faq', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: CONFLICT: Little League''s own charts and NSA use August 31. Treat this as USA Baseball''s event rule, not every league''s. Ask which sanction applies.'),
  ('F239', 'USAB-FAQ', 'baseball', 'usa_baseball', 'international', NULL, NULL, 'retrieved 2026-10-22', 'age', 'wbsc_age_date', 'January 1 (calendar year)', NULL, 'USA Baseball FAQ', 'rule', 'USA Baseball national teams follow WBSC international age rules by birth year. For 2026, 12U is born in 2014 or later, 15U 2011 or later, and 18U 2008 or later.', 'https://www.usabaseball.com/about/faq', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F240', 'USAB-FAQ', 'baseball', 'usa_baseball', NULL, NULL, NULL, 'retrieved 2026-10-22', 'equipment', 'usabat_adopters', 'AABC, Babe Ruth/Cal Ripken, Diamond Youth/Boys, Little League, PONY, NABF, Dizzy Dean', NULL, 'USA Baseball FAQ', 'rule', 'The USABat standard is used by AABC, Babe Ruth/Cal Ripken, Diamond Youth and Diamond Boys, Little League, PONY (6U-14U), NABF (10U-14U) and Dizzy Dean (6-12).', 'https://www.usabaseball.com/about/faq', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: USSSA isn''t on the list; it has its own bat standard.'),
  ('F241', 'USAB-FAQ', 'baseball', 'usa_baseball', NULL, NULL, NULL, 'retrieved 2026-10-22', 'equipment', 'usabat_basics', 'no drop limit; marked and listed', NULL, 'USA Baseball FAQ', 'rule', 'A USABat-legal bat carries the USA Baseball mark and appears on the approved list. There''s no drop-weight limit. Solid one-piece wood bats are legal with or without the mark. Tee ball bats go only with approved tee balls.', 'https://www.usabaseball.com/about/faq', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F242', 'USAB-FAQ', 'baseball', 'usa_baseball', NULL, NULL, NULL, 'retrieved 2026-10-22', 'equipment', 'decertification', 'by length; immediate', NULL, 'USA Baseball FAQ', 'rule', 'USA Baseball can retest any approved bat bought at retail. Decertification takes effect immediately, mid-season included, and can hit only certain lengths of a model. The maker must make buyers whole.', 'https://www.usabaseball.com/about/faq', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F243', 'USAB-FAQ', 'baseball', 'usa_baseball', 'events', NULL, NULL, 'retrieved 2026-10-22', 'safety', 'safesport_wristband', 'compliance required to be with minors', NULL, 'USA Baseball FAQ', 'rule', 'At USA Baseball events, coaches, umpires and trainers need a background check, yearly SafeSport training and a signed abuse-prevention policy. Compliant adults wear a wristband that lets them into athlete areas.', 'https://www.usabaseball.com/about/faq', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Event policy; points to safety resources, not rulings.'),
  ('F244', 'USAB-NTC', 'baseball', 'usa_baseball', 'National Training Complex', NULL, NULL, 'retrieved 2026-10-22', 'safety', 'lightning_vehicles', 'wait in vehicles until all-clear', NULL, 'NTC guidelines', 'rule', 'At USA Baseball''s National Training Complex, everyone waits in their vehicle during lightning until an all-clear is announced. Spectators must respect officials and avoid profanity or threats.', 'https://www.usabaseball.com/about/national-training-complex/guidelines', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Venue rule.'),
  ('F245', 'USAB-B5', 'both', 'wbsc', NULL, NULL, NULL, 'retrieved 2026-10-22', 'game', 'baseball5', '5-a-side; ball only; WBSC', NULL, 'Baseball5 page', 'rule', 'Baseball5 is WBSC''s five-a-side, mixed-gender street version of the game, played with just a rubber ball and no pitcher. Games take 15 to 20 minutes.', 'https://www.usabaseball.com/about/baseball5', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Background; not a ruling topic.'),
  ('F246', 'USAB-BBCOR', 'baseball', 'usa_baseball', 'high school/college', NULL, NULL, 'announced 2026-07-02', 'equipment', 'usa_bbcor_transition', 'USA Baseball now runs BBCOR', NULL, 'About USA BBCOR (2026-07-02)', 'rule', 'Since July 2026, USA Baseball runs the BBCOR standard, renamed USA BBCOR, taking it over from the NCAA. Performance limits haven''t changed. New bats will say ''USA Baseball BBCOR Certified .50'', with no stickers or decals accepted.', 'https://www.usabaseball.com/bats/about-bbcor', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F247', 'USAB-BBCOR', 'baseball', 'usa_baseball', 'high school/college', NULL, NULL, 'announced 2026-07-02', 'equipment', 'usa_bbcor_dates', 'retail 2027-07-01; NCAA-only 2029', NULL, 'About USA BBCOR', 'rule', 'USA BBCOR bats reach stores July 1, 2027 and become legal in college and high school play from 2028. NCAA allows only USA BBCOR from January 1, 2029. High schools keep accepting older BBCOR bats indefinitely and add USABat -4, -5 and -6 bats from 2028.', 'https://www.usabaseball.com/bats/about-bbcor', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Little League says the change doesn''t affect its 2026 or 2027 seasons (LL-BAT).'),
  ('F248', 'USAB-MATRIX', 'baseball', 'usa_baseball', NULL, 4, 16, 'retrieved 2026-10-22 (rendered)', 'development', 'adm_stages', 'Activate; Discover; Progress; Develop', NULL, 'Youth Baseball Skills Matrix', 'rule', 'USA Baseball''s American Development Model has four stages. Activate (to age 7) is about fun, play and basic movement. Discover (7-12) builds fundamentals in organized play. Progress (12-14) hones mechanics and independence. Develop (14-16) adds individual training and recovery.', 'https://usabdevelops.com/page/5007/youth-baseball-skills-matrix', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Use stage to choose age-appropriate improvement plans.'),
  ('F249', 'USAB-MATRIX-S1', 'baseball', 'usa_baseball', 'Stage 1', 4, 7, 'retrieved 2026-10-22 (rendered)', 'development', 'stage1_skills', 'grip, one-step throw, two hands, tee, run the bases in order', NULL, 'Skills Matrix Stage 1', 'rule', 'For players up to age 7, the matrix focuses on the basics: gripping and throwing with one step, catching with good feet and glove position, fielding with two hands in front of the ball, hitting off a tee, knowing the bases and running them in order, and a straight-leg slide.', 'https://usabdevelops.com/page/5008/stage-1-activate/17231/skills-matrix-stage-1-activate', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F250', 'USAB-MATRIX-S2A', 'baseball', 'usa_baseball', 'Stage 2 (7-9)', 7, 9, 'retrieved 2026-10-22 (rendered)', 'development', 'stage2a_skills', 'adds strike zone, rounding first, force outs, tag ups', NULL, 'Skills Matrix Stage 2 (7-9)', 'rule', 'For ages 7-9 the matrix adds learning the strike zone, loading and striding, front toss, backhands, hitting the cutoff, running through and rounding first, force outs, tagging up, and basic catcher stance and equipment.', 'https://usabdevelops.com/page/5009/stage-2-discover', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.');
INSERT INTO rules_facts (fact_code, source_id, sport, sanction, division, age_min, age_max, edition, topic, fact_key, fact_value, unit, rule_ref, call_type, summary, source_url, verified, verified_by, retrieved_on, verify_note) VALUES
  ('F251', 'USAB-MATRIX-S2B', 'baseball', 'usa_baseball', 'Stage 2 (10-12)', 10, 12, 'retrieved 2026-10-22 (rendered)', 'development', 'stage2b_skills', 'adds swing path, timing, bunting, DP pivots, drop steps, basic pitching mechanics', NULL, 'Skills Matrix Stage 2 (10-12)', 'rule', 'For ages 10-12 the matrix adds swing path, rhythm and timing, an approach at the plate, sacrifice bunting, double-play pivots and feeds, drop steps on fly balls, and basic pitching mechanics (wind-up vs. stretch, fastball grips, follow-through).', 'https://usabdevelops.com/page/5009/stage-2-discover', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Pitching here is mechanics only; pair with the Pitch Smart workload facts.'),
  ('F252', 'USAB-MATRIX-S2A', 'baseball', 'usa_baseball', 'Stage 2 (7-9)', 7, 9, 'retrieved 2026-10-22 (rendered)', 'coaching', 'practice_outline_7_9', '2-2.5 h; drills 15-20 min; varied', 'minutes', 'Skills Matrix Stage 2 (7-9)', 'rule', 'A 7-9 practice in the matrix runs 2 to 2.5 hours, with each drill kept to about 15 to 20 minutes and plenty of variety. Every practice includes a warm-up (10 min), baserunning (10-15), throwing and catching (10), fielding (15-20), tee work (15-20) and coach-pitch batting practice (25-30).', 'https://usabdevelops.com/page/5009/stage-2-discover', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F253', 'USAB-MATRIX-S2B', 'baseball', 'usa_baseball', 'Stage 2 (10-12)', 10, 12, 'retrieved 2026-10-22 (rendered)', 'coaching', 'practice_outline_10_12', '2.5 h; BP 45-60 min', 'minutes', 'Skills Matrix Stage 2 (10-12)', 'rule', 'A 10-12 practice runs about 2.5 hours. Every practice includes a 15-minute warm-up, baserunning (15-20), throwing and catching (10-15), fielding (30), team situations (20) and 45 to 60 minutes of batting practice that doubles as defense and baserunning work.', 'https://usabdevelops.com/page/5009/stage-2-discover', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F254', 'USAB-DRILL-INTERVAL', 'baseball', 'usa_baseball', NULL, 9, 18, 'retrieved 2026-10-22 (rendered)', 'coaching', 'interval_throwing', 'one knee 5-10 ft up to 120-140 ft, then back to 45', 'feet', 'Interval Throwing drill', 'rule', 'USA Baseball''s interval throwing warm-up starts on one knee at 5 to 10 feet and works back through set distances, with about 10 throws each, out to 120 to 140 feet for older players. It finishes by coming back in to 45 feet. Throws stay on a line; a bounce is fine.', 'https://usabdevelops.com/page/1524/practice-plans/playlists/16/1-hour-infield-workout/3093/interval-throwing', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Scale the maximum distance down for younger players.'),
  ('F255', 'USAB-DRILL-123', 'baseball', 'usa_baseball', NULL, 7, 14, 'retrieved 2026-10-22 (rendered)', 'coaching', 'drill_format_model', 'skill; difficulty; athletes; time; equipment; goal; steps; add difficulty', NULL, '1-2-3 Drill page', 'rule', 'Each USA Baseball drill lists the skill, difficulty, number of players and coaches, time, equipment, a one-line goal, numbered steps, and an ''add difficulty'' variation. The 1-2-3 tee drill, for example, breaks a swing into load, stride and swing on a partner''s count.', 'https://usabdevelops.com/page/1363/drills/3310/1-2-3-drill', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Use this format as the model for our drills table.'),
  ('F256', 'USAB-PLAN-CATCH', 'baseball', 'usa_baseball', NULL, 10, 18, 'retrieved 2026-10-22 (rendered)', 'coaching', 'one_hour_catching', '15 min warm-up; receiving 25; blocking 20', 'minutes', '1 Hour Catching Workout', 'rule', 'USA Baseball''s one-hour catching workout is a 15-minute throwing warm-up, then 5-minute receiving drills (soft hands, sway, sticking the pitch) and 5-minute blocking drills that build up to block, recover and throw.', 'https://usabdevelops.com/page/1524/practice-plans/playlists/14', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F257', 'USAB-MANUAL', 'baseball', 'usa_baseball', NULL, 4, 18, 'retrieved 2026-10-22', 'conduct', 'coach_no_judgment_challenge', 'discuss rules, not judgment', NULL, 'Youth Baseball Manual (Coach Code of Conduct)', 'judgment', 'USA Baseball''s coach code says coaches keep discussions with umpires to the rules and don''t challenge judgment calls. Publicly criticizing umpires or players is called unethical, as is stirring up players or fans against umpires.', 'https://api.mobilecoach.org/static/asset/pdf/131_b1db57b6-26fc-4cc0-98d0-b2c1f60cfa6d_default.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Core support for the ''it''s the umpire''s call'' explanation.'),
  ('F258', 'USAB-MANUAL', 'baseball', 'usa_baseball', NULL, 4, 18, 'retrieved 2026-10-22', 'conduct', 'teach_respect_for_umpires', 'coach teaches players how to address umpires', NULL, 'Youth Baseball Manual (In-Game Management)', 'rule', 'Coaches are expected to teach players, especially pitchers and catchers who work most closely with the umpire, to speak to umpires respectfully. Rival coaches should greet each other before and after games to set the tone.', 'https://api.mobilecoach.org/static/asset/pdf/131_b1db57b6-26fc-4cc0-98d0-b2c1f60cfa6d_default.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F259', 'USAB-MANUAL', 'baseball', 'usa_baseball', NULL, 4, 18, 'retrieved 2026-10-22', 'channel', 'parent_coach_conflict', 'meet at a time the coach sets, with the athlete present', NULL, 'Youth Baseball Manual (Managing Conflicts)', 'rule', 'For parent concerns, the manual recommends setting ground rules at a preseason meeting and meeting at a time and place the coach picks, not right after a game. The athlete should be in the meeting. Coach and athlete try to resolve things first; the coach listens and avoids comparing players.', 'https://api.mobilecoach.org/static/asset/pdf/131_b1db57b6-26fc-4cc0-98d0-b2c1f60cfa6d_default.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Key source for the ''appropriate channel'' answer.'),
  ('F260', 'USAB-MANUAL', 'baseball', 'usa_baseball', NULL, 4, 18, 'retrieved 2026-10-22', 'channel', 'off_limits_topics', 'playing time, position and lineup are the coach''s call', NULL, 'Youth Baseball Manual (Managing Conflicts)', 'rule', 'The manual suggests coaches tell parents up front that playing time, positions and batting order aren''t topics for parent meetings unless the coach raises them.', 'https://api.mobilecoach.org/static/asset/pdf/131_b1db57b6-26fc-4cc0-98d0-b2c1f60cfa6d_default.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Team-level guidance; leagues may differ.'),
  ('F261', 'USAB-MANUAL', 'baseball', 'usa_baseball', NULL, 4, 18, 'retrieved 2026-10-22', 'safety', 'base_and_first_aid', 'BASE compliance; emergency plan', NULL, 'Youth Baseball Manual (Health and Safety)', 'rule', 'USA Baseball''s manual asks every coach to complete BASE abuse-prevention compliance and to have an emergency and first-aid plan in place. It also points to Pitch Smart for arm health.', 'https://api.mobilecoach.org/static/asset/pdf/131_b1db57b6-26fc-4cc0-98d0-b2c1f60cfa6d_default.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F262', 'USAB-MATRIX-S3', 'baseball', 'usa_baseball', 'Stage 3 (12-14)', 12, 14, 'retrieved 2026-10-22', 'development', 'stage3_skills', 'adds leads, steals, squeeze, hit and run, 2-strike approach, off-speed grips', NULL, 'Skills Matrix Stage 3 (12-14)', 'rule', 'For ages 12-14 the matrix adds primary and secondary leads, reading balls in the dirt, stealing second and third, the infield fly rule, pop-up and hook slides, squeeze and drag bunts, hit and run, a two-strike approach, pitch recognition and off-speed grips.', 'https://api.mobilecoach.org/static/asset/pdf/131_c8c1788e-1ecb-4f6f-8a59-1a03d0946a44_default.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Closes the Stage 3 gap. Off-speed here is grips; pair with Pitch Smart guidance on breaking balls.'),
  ('F263', 'USAB-MATRIX-S2B-PDF', 'baseball', 'usa_baseball', 'Stage 2 (10-12)', 10, 12, 'retrieved 2026-10-22', 'coaching', 'drill_length_10_12', '20-25 minutes', 'minutes', 'Skills Matrix PDF (10-12)', 'rule', 'The 10-12 matrix PDF suggests keeping each drill to about 20 to 25 minutes and varying them, a bit longer than the 15 to 20 recommended for 7-9.', 'https://api.mobilecoach.org/static/asset/pdf/131_0d4b3c90-38fa-4a4d-ab7a-a818b6471076_default.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: The web page and the PDF differ slightly; this follows the PDF.'),
  ('F264', 'USAB-DRILL-SOFTHANDS', 'baseball', 'usa_baseball', NULL, 9, 14, 'retrieved 2026-10-22', 'drill_model', 'catching', 'see summary', NULL, 'drill sheet', 'rule', 'Tennis Ball Soft Hands: the catcher lets the ball travel and receives with a soft hand instead of reaching. Easy, 5 minutes, catcher''s gear and a bucket of tennis balls.', 'https://api.mobilecoach.org/content/pdf/AssetPDF_03797_default.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Model for writing our own drill; ages are our estimate.'),
  ('F265', 'USAB-DRILL-FLYBALLS', 'baseball', 'usa_baseball', NULL, 7, 14, 'retrieved 2026-10-22', 'drill_model', 'outfield', 'see summary', NULL, 'drill sheet', 'rule', 'Fly Balls: players move to get under the ball and catch it in front of the hat brim. Easy, 5 minutes, partners with balls and gloves.', 'https://api.mobilecoach.org/content/pdf/AssetPDF_03727_default.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Model for writing our own drill; ages are our estimate.'),
  ('F266', 'USAB-DRILL-OFCOMM', 'baseball', 'usa_baseball', NULL, 9, 14, 'retrieved 2026-10-22', 'drill_model', 'outfield', 'see summary', NULL, 'drill sheet', 'rule', 'Outfield Communication: outfielders call for the ball and back each other up. Easy, 10-15 minutes; add middle infielders to make it harder.', 'https://api.mobilecoach.org/content/pdf/AssetPDF_03578_default.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Model for writing our own drill; ages are our estimate.'),
  ('F267', 'USAB-DRILL-SHORTHOPS', 'baseball', 'usa_baseball', NULL, 9, 14, 'retrieved 2026-10-22', 'drill_model', 'outfield', 'see summary', NULL, 'drill sheet', 'rule', 'Short Hops: field the ball right as it bounces, pushing the glove through it. Medium, 5 minutes, partners.', 'https://api.mobilecoach.org/content/pdf/AssetPDF_03641_default.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Model for writing our own drill; ages are our estimate.'),
  ('F268', 'USAB-DRILL-GROUNDERS', 'baseball', 'usa_baseball', NULL, 7, 14, 'retrieved 2026-10-22', 'drill_model', 'outfield', 'see summary', NULL, 'drill sheet', 'rule', 'Grounders: field outfield ground balls outside the glove-side foot with head down and eyes on the ball. Easy, 5 minutes, partners.', 'https://api.mobilecoach.org/content/pdf/AssetPDF_03573_default.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Model for writing our own drill; ages are our estimate.'),
  ('F269', 'USAB-MATRIX-S4', 'baseball', 'usa_baseball', 'Stage 4 (14-16)', 14, 16, 'retrieved 2026-10-22', 'development', 'stage4_skills', 'adds pick moves, slide step, pitch-outs, back picks, tandem relays, 1st-and-3rd plays, PFP', NULL, 'Skills Matrix Stage 4 (14-16)', 'rule', 'For ages 14-16 the matrix keeps the Stage 3 hitting and baserunning work and adds pitchers holding runners (pick moves, slide step, pitch-outs), catcher back-picks and plays at the plate, tandem relays, first-and-third offense and defense, and pitcher fielding practice.', 'https://api.mobilecoach.org/static/asset/pdf/131_9ed15016-b2a8-43cb-945b-3a41bc653480_default.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F270', 'USAB-MATRIX-S4', 'baseball', 'usa_baseball', 'Stage 4 (14-16)', 14, 16, 'retrieved 2026-10-22', 'coaching', 'practice_outline_14_16', '2.5-3 h; drills 20-25 min; BP 45-60 min', 'minutes', 'Skills Matrix Stage 4 (14-16)', 'rule', 'A 14-16 practice runs 2.5 to 3 hours with varied drills of about 20 to 25 minutes. Every practice includes a warm-up (15), baserunning (15-20), throwing (10-15), fielding (30), pitcher and catcher work, team situations (20-25) and 45 to 60 minutes of batting practice.', 'https://api.mobilecoach.org/static/asset/pdf/131_9ed15016-b2a8-43cb-945b-3a41bc653480_default.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F271', 'USAB-ADM-DOC', 'baseball', 'usa_baseball', NULL, 4, 18, 'retrieved 2026-10-22 (26 pages)', 'development', 'practice_vs_competition', '75/25 to age 12; 65/35 at 12-18 (recreational)', 'percent', 'ADM: Recommended Frequency by Stage', 'rule', 'On the recreational track, USA Baseball''s development model recommends about 75% practice or deliberate play and no more than 25% games through age 12. From 12 to 18 the split is 65% practice and 35% games.', 'https://api.mobilecoach.org/static/asset/pdf/131_fbf15163-2aab-422d-9205-6c36fade758d_default.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Guidance, not a rule. Strong basis for ''more practice reps'' advice in improvement plans.'),
  ('F272', 'USAB-ADM-DOC', 'baseball', 'usa_baseball', NULL, 4, 18, 'retrieved 2026-10-22 (26 pages)', 'development', 'days_and_months', '1-2 days/wk, 4 months to age 12; 2-5 days/wk, 4-8 months at 12-18', NULL, 'ADM: Recommended Frequency by Stage', 'rule', 'Recommended baseball load: 1-2 days a week over about 4 months for players up to 12; 2-3 days at 12-14; 3-4 at 14-16; and 4-5 at 16-18, over 4 to 8 months. Advanced-track teens may compete more, roughly half practice and half games.', 'https://api.mobilecoach.org/static/asset/pdf/131_fbf15163-2aab-422d-9205-6c36fade758d_default.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Guidance, not a rule.'),
  ('F273', 'USAB-ADM-DOC', 'baseball', 'usa_baseball', NULL, 4, 16, 'retrieved 2026-10-22 (26 pages)', 'development', 'specialization', 'none before 12; delay as late as possible', NULL, 'ADM: Stages 1-4 (Specialization)', 'rule', 'The model says no single-sport specialization before age 12, and players up to 12 should play about two other sports. At 12-14 it still encourages another sport. Any specialization at 14-16 should be delayed as long as possible and agreed by athlete, parents and coach, never required by a team.', 'https://api.mobilecoach.org/static/asset/pdf/131_fbf15163-2aab-422d-9205-6c36fade758d_default.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: Useful when parents ask about year-round travel ball.'),
  ('F274', 'USAB-ADM-DOC', 'baseball', 'usa_baseball', NULL, 4, 18, 'retrieved 2026-10-22 (26 pages)', 'safety', 'injury_prevention_basics', 'warm up and cool down; report symptoms; follow Pitch Smart', NULL, 'ADM: Injury Prevention', 'rule', 'The model calls overuse the main source of baseball injuries. Players should warm up and cool down every session, learn to tell a parent or coach about pain, and follow Pitch Smart for pitching limits and rest. Pitchers-only players should be scheduled by Pitch Smart.', 'https://api.mobilecoach.org/static/asset/pdf/131_fbf15163-2aab-422d-9205-6c36fade758d_default.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25. Earlier note: No medical advice. Point to a doctor or athletic trainer for injuries.'),
  ('F275', 'USAB-ADM-DOC', 'baseball', 'usa_baseball', 'Stage 2 (7-12)', 7, 12, 'retrieved 2026-10-22 (26 pages)', 'development', 'modified_games', 'smaller balls, shorter bases, modified formats', NULL, 'ADM: Stage 2 Discover', 'rule', 'For ages 7-12, the model recommends modified versions of baseball, such as smaller balls, shorter bases and adapted formats like Fun at Bat, so players master basic skills.', 'https://api.mobilecoach.org/static/asset/pdf/131_fbf15163-2aab-422d-9205-6c36fade758d_default.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.'),
  ('F276', 'USAB-ADM-DOC', 'baseball', 'usa_baseball', 'Stage 3 (12-14)', 12, 14, 'retrieved 2026-10-22 (26 pages)', 'development', 'growth_spurt_technique', 'revisit basic technique during growth', NULL, 'ADM: Stage 3 Progress', 'rule', 'Players aged 12-14 are often going through big growth changes. Coaches may need to revisit basic throwing and running technique to keep movement quality up and injury risk down.', 'https://api.mobilecoach.org/static/asset/pdf/131_fbf15163-2aab-422d-9205-6c36fade758d_default.pdf', TRUE, 'DIQ umpire', DATE '2026-10-22', 'Reviewed by our umpire on 2026-10-25.');
