INSERT INTO pitch_rest_rules (sanction, sport, age_min, age_max, pitches_min, pitches_max, rest_days, edition, source_url, verified, source_id) VALUES
  ('pitch_smart', 'baseball', 17, 18, 81, 105, 4, 'current page, retrieved 2026-10-22', 'https://www.mlb.com/pitch-smart/pitching-guidelines', TRUE, 'PS-GUIDE');
INSERT INTO coaching_insights (insight_code, topic, sport, age_min, age_max, audience, situation, insight, why, try_this, source_id, verified, verified_by, verify_note) VALUES
  ('C001', 'plate_coverage', 'both', 8, 14, 'all', 'Hitter strikes out on pitches away / outside', 'Many youth pitchers miss away from the batter on purpose, because they don''t want to hit anyone. Moving closer to the plate (crowding it) brings those outside pitches into reach.', 'If you stand too far off the plate, the outer edge, where most youth pitches end up, is out of your reach.', 'Before the at-bat, set your feet so the end of the bat covers the far edge of the plate. If the pitcher keeps missing away, inch closer.', 'DIQ-SME', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Team-authored guidance (Sean); confirm wording, then set verified.'),
  ('C002', 'strike_zone', 'both', 8, 14, 'all', 'Hitter takes close pitches for strikes', 'In youth games the zone is often called generously, roughly chins to shins and line to line, because pitchers are still developing control and umpires keep the game moving. Treat it as a hit zone: if it''s close, be ready to swing.', 'Waiting for a perfect pitch at this level usually means watching strike three.', 'In practice, call anything chins-to-shins a ''swing pitch'' and react to it. Note how the umpire is calling it in the first inning and adjust.', 'DIQ-SME', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Team-authored; the zone is the umpire''s judgment, so this is preparation advice, never grounds to argue. Confirm wording.'),
  ('C003', 'two_strike_approach', 'both', 9, 18, 'player', 'Two strikes in the count', 'With two strikes, protect the zone: widen what you''ll swing at, shorten the swing, choke up slightly, and try to put the ball in play or foul off tough pitches.', 'A ball in play can become a hit or an error; a called third strike can''t.', 'Two-strike rounds in batting practice: start every rep at 0-2, choke up, shorter swing, battle the outer half off a tee or soft toss.', 'DIQ-SME', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Team-authored guidance (Sean); confirm wording, then set verified.'),
  ('C004', 'umpire_communication', 'both', 8, 18, 'coach', 'Pregame, or when unsure how the zone is being called', 'Before the game, a coach can politely ask the plate umpire how they''re calling the zone (for example, how wide or how low). Players can also learn a lot by watching the first innings.', 'Knowing the zone tells hitters where to stand and what to swing at, and it builds a respectful relationship with the crew.', 'At the plate meeting, ask once, briefly and respectfully, then adjust. Never argue balls and strikes during play: they''re judgment calls and can''t be protested.', 'DIQ-SME', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Team-authored guidance (Sean); confirm wording, then set verified.'),
  ('C005', 'failure_recovery', 'both', 6, 18, 'all', 'A strikeout or mistake that ends a game', 'A strikeout, even one that ends the game, is one at-bat of information. Talk about the process (were you ready, where did you stand, did you protect with two strikes?), not the result.', 'Players who learn from a tough at-bat instead of fearing the next one get better faster and enjoy the game longer.', 'Pick one thing to work on (for example, plate coverage or the two-strike approach), practise it this week, and let the rest go.', 'DIQ-SME', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Team-authored guidance (Sean); confirm wording, then set verified.'),
  ('C006', 'parent_support', 'both', 6, 18, 'parent', 'Right after a tough game', 'On the ride home, let your child speak first. ''I love watching you play'' and praise for effort and approach help more than a breakdown of what went wrong.', 'Kids hear critique from a parent differently right after a loss; support keeps the door open for learning later.', 'Wait until they bring it up or until a calm time the next day. Leave technique to the coach unless your child asks you.', 'DIQ-SME', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Team-authored; consistent with USA Baseball''s parent guidance and Little League''s parent code. Confirm wording.'),
  ('C007', 'parent_support', 'both', 6, 18, 'parent', 'A parent wants to help with mechanics or playing time', 'Raise concerns with the coach at a time the coach sets, not right after a game, and don''t coach from the stands during play.', 'It keeps one voice coaching the player during games and keeps adult conflict away from the kids.', 'Ask the coach for a short conversation later in the week, with your player there, and come with a question rather than a complaint.', 'LL-D-parent-code-conduct', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. From Little League''s parent code and USA Baseball''s manual; check wording.'),
  ('C008', 'confidence_mindset', 'both', 8, 18, 'player', 'A player gets down on themselves', 'Focus on what you control: being ready, your approach, effort and how you respond. Hits and wins depend partly on luck; a good at-bat can still be an out.', 'Measuring yourself by things you control builds confidence that lasts through slumps.', 'After each at-bat, grade one controllable (Was I ready? Did I swing at my pitch?) instead of the result.', 'DIQ-SME', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Team-authored guidance (Sean); confirm wording, then set verified.'),
  ('C009', 'umpire_respect', 'both', 6, 18, 'all', 'Frustration with a call', 'Umpires make judgment calls, and youth umpires are often volunteers. Adjusting to the zone you''re given is a skill; arguing it never changes it.', 'Players copy how adults treat officials, and respect keeps the game running and the crew wanting to come back.', 'Model a calm reaction. If a rule (not a judgment) seems misapplied, the head coach can ask calmly at a stoppage.', 'LL-D-league-resource-guide', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Volunteer umpires per Little League''s resource guide; check wording.'),
  ('C010', 'practice_balance', 'both', 4, 18, 'coach', 'Planning a season or a week', 'Players improve with reps: up to age 12, aim for about three-quarters practice or deliberate play to one-quarter games; from 12 to 18 roughly two-thirds to one-third.', 'Games give few touches per player; practice gives many.', 'Plan more short, active practices with stations rather than adding more games.', 'USAB-ADM-DOC', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. From USA Baseball''s American Development Model; check figures.'),
  ('C011', 'multi_sport', 'both', 4, 16, 'parent', 'Questions about year-round baseball or softball', 'Playing other sports helps young players develop and stay healthy; USA Baseball recommends no single-sport specialization before age 12.', 'Different movements build athleticism and reduce overuse.', 'Keep at least one other sport in the year, and take months off from throwing.', 'USAB-ADM-DOC', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. From USA Baseball''s American Development Model; check wording.'),
  ('C012', 'bat_weight_check', 'both', 6, 18, 'all', 'Choosing a bat or wondering if it''s too heavy', 'Quick check: hold the bat by the handle with one arm straight out to the side for about 20-30 seconds. If the barrel drops or the arm shakes, the bat is probably too heavy.', 'A bat that''s too heavy slows the swing and makes it hard to adjust to pitches, which leads to late swings and pulled-off contact.', 'Try the hold test and a few dry swings; if the player drops the barrel or is late, go lighter (a bigger drop) or shorter.', 'DIQ-SME', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Common field check; Sean to confirm the exact hold time and add sizing charts.'),
  ('C013', 'equipment_bat', 'both', 4, 18, 'all', 'Choosing a bat', 'Start with what''s legal in the player''s league (for example USABat, BBCOR or USSSA marks, or the softball certification), then fit length and weight to the player. Control and bat speed matter more than size.', 'An illegal bat can be removed or penalized; an oversized bat hurts development.', 'Check the league''s bat rule, use a sizing chart for length, then do the weight check before buying.', 'DIQ-SME', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Team-authored; sizing charts to be added (bat_sizing). Confirm wording.'),
  ('C014', 'pitch_workload', 'baseball', 7, 18, 'all', 'Pitcher fatigue or a heavy week of games', 'Follow pitch counts and rest days, don''t pitch on three days in a row, avoid catching on non-pitching days, and take time off from throwing each year.', 'Overuse is the main source of youth arm injuries.', 'Track pitches every outing and plan the rotation before a tournament weekend.', 'PS-9-12', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. From Pitch Smart; check wording.'),
  ('C015', 'run_it_out', 'both', NULL, NULL, 'player', 'Batter hits a ball near the line, or isn''t sure it''s fair', 'Run hard to first on every ball you hit until you hear ''Foul!'' or ''Time!'' Fair or foul is the umpire''s call, not the batter''s.', 'A ground ball near the line can roll foul and come back fair. A batter who stops to judge it gives away an out that running would have saved.', 'In practice, roll balls down the lines that go foul and come back fair. The batter runs every one; the fielder makes the play; a coach plays umpire and signals fair or calls foul.', 'DIQ-SME', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Drafted by Claude from Sean''s fair/foul scenario (2026-10-23); confirm, then set verified.'),
  ('C016', 'drop_weight', 'both', 4, 18, 'all', 'Reading a bat''s size or comparing bats', 'A bat''s drop is its length minus its weight in ounces: a 30-inch bat at -10 weighs 20 ounces. The bigger the drop number, the lighter the bat. Typical ranges: tee ball about -10.5 to -14, coach pitch -9 to -12, fastpitch -8 to -13; high school and college baseball use -3 BBCOR bats.', 'Matching the drop to the player''s age and strength keeps the bat light enough to swing with control, and some leagues limit the drop.', 'Read the length and drop printed on the bat (for example 29-inch, -10), work out the weight, then check that the league''s bat rule allows it before buying.', 'JB-GUIDE', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Facts from a retailer guide, in our own words; confirm, then set verified.'),
  ('C017', 'bat_fit_now', 'both', 5, 14, 'parent', 'Buying a bigger bat to grow into', 'Don''t buy a bat to grow into. A bat that''s too long or too heavy hurts swing mechanics now, and those habits stick. Fit the bat to the player today: height and weight give a starting length, then watch how it swings.', 'Bat speed and control drive good contact; an oversized bat costs both.', 'Use the maker''s size chart for a starting length, then have the player try a teammate''s bat one size up and one size down and compare the swings.', 'JB-YOUTH-SELECT', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Facts from a retailer guide, in our own words; confirm, then set verified.'),
  ('C018', 'bat_care', 'both', 6, 18, 'all', 'Taking care of a bat', 'Don''t roll or shave a bat: it can void the warranty and make the bat illegal. Composite bats need a short break-in at partial power (follow the maker''s instructions), and shouldn''t be used in cold weather (below about 60 degrees F) or with heavy yellow cage balls. Turn the bat a quarter turn after each swing so wear spreads around the barrel.', 'An altered or damaged bat can be removed from play, and replacing one is expensive.', 'Mark the label side and rotate a quarter turn each swing in batting practice; keep composite bats out of cold-weather games and cage machines.', 'JB-GUIDE', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Facts from a retailer guide, in our own words; confirm, then set verified.'),
  ('C019', 'softball_bat_certification', 'softball', 6, 18, 'all', 'Choosing a softball bat for a league or tournament', 'Softball has several governing bodies (for example USA Softball, USSSA, NSA, ISA and WBSC), and each certifies bats separately. A bat that''s legal in one league may not be legal in another.', 'An uncertified bat can be removed from the game or penalized.', 'Before buying or before a tournament, find out which body governs it and look the bat up on that body''s certified list.', 'JB-SB-GOV', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Facts from a retailer guide, in our own words; confirm, then set verified.'),
  ('C020', 'pre_pitch_check', 'both', 7, 18, 'coach', 'Runners forget the outs or what to do on a ground ball or a fly ball', 'Between pitches, have the base coach ask each runner the outs and their plan, and get an answer back: ''Two outs, run on anything'' or ''One out: ground ball I go, fly ball halfway.''', 'A decision made before the pitch becomes a reaction during it. Most youth base-running mistakes come from deciding after the ball is hit.', 'Hold up fingers for the outs every pitch and have runners answer. At practice, call a situation (runner on first, one out) before every rep.', 'BR-SIT-PRACTICE', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Drafted by Claude on 2026-10-25 from Sean''s list of common base-running mistakes. Tip in our own words from the cited source.'),
  ('C021', 'fly_ball_halfway', 'both', 8, 18, 'all', 'A runner on first or second sprints on a fly ball with fewer than two outs and gets doubled off', 'With fewer than two outs, take a few steps off and read the ball. Go far enough to advance if it drops, but stay close enough to get back if it''s caught. Tag up only when the catch is deep enough to advance after it.', 'After a catch with fewer than two outs, every runner has to get back to their base. If the throw beats them, they''re out.', 'Hit or toss fly balls to outfielders with runners on first. Runners call ''halfway'', ''tag'' or ''go'' before they move.', 'BR-SIT-PRACTICE', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Drafted by Claude on 2026-10-25 from Sean''s list of common base-running mistakes. Tip in our own words from the cited source.'),
  ('C022', 'tag_up_third', 'both', 8, 18, 'player', 'Runner on third, fly ball, fewer than two outs', 'Get back to third and tag. Leave the moment the fielder first touches the ball, not when the catch is finished, and run hard home. Leaving early lets the defense appeal for an out.', 'The tag-up is the runner''s best chance to score without a hit.', 'Practice with the coach saying ''Go!'' at the touch, then without the coach while the runner watches the ball into the glove.', 'BR-SIT-PRACTICE', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Drafted by Claude on 2026-10-25 from Sean''s list of common base-running mistakes. Tip in our own words from the cited source.'),
  ('C023', 'two_outs_run', 'both', 7, 18, 'player', 'Two outs and the ball is hit', 'With two outs, run on contact on everything: grounders, line drives and fly balls. A catch ends the inning anyway, so there''s nothing to tag up for.', 'Every step counts if the ball drops or a fielder misplays it.', 'Before each pitch with two outs, runners tell the base coach: ''Two outs, I''m running.''', 'BR-SIT-PRACTICE', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Drafted by Claude on 2026-10-25 from Sean''s list of common base-running mistakes. Tip in our own words from the cited source.'),
  ('C024', 'ground_ball_force', 'both', 7, 14, 'player', 'Runner on first, or the bases loaded, and the batter hits a ground ball', 'On a fair ground ball, a runner on first has to run, and so does every runner with all the bases filled behind them. Sprint to the next base; there''s no going back.', 'The batter needs first base, so the runner there is forced off it. Standing still gives the defense an easy force or double play, or leaves two runners on one base.', 'Ground-ball station: a runner on first, the coach rolls grounders to the infield, and the runner sprints on contact. Then add a runner on second and ask ''force or no force?'' before each rep.', 'BR-SIT-PRACTICE', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Drafted by Claude on 2026-10-25 from Sean''s list of common base-running mistakes. Tip in our own words from the cited source.'),
  ('C025', 'run_through_first', 'both', 7, 18, 'player', 'The batter slows down or stops on first base', 'Run through first at full speed. Touch the front of the bag, keep sprinting a few steps, then slow down and look right, toward foul ground, for the ball.', 'Slowing down to stop on the bag costs time at the exact moment the play is closest. You''re allowed to run past first and come back if you return right away.', 'Put a cone 3 to 4 steps past first base. Runners must reach the cone at full speed.', 'DIQ-SME', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Drafted by Claude on 2026-10-25 from Sean''s list of common base-running mistakes. Tip in our own words from the cited source.'),
  ('C026', 'round_bases', 'both', 8, 18, 'player', 'Rounding a base on a hit to the outfield', 'Swing out a little before the base, touch the inside corner, and keep your speed through the turn.', 'Good angles save steps and keep your momentum.', 'Base-rounding drill: runners take turns rounding first on a pretend single while the coach watches the angle and the foot on the inside corner.', 'AU-BR-DRILLS', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Drafted by Claude on 2026-10-25 from Sean''s list of common base-running mistakes. Tip in our own words from the cited source.'),
  ('C027', 'read_defenders', 'both', 9, 18, 'all', 'The runner stares at the ball and misses what the fielders are doing', 'Read the fielders, not only the ball: where they''re playing, whether they can get to it, and where they''re throwing.', 'Where the ball goes and where the fielders are decide whether you can take the base. Watching only the ball is a common mistake.', 'Read-and-react reps: the coach puts balls in play, runners decide to go or hold, and then they say what they saw.', 'AU-BR-DRILLS', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Drafted by Claude on 2026-10-25 from Sean''s list of common base-running mistakes. Tip in our own words from the cited source.'),
  ('C028', 'baserunning_every_practice', 'both', 7, 18, 'coach', 'Base running gets skipped at practice', 'Do some base running every practice, right after warm-ups, with drills that look like game situations.', 'Good base-running teams don''t need complicated drills. They need a clear philosophy and regular reps.', 'Ten minutes after warm-ups, rotating: leads and first steps one day, fly-ball reads the next, ground-ball forces the next.', 'ABCA-BR', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Drafted by Claude on 2026-10-25 from Sean''s list of common base-running mistakes. Tip in our own words from the cited source.'),
  ('C029', 'always_advance', 'baseball', 11, 18, 'player', 'A runner on base has no plan to move up', 'Your job on base is to get to the next base. Take the same lead every time, set in an athletic stance facing the field, and break when the pitcher commits to home, not when the catcher catches it. Check your league''s rules first: some youth leagues don''t allow leaving before the pitch reaches the batter.', 'A good lead shortens the distance to the next base and makes the defense deal with you.', 'Practice leads and first-step sprints while a pitcher goes through the motion.', 'ABCA-BR', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Drafted by Claude on 2026-10-25 from Sean''s list of common base-running mistakes. Tip in our own words from the cited source.'),
  ('C030', 'simple_signs', 'both', 7, 14, 'coach', 'Too many signs confuse young runners', 'Start with a simple red light/green light from the base coach. Add more signs only after the basics are solid.', 'Young runners can''t execute a sign they''re still decoding.', 'Use one sign per game situation until the whole team gets it right in practice.', 'ABCA-BR', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Drafted by Claude on 2026-10-25 from Sean''s list of common base-running mistakes. Tip in our own words from the cited source.'),
  ('C031', 'fly_ball_drop', 'both', 8, 18, 'player', 'A fly ball is clearly going to drop (over a fielder''s head or into a gap)', 'If the ball is plainly going to drop, run. A runner on first is forced the moment it lands, so waiting at the base can mean being thrown out at second on a hit.', 'When a fair fly ball isn''t caught, the batter becomes a runner and the force is on.', 'Hit or throw balls into gaps and over heads with runners on first. Runners call ''Down!'' and go.', 'BR-SIT-PRACTICE', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Drafted by Claude on 2026-10-25 from Sean''s list of common base-running mistakes. Tip in our own words from the cited source.');
INSERT INTO coaching_lessons (lesson_code, title, principle, life_lesson, for_player, for_coach, for_parent, for_umpire, tags, source_id, verified, verified_by, verify_note) VALUES
  ('L001', 'Win as a team, lose as a team', 'No one wins or loses a game alone. Every player, the coaches and the people in the stands are part of the result.', 'Families, classrooms and workplaces work the same way: you share the credit and you share the load.', 'One at-bat or one error never decides a game by itself. Pick up your teammates the way you want them to pick you up.', 'Talk about results as ''we''. Never single out the player who made the last out or the last error.', 'Celebrate the team first. After a loss, don''t let your child carry it alone or put it on a teammate.', 'The crew works as a team too, and their calls are part of the game, never the reason a team lost.', 'team;loss;win;blame;last_out;error', 'DIQ-SME', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Sean''s words (2026-10-23 conversation), lightly edited; confirm wording, then set verified.'),
  ('L002', 'Everyone makes mistakes: forgive others, own yours', 'Players, coaches, parents and umpires are all human, and we all make mistakes. Forgive the mistakes of others, and take responsibility for your own so you can learn from them and grow. We strive to be perfect, but nobody is.', 'Owning a mistake and learning from it is a habit that lasts far beyond the diamond.', 'Say ''that''s on me'', then ask what you''d do differently next time. When a teammate makes a mistake, let it go and pick them up.', 'Model it: own your own coaching mistakes out loud, and treat a player''s error as a teaching moment, not a punishment.', 'Show your child how to own a mistake without beating themselves up, and never blame the umpire, the coach or a teammate in front of them.', 'Umpires miss calls too. Owning that calmly earns respect; everyone else should give the same grace.', 'mistake;error;blame;umpire;responsibility;failure;forgiveness', 'DIQ-SME', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Sean''s words (2026-10-23 conversation), lightly edited; confirm wording, then set verified.'),
  ('L003', 'Believe in your players before they believe in themselves', 'Have confidence in your players even when they don''t show it, even when their track record says failure. Don''t lose that confidence. Feed it to them and they will succeed.', 'People rise to the belief others show in them, at school, at work and at home.', 'Your coach picked you for this moment because they believe you can do it. Trust your preparation.', 'Give players the chance to step up, including the ones without a great record yet, and tell them you believe in them before the result.', 'Your belief matters most when your child is struggling. Tell them you love watching them play, hit or no hit.', NULL, 'confidence;underdog;scared_hitter;slump;opportunity;pitching_depth', 'DIQ-SME', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Sean''s words (2026-10-23 conversation), lightly edited; confirm wording, then set verified.'),
  ('L004', 'Winning comes from a winning formula', 'Winning is fun and feels great, but it doesn''t happen without a winning formula: healthy arms, many players who can contribute, and everyone playing their part. Don''t put the scoreboard above developing players.', 'Long-term success comes from building people and habits, not from chasing one result at any cost.', 'Do your job, whatever your role is that day. A team of players doing their part beats one star.', 'Protect arms and build depth: give more pitchers reps in lower-pressure innings so they''re ready when you need them. Rest your best arm when the rules or their body say so.', 'Measure the season by how your child grows and how the team plays together, not only by wins.', NULL, 'winning;pitching_depth;arm_care;pitch_count;development;playoffs', 'DIQ-SME', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Sean''s words (2026-10-23 conversation), lightly edited; confirm wording, then set verified.'),
  ('L005', 'Big moments aren''t scripted', 'The moments that matter most aren''t planned. They happen because kids are put in situations where they can fail or succeed, and sometimes they succeed through what could have been failure.', 'You can''t plan for every opportunity, but you can be ready for it and willing to take it.', 'Play every pitch to the end and be ready: your moment can come when you least expect it.', 'Put kids in situations where they can fail or succeed. That''s where growth and team belief come from.', 'Let your child take on hard moments. The chance to fail is also the chance to shine.', NULL, 'opportunity;underdog;dropped_third_strike;new_rule;playoffs;first_year', 'DIQ-SME', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Sean''s words (2026-10-23 conversation), lightly edited; confirm wording, then set verified.'),
  ('L006', 'Believe in your teammates, especially when they fail', 'Believe in your teammates, especially when they fail. The moment after a mistake is when a teammate needs your belief most.', 'Standing by people when they stumble is what makes a team, a family or a group of friends strong.', 'After a teammate''s error or strikeout, be the first to say ''next one''s yours''. Never roll your eyes or turn away.', 'Teach players how to pick each other up, and praise it when you see it, as much as you praise a hit.', 'Cheer for every player on the team, especially the one who''s struggling, and teach your child to do the same.', NULL, 'team;error;strikeout;failure;teammates;encouragement', 'DIQ-SME', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Sean''s words (2026-10-23 conversation), lightly edited; confirm wording, then set verified.'),
  ('L007', 'Your value isn''t your stat line', 'Your value is not determined by your failures or your successes.', 'Who you are matters more than any result: a grade, a game or a job outcome doesn''t define your worth.', 'A strikeout or a home run doesn''t change who you are. Show up, compete and be a good teammate.', 'Make sure every player knows their place on the team doesn''t depend on today''s box score.', 'Love your child the same after an 0-for-4 as after a 3-for-4, and let them see it.', 'One missed call doesn''t define an umpire either.', 'failure;success;confidence;slump;identity;self_worth', 'DIQ-SME', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Sean''s words (2026-10-23 conversation), lightly edited; confirm wording, then set verified.'),
  ('L008', 'A game built on failure', 'In baseball, succeeding about 30% of the time at the plate can make a Hall of Fame career at the professional level. That''s a 70% failure rate. You will not win every competition, and you will not lose every competition, but you will learn and grow through every competition.', 'Failing often on the way to success is normal in anything worth doing; what matters is learning from each try.', 'Expect to fail more than you succeed at the plate, even when you''re good. Judge yourself by your approach and effort, then go again.', 'Help players keep failure in perspective: celebrate good at-bats and hard effort, not just hits.', 'Remind your child that even the best hitters fail most of the time. A tough day is part of the game, not a sign they don''t belong.', NULL, 'failure;strikeout;slump;perspective;hitting;loss', 'DIQ-SME', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Sean''s words (2026-10-23 conversation), lightly edited; confirm wording, then set verified.'),
  ('L009', 'Today''s opponents, tomorrow''s teammates', 'Your opponents today may be your teammates in the future. Treat them that way, especially after a game. As competitive athletes in the same sport, you are all brothers and sisters.', 'Respect for competitors builds the relationships and reputation you carry for the rest of your life.', 'Compete hard, then shake hands like you mean it. Congratulate a good play by the other team.', 'Model respect for the other team and its coaches, and expect it of your players in the handshake line.', 'Cheer for good plays by both teams and speak well of opponents in front of your child. The other team''s kids are someone''s children too.', 'Treat both teams the same; respect for everyone on the field starts with the crew.', 'sportsmanship;opponents;respect;handshake;loss;win', 'DIQ-SME', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Sean''s words (2026-10-23 conversation), lightly edited; confirm wording, then set verified.'),
  ('L010', 'Control the moment', 'When a play gets loud and confusing, the adults set the temperature. Umpires stop the play, get together and explain calmly; coaches lower their voices and wait for the explanation.', 'In any heated moment, slowing down and getting the facts straight before reacting keeps a mistake from turning into a fight.', 'When the umpire calls time, stop and listen. Don''t keep running or tagging because someone is yelling.', 'Yelling directions during a confusing play makes it harder for everyone, including your players. Wait for the umpires, then ask calmly what rule applies.', 'Stay in the stands and stay calm. The players take their cue from the adults.', 'Kill it loudly: ''Time! Dead ball!'' with both arms up. Get your partner, agree on what happened and where everyone goes, then explain once to each coach. Don''t let the volume change the call: a misapplied rule can be corrected, and a judgment call stands.', 'umpire;conflict;de_escalation;dead_ball;interference;coaches;yelling;crew', 'DIQ-SME', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Drafted by Claude from Sean''s umpire scenario (2026-10-23); confirm wording, then set verified.'),
  ('L011', 'Play until you hear ''foul''', 'Every batted ball is live until the umpire says otherwise. Players don''t decide fair or foul; the umpire does. So run hard and play the ball until you hear ''Foul!'' or ''Time!''', 'Don''t quit on something because you''ve already decided how it will turn out. Finish the job, and leave the call to the person whose call it is.', 'Hit it, drop the bat and run, every time, until you hear ''Foul!''. Fielders: if the ball is in play, make the play.', 'Teach ''run until you hear foul'' at practice with rollers that go foul and come back fair. During a play, one short word (''Run!'') helps more than a dozen shouted directions.', 'If your player stood and watched, make it a learning moment on the ride home, not a criticism. ''Run until you hear foul'' is a rule many players learn the hard way.', 'Make the fair signal big and immediate: point toward fair territory as soon as the ball is touched or stops in fair territory. Call ''Foul!'' loudly with both arms up. Clear signals stop the guessing and the yelling.', 'fair_foul;hustle;run;umpire_signal;ground_ball;batter;learning', 'DIQ-SME', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Drafted by Claude from Sean''s fair/foul scenario (2026-10-23); confirm wording, then set verified.'),
  ('L012', 'Know the play before the pitch', 'Before every pitch, a good runner knows how many outs there are, whether they''re forced, and what they''ll do on a ground ball, a fly ball and a line drive. Decide before the ball is hit, so you react instead of think.', 'Preparation turns pressure into routine. People who think ahead stay calm when things get busy.', 'Every pitch, ask yourself three things: How many outs? Am I forced? What do I do on a ground ball or a fly ball? Then look at your base coach.', 'Between pitches, ask runners out loud: ''How many outs? What do you do on a ground ball?'' Make it a habit, not a quiz. At practice, call out a situation before every rep.', 'On the ride home, ask about one decision on the bases (''What did you do with a runner on first and one out?''). Praise the good decision, even if the runner was out.', 'Know the outs and the force situations before every pitch too, and signal the outs between batters so players and coaches stay with you.', 'base_running;outs;force;tag_up;fly_ball;ground_ball;preparation;situation', 'DIQ-SME', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Drafted by Claude on 2026-10-25 from Sean''s list of common base-running mistakes. Lesson in our own words, built on the base-running practice sheet (BR-SIT-PRACTICE).'),
  ('L013', 'Run hard through the finish', 'Run every ball out at full speed, through first base and until the play is over. Slowing down at the end costs more outs than speed ever gains.', 'Finish the job. Easing up at the end can undo all the good work that came before it.', 'Run through first base, not to it: hit the front of the bag, keep sprinting a few steps past, then look right to find the ball. On a dropped third strike, run without waiting to be told.', 'Put a finish line a few steps past first base at practice. Praise full-speed effort on routine outs as much as on hits.', 'Cheer hustle on an out the same as a hit. A full-speed run is something your player controls every time.', 'Close plays at first happen because runners hustle. Get a good angle, be set before the ball arrives, and sell the call.', 'base_running;hustle;run_through;first_base;overrun;effort;dropped_third_strike', 'DIQ-SME', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Drafted by Claude on 2026-10-25 from Sean''s list of common base-running mistakes. Lesson in our own words.'),
  ('L014', 'Read the ball, then go', 'Good base running is a series of decisions. Watch where the ball goes and what the fielders do, then choose: go, go halfway, or get back. Don''t guess, and don''t freeze.', 'Take in what you can see, decide, and commit. Waiting for perfect certainty can cost as much as rushing.', 'On a fly ball with fewer than two outs, go as far as you can while still being able to get back if it''s caught. On a ball that''s clearly going to drop, run. Watch the fielders, not only the ball.', 'Run read-and-react reps: you throw or hit a ball, runners decide, and you talk about the decision after each rep, not just the result.', 'Mistakes on the bases are how players learn to read the game. Ask what they saw, not why they did it.', 'On fly balls with runners on, watch the catch and the runners'' tags. In many codes a runner who leaves early is out only if the defense appeals, so know your league''s appeal rules.', 'base_running;read;fly_ball;tag_up;halfway;line_drive;decision;defenders', 'DIQ-SME', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Drafted by Claude on 2026-10-25 from Sean''s list of common base-running mistakes. Lesson in our own words, drawing on the practice sheet and the read-and-react drill idea (AU-BR-DRILLS).');
INSERT INTO coaching_situations (situation_code, name, topic, bases, outs, pitch_count_state, rule_fact_codes, offense, defense, common_mistakes, lesson_codes, source_id, verified, verified_by, verify_note) VALUES
  ('SIT001', 'Dropped third strike, bases loaded, 2 outs', 'dropped_third_strike', 'loaded', '2', 'two strikes', 'F034;F054;F148;F217;F021', 'The batter can run because there are two outs, even though first base is occupied. Everyone runs: every runner is forced to move up. Batter: drop the bat and sprint to first right away.', 'Every base is a force. The simplest out is often for the catcher to pick up the ball and step on home plate, or throw to first. Don''t rush into a wild throw: one clean force ends the inning.', 'Batter walks back to the dugout thinking it''s over; runners stop; catcher tags the batter late or throws wildly instead of taking the sure force at home.', 'L005;L002', 'DIQ-SME', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Strategy in our words; general baseball/softball rule logic. Applies only where the uncaught-third-strike rule is in effect. Coach/umpire to confirm.'),
  ('SIT002', 'Dropped third strike, runner on first, 1 out', 'dropped_third_strike', 'first', '1', 'two strikes', 'F034;F054;F148;F217;F021', 'With first base occupied and fewer than two outs, the batter is out and can''t run, whether or not the catcher holds the pitch. The runner on first is NOT forced; he may try to advance at his own risk.', 'The batter is already out. Don''t throw to first; watch the runner. Keep the ball in front, call ''batter''s out'' loudly so the infield knows, and only throw if the runner is trying to advance.', 'Defense throws to first for a batter who is already out and lets the runner take extra bases; batter runs when he can''t and draws a throw that helps no one.', 'L002', 'DIQ-SME', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Strategy in our words; general baseball/softball rule logic. Applies only where the uncaught-third-strike rule is in effect. Coach/umpire to confirm.'),
  ('SIT003', 'Dropped third strike, runner on third, 1 out', 'dropped_third_strike', 'third', '1', 'two strikes', 'F034;F054;F148;F217;F021', 'First base is open, so the batter can run: sprint to first the moment the ball gets away. The runner on third watches the catcher: if the catcher throws to first, that''s often the chance to break for home.', 'Tag the batter if he''s close, or throw to first. Before throwing, check the runner on third; the corner infielders should call it out. A rushed throw can give away the winning run.', 'Batter doesn''t run because he thinks strike three ends it; runner on third doesn''t read the throw; catcher throws to first without looking the runner back.', 'L005;L003', 'DIQ-SME', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Strategy in our words; general baseball/softball rule logic. Applies only where the uncaught-third-strike rule is in effect. Coach/umpire to confirm.'),
  ('SIT004', 'Runner hit by a fair batted ball, bases loaded, no outs', 'runner_hit_by_batted_ball', 'loaded', '0', NULL, 'F095;F206', 'One out, and the inning isn''t over. A runner hit by a fair batted ball that no fielder has touched is out, and the ball is dead at that moment, even if it later rolls foul. Nothing after the dead ball counts. The batter is awarded first base and only forced runners move up one base, so with the bases loaded: the batter goes to first, the runner from first to second, the runner from second to third, and no run scores. Coaches: when you hear ''dead ball'', stop calling for runners to go and let the umpires place them.', 'Once the umpire calls dead ball, tags and throws don''t count, however good they were: hold the ball and let the umpires place the runners. The key judgment is whether a fielder touched the ball before it hit the runner. If she did, the ball stays live and the runner isn''t out unless she interfered on purpose, so the tags that followed would count.', 'The umpire calls the runner out but doesn''t kill the play loudly, so everyone keeps playing; a second umpire calls more outs on a ball that was already dead; coaches yell players into extra running and tagging; the crew changes a call because of the noise instead of getting together. Fix: ''Time! Dead ball!'' with both arms up, a quick crew conference, then one calm explanation to each coach.', 'L010;L002', 'DIQ-SME', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Our wording of general softball rule logic: an untouched fair batted ball hitting a runner before it passes an infielder makes the runner out and the ball dead; the batter gets first and only forced runners advance. No rulebook text for this is loaded yet (see gaps.csv); confirm against your sanction''s rulebook. Scenario from Sean (2026-10-23).'),
  ('SIT005', 'Slow roller rolls foul, then back fair before first base', 'fair_foul_ground_ball', 'none', NULL, NULL, 'F015;F087;F199;F032', 'It''s a fair ball, so the batter is a runner and the out at first stands. A ground ball that hasn''t reached first or third base isn''t foul just because it crossed the line: it''s judged where it stops or where a fielder first touches it. This one rolled foul, came back, and was picked up in fair territory, so it was fair and in play. Umpires usually signal a fair ball by pointing toward fair territory without saying anything; only foul is called out loud. Batter: run on every ball you hit until you hear ''Foul!'' or ''Time!''', 'Pick the ball up and make the play: step on first or throw there. A slow roller near the line that''s still rolling can be left alone; if it stops or you touch it in foul territory before it reaches the base, it''s foul. Fielders, like batters, play until the umpire stops it.', 'The batter stands at the plate because the ball crossed the line once; the fielder picks it up and freezes; the umpire''s fair signal is late or small, so nobody sees it; coaches on both sides shout directions and the players try to learn the rule in the middle of the play. Fix: the plate umpire points fair clearly the moment the ball is touched in fair territory, and coaches teach ''run until you hear foul'' at practice, not during the play.', 'L011;L002', 'DIQ-SME', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Our wording of the general fair/foul rule for a ground ball before first or third base (baseball and softball). No rulebook definition text is loaded yet (see gaps.csv). Fair or foul is the umpire''s judgment and can''t be protested (F015, F087, F199, F032). Scenario from Sean (2026-10-23).'),
  ('SIT006', 'Fly ball with a runner on first, fewer than 2 outs', 'fly_ball_read', 'first', '0 or 1', NULL, 'F250', 'Take a few steps off the base and read the ball. With fewer than two outs, if it''s caught you must get back and touch first before you can go anywhere, and the defense can throw behind you for a double play. If it drops, run hard: you''re forced to second the moment it lands. On a very deep fly, you can tag up and try for second after the catch, but only if the throw can''t beat you.', 'Catch it, then look at the runner. If they''re off the base, throw behind them to first for the double play. If they tagged and broke for second, hit the cutoff.', 'The runner sprints on contact and gets doubled off; the runner stays glued to first on a ball that drops and is forced out at second; the runner forgets to go back and touch first before trying to advance.', 'L014;L012', 'BR-SIT-PRACTICE', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Drafted by Claude on 2026-10-25 from Sean''s list of common base-running mistakes. Strategy from the practice sheet; tag-up rule in our own words. No rulebook text for retouching after a catch is loaded yet (see gaps.csv).'),
  ('SIT007', 'Fly ball with a runner on third, fewer than 2 outs', 'tag_up', 'third', '0 or 1', NULL, 'F250;F155', 'Go back to third and tag up. Leave as soon as the fielder first touches the ball and sprint home. On a short fly or an infield pop-up, stay on the base unless your coach sends you. If you leave before the fielder touches the ball, the defense can appeal and you''re out.', 'Catch it and throw home through the cutoff. If the runner left early, tag third base or the runner and appeal to the umpire. Some leagues allow only live-ball appeals, so make the appeal before the next pitch.', 'The runner goes halfway from third on a deep fly and can''t score after the catch; the runner leaves before the catch; the runner jogs home and is thrown out.', 'L014;L012', 'BR-SIT-PRACTICE', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Drafted by Claude on 2026-10-25 from Sean''s list of common base-running mistakes. Strategy from the practice sheet; tag-up and appeal in our own words. F155 covers live-ball appeals in Little League softball only. See gaps.csv for tag-up rule text.'),
  ('SIT008', 'Ground ball with a runner on first', 'ground_ball_force', 'first', '0 or 1', NULL, 'F250', 'Run hard to second on contact. When the batter hits a fair ground ball, the batter needs first base, so you''re forced to leave it. There''s no waiting to see if it gets through, and there''s no going back.', 'Take the sure out. Older teams turn two, second base then first. Younger teams get the force at second or the out at first. Once the batter is out at first, the runner isn''t forced any more, so a tag is needed to get them.', 'The runner waits to see if the ball gets through and is forced out easily; the runner goes back to first and ends up on the same base as the batter; the runner stops halfway thinking the ball was caught.', 'L012;L013', 'BR-SIT-PRACTICE', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Drafted by Claude on 2026-10-25 from Sean''s list of common base-running mistakes. Strategy from the practice sheet; force rule in our own words. No rulebook text for force plays is loaded yet (see gaps.csv).'),
  ('SIT009', 'Ground ball with the bases loaded, fewer than 2 outs', 'ground_ball_force', 'loaded', '0 or 1', NULL, 'F250', 'Everyone runs. With the bases full, every runner is forced as soon as the batter hits a fair ground ball. Runner on third: sprint home, wherever the ball is hit. Nobody stops to look and nobody goes back.', 'The force is on at every base, so step on the base instead of chasing a tag. The easiest out is often at home or at first. Older teams can turn home to first.', 'The runner on third holds because the ball was hit to the left side; runners stop and watch; the catcher tries to tag the runner instead of stepping on home plate.', 'L012;L013', 'BR-SIT-PRACTICE', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Drafted by Claude on 2026-10-25 from Sean''s list of common base-running mistakes. Strategy from the practice sheet; force rule in our own words (see gaps.csv).'),
  ('SIT010', 'Ground ball with a runner on second, first base open', 'ground_ball_read', 'second', '0 or 1', NULL, 'F250', 'You''re not forced, so read where the ball goes. If it''s hit in front of you (to the shortstop or third baseman), stay unless it gets through. If it''s hit behind you (to the right side), run hard to third. With two outs, run on contact.', 'Look the runner back to second before throwing to first. If the runner breaks on a ball to the left side, throw to third for the tag.', 'The runner runs into a tag on a ball hit right to the shortstop; the runner holds on a ball to the right side and gives up an easy base.', 'L014;L012', 'BR-SIT-PRACTICE', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Drafted by Claude on 2026-10-25 from Sean''s list of common base-running mistakes. Strategy from the practice sheet, in our own words.'),
  ('SIT011', 'Two outs, ball in play with runners on', 'two_outs_run', 'any', '2', NULL, 'F250', 'Run on contact, on everything: ground balls, line drives and fly balls. A catch ends the inning anyway, so there''s nothing to tag up for. A runner on second should run hard and expect to score on a hit.', 'Get the easiest out: a force at the nearest base or the out at first.', 'Runners go halfway or tag up out of habit; runners stop to watch a fly ball; nobody reminds the runners that there are two outs.', 'L012;L013', 'BR-SIT-PRACTICE', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Drafted by Claude on 2026-10-25 from Sean''s list of common base-running mistakes. Strategy from the practice sheet, in our own words.'),
  ('SIT012', 'Two runners end up on the same base', 'two_runners_same_base', 'any', NULL, NULL, NULL, 'Stay on the base and look at your coach; don''t walk off. The base belongs to the runner who was there first, unless that runner was forced to leave it, in which case it belongs to the runner behind. The runner who doesn''t own the base can be tagged out even while standing on it. If you''re the lead runner and the base behind you is open, your coach may send you back there.', 'Tag both runners, then let the umpire rule. Only the runner who isn''t entitled to the base is out.', 'Both runners step off thinking one is already out, and both are tagged; the fielder tags only one runner; coaches argue instead of asking the umpire which runner owns the base.', 'L012;L002', 'DIQ-SME', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Drafted by Claude on 2026-10-25 from Sean''s list of common base-running mistakes. General rule logic in our own words. No rulebook text for two runners on one base is loaded yet (see gaps.csv).'),
  ('SIT013', 'Batter runs through first base', 'run_through_first', 'none', NULL, NULL, 'F250', 'Run through first base at full speed. Touch the front edge of the bag, keep running a few steps past it, then slow down and look to your right, toward foul territory, to find the ball. Come back to first right away. You''re allowed to run past first and come back without being tagged out, as long as you don''t try to go to second.', 'Stretch toward the throw with your foot on the base, then get out of the runner''s path after the catch.', 'The runner slows down to stop on the bag and is out by a step; the runner dives or slides into first, which is slower; the runner jogs on a routine ground ball and can''t take advantage of a wild throw.', 'L013', 'DIQ-SME', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Drafted by Claude on 2026-10-25 from Sean''s list of common base-running mistakes. General rule logic in our own words; F250 lists running through first as a skill for ages 7-9. No rulebook text for overrunning first is loaded yet (see gaps.csv).'),
  ('SIT014', 'Batter overruns first and turns toward second (umpire''s judgment)', 'overrun_first_attempt', 'none', NULL, NULL, 'F015;F032', 'After you run through first, come straight back and don''t make any move toward second unless you''re really going. If the umpire judges that you tried to go to second, you lose the protection for overrunning the base and can be tagged out before you get back. Which way you turn doesn''t decide it by itself: the umpire judges whether you made an attempt to advance.', 'If the runner makes a move toward second, tag them, then let the umpire make the call.', 'The runner drifts toward second while looking for the ball and is tagged; fans and coaches shout that the runner turned the wrong way, as if the direction alone decides it; players and coaches argue the call. Whether the runner tried to advance is the umpire''s judgment, so the call stands.', 'L013;L002;L010', 'DIQ-SME', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Drafted by Claude on 2026-10-25 from Sean''s list of common base-running mistakes. Judgment call. General rule logic in our own words; F015 and F032 cover judgment calls not being protestable in Little League and USSSA fastpitch. See gaps.csv.'),
  ('SIT015', 'Fly ball that clearly won''t be caught, runner on first', 'fly_ball_drop', 'first', 'any', NULL, 'F250', 'If the ball is clearly going to drop (over the outfielder''s head, into a gap, or far from every fielder), run right away. The moment it lands you''re forced to second, so freezing at first can get you thrown out at second on a hit. Watch the fielder: one running hard with their back to the infield probably won''t catch it.', 'Field it and throw to the lead base. An outfielder can get a force out at second if the runner waited at first.', 'The runner waits at first on a ball over everyone''s head and is forced out at second; the runner goes back to first while the batter also arrives, so two runners share one base; the runner goes halfway on a ball nobody could catch and only gets one base.', 'L014;L013', 'BR-SIT-PRACTICE', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Drafted by Claude on 2026-10-25 from Sean''s list of common base-running mistakes. Strategy from the practice sheet''s deep-fly reads; force rule in our own words (see gaps.csv).'),
  ('SIT016', 'Dropped third strike, first base open', 'dropped_third_strike', 'none', 'any', 'two strikes', 'F034;F054;F148;F217;F021', 'Run! When the catcher doesn''t catch strike three cleanly and first base is open, or there are two outs, the batter can run to first. Drop the bat and sprint until you''re tagged, thrown out or called out. Don''t wait for someone to tell you. This applies only where your league uses the uncaught-third-strike rule; many younger divisions don''t.', 'Catcher: pick the ball up and tag the batter or throw to first right away. First baseman: get to the base and give a target.', 'The batter walks back toward the dugout; the batter waits for a coach to yell; the catcher rolls the ball back to the mound while the batter can still run.', 'L005;L013', 'DIQ-SME', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Drafted by Claude on 2026-10-25 from Sean''s list of common base-running mistakes. Our own wording; follows SIT001-SIT003, which use the same facts on where the rule applies.');
INSERT INTO coaching_stories (story_code, title, story, lesson_codes, situation_codes, source_id, verified, verified_by, verify_note) VALUES
  ('ST001', 'The playoff game nobody scripted', 'In a do-or-die playoff game, our best pitchers weren''t available, so I started a kid who hadn''t had many pitching reps for us. It was a risk. He went out, threw strikes, and his pitches weren''t fast and he didn''t strike many kids out, but the slower speed meant fewer hard-hit balls, and the defense stepped up. That success started to feed the whole team: they hit well, ran the bases well and played an outstanding team game, because they had to. Everyone had to step up and play their part. That year they won the championship. The championship game ended on a dropped third strike with a runner on third and one out. The batter hadn''t had a hit all year, not one. He''d been hit by pitches several times and was really scared at the plate. He ran, and the runner who scored from third was playing baseball for the first time. Those moments aren''t scripted. They happen because kids are put in situations where they can fail or succeed.', 'L003;L004;L005;L001', 'SIT003', 'DIQ-SME', TRUE, 'DIQ umpire', 'Reviewed by our umpire on 2026-10-25. Sean''s coaching story, anonymized: no names, team, league or year. Keep it that way. Confirm wording.');
